/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250317-3","meetingId":"r07-c-budget","date":"2025年3月17日","dateIso":"2025-03-17","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時２２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"よって、発言の取消しを許可することに決定いたしました。 なお、まつざわ委員の発言につきましては、後刻、記録を調査の上、措置することにいたします。 それでは","agenda":"よって、発言の取消しを許可することに決定いたしました。 なお、まつざわ委員の発言につきましては、後刻、記録を調査の上、措置することにいたします。 それでは","exchanges":[{"speaker":"西村委員","kind":"質問","question":"３８７ページ、特別支援教育費で、ＬＤ学習障害、３７５ページ、家庭教育学級、３９３ページ、児童・生徒用タブレット端末等運用、時間が許せば３８７ページ、メタバースを活用した不登校支援事業で、教育版Ｍｉｎｅｃｒａｆｔについて順次伺ってまいりたいと思います。このことについての経緯を伺います。","respondent":"柏木学務課長","answer":"児童・生徒タブレットのＹｏｕＴｕｂｅの規制についてです。タブレットでは、これまでは子どもたちが主体的な学習ができるよう、一部制限して、ＹｏｕＴｕｂｅの視聴を利用可能としてまいりました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西村委員","kind":"確認","question":"これまでの利用時間の制限がどのようなものだったのかを伺いたいのですが、完全規制の判断をするまでに、学校現場と状況確認や協議は行っていただいたとおっしゃっていただきましたが、完全規制に関して学校現場の声にはどのようなものがあったのか伺います。","respondent":"柏木学務課長","answer":"規制する前ですけれども、ｉＰａｄでスクリーンタイムといって、時間制限等をできる機能がありますので、そちらを使用して、各ご家庭で対応をお願いしていたところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西村委員","kind":"質問","question":"既にこの１か月ぐらいで、授業や調べ学習への影響が出ていると伺っています。保護者の方からは、全面禁止はネットリテラシーが身につかないのではないかという声がありまして、せめてこのような学校内での活動に不具合が出ていることは、早急に対応できないかと思いますが、伺います。","respondent":"丸谷教育総合支援センター長","answer":"先ほどもありましたが、必要なものについてはフィルタリングを解除できるようにしておりますので、そういった対応で当面は続けていけたらと考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西村委員","kind":"質問","question":"少し、自由度が子どもたちの中でなくなってきているというのを、様々な声からも感じておりますので、保護者の方々からこの１か月間、ＹｏｕＴｕｂｅの利用停止についてどのようなお声が届いているか、改めて伺いたいと思います。例えば、持ち帰らないだけでも、おうちの中でのコントロールはできるようになってくると思いますので、そういった対応もこれから段階的にできないのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"この間の保護者の方からのご意見というところですけれども、例えば不登校支援を行っているＨＥＡＲＴＳからは、保護者から、ＹｏｕＴｕｂｅの制限がかかって、昼夜逆転の様子が変わったということで、一定程度ご理解というか。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西村委員","kind":"質問","question":"せっかくスクリーンタイムということもできたわけですから、もう少し保護者の方々の家庭教育も必要ではないかと思っています。次に、ＬＤ、学習障害について伺ってまいりたいと思います。そして、現在、特別支援学級や通級指導学級、特別支援教室に通う児童・生徒の中で、学習障害と言われる児童・生徒がどれぐらいいらっしゃるか、伺えればと思います。","respondent":"唐澤特別支援教育担当課長","answer":"現在の特別支援教室や特別支援学級にお子さんが通う割合ですが、まず特別支援教室については、学習障害をはじめ、４つの障害種別のお子さんを対象として指導しているところですが、次年度に向けては、約７００名のうち３０名のお子さんが。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西村委員","kind":"質問","question":"特に近年広がりのあるＩＣＴツールを積極的に導入しておられることもあると思いますので、それぞれの障害に合わせてどのような学習教材が導入されているか、伺いたいと思います。それぞれのお子さんに合った学習支援、テストを行うときの支援の仕方なども、学校での現場で対応を柔軟にされていると思いますので、その辺りを伺えればと思います。","respondent":"唐澤特別支援教育担当課長","answer":"教材等についてですが、まず読み書きアセスメントを活用する中で、例えば読むことに課題があるお子さんについては、ラインなどを引いたり、それがもちろんＩＣＴを活用しながらということもありますが、直接的な支援であったり、読むことを必ずしも主訴としないのであれば、代読。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西村委員","kind":"質問","question":"どうして勉強ができないのかと怒られ続けるお子さんもいらっしゃいます。例えばですが、品川子育てメッセのような既存イベントを活用して、ＬＤに関する相談ブースを設けるなど、それぞれの学びを止めない支援をぜひともお願いしたいと思います。次に移ります。次が、家庭教育学級について伺いたいのですが、事務事業評価ではＣ評価だったと思います。はその理由をお聞かせください。","respondent":"舩木庶務課長","answer":"こうした中で、今、ＰＴＡの方を中心に、家庭教育委託学級というところを実施しておりますけれども、実際にテーマを企画する段階から、どのように設定したらいいのか、どういうふうに考えたらいいのかというところを悩まれるようなケースもありますので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西村委員","kind":"質問","question":"以前、この件で質問させていただいたことがありまして、そのときには、ＰＴＡはあくまで保護者主体であるからというようなご答弁を頂いております。区で推奨する講座があると、１つ、目安になると思いますし、ＰＴＡの負担軽減にもつながっていくだろうというのは私も思いますので、どのような講座を今検討されているか伺います。","respondent":"舩木庶務課長","answer":"あるいは給食の試食などを通じて、ぜひ各ご家庭にも給食の重要性を感じていただいて、そういった給食から学ぶ知識をぜひご家庭でも習慣づけていただく、やはり基本的な生活習慣の形成に関することといったところのテーマが、どのご家庭にも必要な支援ではないかと捉えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"西村委員","kind":"提案","question":"最後に、教育版Ｍｉｎｅｃｒａｆｔですけれども、メタバースに登録していても入ってこないという児童・生徒が多くいると思います。子どもたちが楽しいと思えることが重要だろうと思いますし、メタバース内で教育版Ｍｉｎｅｃｒａｆｔ大会を開催できたら、子どもたちが面白がって入ってきてくれるのではないかと思いますが、ご見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"これまでも、クイズ大会や国際交流イベントなど、人集めに努めているところですけれども、今ご提案いただいたＭｉｎｅｃｒａｆｔの大会等も視野に入れながら、次年度、引き続きログインができるような状況をつくっていきたいと考えます。","voiceIndex":21,"id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"来週、ウェルビーイング・ＳＤＧｓ推進ファンド事業を採択した区内事業者が、Ｍｉｎｅｃｒａｆｔのリアルイベントを大崎で開催されると伺っております。Ｍｉｎｅｃｒａｆｔは、地域の課題解決や歴史文化の学習にも活用が可能ですし、例えば区の地域資源をテーマにしたワールドを作成するというようなこともやっていけると思いますので、ぜひともご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"おはようあります。３７５ページ、就学事務費からインターナショナルスクールについて、３９９ページ、給食運営費、３９１ページ、図書取次施設運営、そして時間があれば、３８５ページの不登校対策事業費についてもお伺いしたいと思います。就学事務費から、インターナショナルスクールについてなのですが、昨年の決算委員会で、インターナショナルスクールについての質疑を行わせていただきました。","respondent":"柏木学務課長","answer":"ただ、個別にお話をお伺いしまして、個別に対応していたところではあります。それで、これまで様々検討してまいりましたが、令和７年度からは原則、認めるべく、現在、準備を進めているところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"新妻委員","kind":"確認","question":"令和７年度からは、インターナショナルスクールに通っても、区内の学校、それぞれの地元の地域の学校に在籍扱いとするということでご対応いただけるということでよろしいでしょうか。もう一度確認です。","respondent":"柏木学務課長","answer":"委員からございましたとおり、通学区域の学校に学籍を置くということで、準備を進めております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"令和７年度からですので、また保護者に対するお知らせも漏れなくしていただきますように、よろしくお願いいたします。続きまして、給食運営費から伺ってまいります。食育も含め、給食に関する児童・生徒への学びの場の現状についてお伺いいたします。学校の教職員、そして栄養士をはじめ、調理師、また給食に関わる方へは、新たなこの給食の導入についてどのような説明がされるのでしょうか。お伺いします。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"今回の有機農産物等も含めてそういった取組が進んでいくものと考えております。私からは、栄養士または調理師等への対応ですけれども、これまで各学校で給食業務を担ってきました栄養士・調理師への対応や配慮ですけれども、予算案のご議決を頂きましたらば。","voiceIndex":29,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"この区民の方のお声は、オーガニック、イコール、おいしい給食などという、決めつけたようなことを子どもたちに伝えていくということは、違うのではないかという心配のお声であります。学校の給食に関わる方、また学校の食に関わる教えの場の中で、子どもたちにそういうイメージを与えるような発言があるのではないかというところの心配が少しあるようであります。その点についてはいかがでしょうか。","respondent":"柏木学務課長","answer":"決して、慣行農業・農産物を否定しているものではございません。あくまでも、環境負荷の小さい食材を提供していくということで導入を決めたものです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。図書取次施設設置運営要綱第２条には、「区民への図書サービスの利便を図るため、施設を置く」とありますが、今後の取次施設設置について、区のお考えをお伺いします。ぜひ、東京都競馬株式会社とも連携していただきながら、区民への図書サービスの利便を図るためとの目的の下、勝島地域、また区内全域への図書機能を持つ施設設置をご検討いただきたいと思いますが、いかがでしょうか。","respondent":"河内品川図書館長","answer":"お話のありました、勝島地域にお住まいになられている方というところで、南大井図書館、八潮図書館が最寄りだと思うのですが、利便性向上のために、さらに今後も様々な機会を捉えまして。","voiceIndex":34,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"勝島地域に限らずですけれども、図書機能は区内全域にあることが望ましいと思いますし、図書に触れている方というのは結構いらっしゃいます。取次の場所がいろいろなところに点在するということで、区民への利便性も向上されますので、ぜひまた拡大の検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、３８１ページ、教職員支援経費、３８３ページ、市民科・各教科充実経費について伺います。「性的同意について学校で教えてほしい」と考える生徒の割合が７８％という結果となっておりました。インターネットやＳＮＳよりも、学校のほうがこの教育の主な情報源となっており、性的同意について学校でしっかりと教えてほしい、正しい知識を身につけたいというようなお話が出ております。","respondent":"丸谷教育総合支援センター長","answer":"性的同意についてのご質問です。小学校・中学校など、義務教育段階の児童・生徒に対しては、生命（いのち）の安全教育というところで進めているところです。この中で、嫌がることをしないということを前提に相手との関係性を築いていくという学習を行っているところです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"もう少し突っ込んでしっかりと、教育として取り入れたほうがいいのかなと考えています。「性に関することについて相談できる人がいない」と回答した方が５２％となっておりました。性に関することを相談できるのは家族・友人が多く、学校現場での相談先が不十分です。相談しやすい環境づくりについても要望いたしますが、区の現在の対応について、また今後の課題を含めた対応についてもお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"児童・生徒の相談窓口というところですが、確かに今、スクールカウンセラーが週１回、また保健室に養護教諭が常駐しておりますので、性的な相談に限らず、何か相談したいことがあれば、相談できる体制というのをつくっております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"「性的同意を学ぶ上で学校に求めることは何ですか」と聞いたときに、「学校の先生が性的同意について正しい知識を持っていてほしい」、また、「親身になって相談に乗ってくれるとうれしいです」というようなお話を聞いております。教員が生徒の悩みに親身に対応できるように、心理的支援やカウンセリング技術の研修を受ける機会を増やすよう要望しますが、区の見解についてお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"研修体制についてですけれども、教育相談の研修を例年夏に、教員を対象に行っております。この中に、そういった多種多様な相談に対応できるような人材育成というものは広げる必要があると思いますので、今後検討していきたいと考えております。","voiceIndex":42,"id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ教員の方々への指導というところでも前向きに取り入れていただくように要望いたします。区立学校における２０２４年の外部講師、また助産師・産婦人科医を招いた授業の実施の有無について伺います。東京都の取組なども活用しながら品川区での性教育をさらに発展させるよう要望いたしますが、今後の取組についてもお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"２０２４年度につきましても、前年度に引き続きまして、浜川中学校でライフスキル講座を実施しております。次年度につきましては、東京都の事業を活用いたしまして、浜川中学校に加え、東海中学校で、外部講師を招いた性教育を実施する予定です。","voiceIndex":44,"id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"浜川中学校で継続されたということ、また１校、新たに加わるということで、大変うれしく思っております。この取組をしっかりと品川区全体に広げていただきたいと考えています。市民科検討委員会経費というものが、新しく次年度予算として入っていますが、この中で、子どもたちのこういったご要望、ご家族のご要望を受け入れられるような、届けられるような機会はあるのかということについても伺います。","respondent":"丸谷教育総合支援センター長","answer":"区立学校全体への広がりというところですけれども、次年度、２校で実施させていただいて、その様子を見ながら、いいものであれば徐々に広がりが出てくるものと捉えております。状況につきましては、広く周知できるようにしたいと思います。","voiceIndex":46,"id":"exchange-021"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひこちらの検討委員会でも、保護者の方、また子どもたちの声をしっかりと取り上げていただきたいと要望いたします。次に、教職員支援経費に関連して質問をします。２０２３年の結果ですが、新規採用教員のうち１年以内に離職した教員の割合が４.９％に上った。これは、３年連続増加。これは２０２３年の結果ではありますが、品川区での現状についてお聞かせいただきたいと思います。","respondent":"中谷指導課長","answer":"各学校でそういった職場づくりが推進できるように、教育委員会としても、教職員へどのようにサポートしていったらよいのかという視点での管理職への助言や学校への人的支援を、これからも充実していきたいと考えています。","voiceIndex":48,"id":"exchange-022"},{"speaker":"ひがし委員","kind":"質問・要望","question":"特に、病気を理由に自己都合での退職というものが多いと、この記事には載っておりました。しっかりと指導というところ、またその環境づくりを行っていただきたいと思います。今ご答弁でもありました人的支援についても取組を強化していただきたいと思います。今年度、エデュケーション・アシスタント増員、また副校長補佐の配置についても、変化等があればお聞かせください。","respondent":"中谷指導課長","answer":"副校長を複数配置しております義務教育学校は最大で３人というところになっておりますが、こちらも、副校長業務も人数分、多くなるというところを見越しまして、複数配置の副校長補佐の配置を予定しているというところになります。","voiceIndex":50,"id":"exchange-023"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほどもお話ししましたように、採用をせっかく入れてもなかなか続かず辞めてしまうというふうになると、せっかく学校として取組をしてきたのに、なかなかそれが広がっていかないというようなことがあると思いますので、新しく入ってきた方々へのメンタルフォローというところも、しっかりと区としても計画を立てていただきたいと思いますが、その点はいかがでしょうか。","respondent":"中谷指導課長","answer":"さらに来年度は中学校にも広げようという東京都の計画がありますので、併せて区も一緒にやっていくということで、相談ができて声を出しやすいという環境を整えてまいりたいと思います。","voiceIndex":52,"id":"exchange-024"},{"speaker":"ひがし委員","kind":"質問・要望","question":"教職員の方々が安心して働ける環境づくりをしっかりと意識して取り組んでいただきたいと考えていますし、教職員の方々が心にゆとりを持つことで、先ほど言いましたように、子どもたちの相談にも真摯に向き合えるかなと考えています。引き続き取組を強化していただきますよう要望いたしまして、私からの質問は終了とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"３８１ページ、いじめ防止対策費、３８５ページ、不登校対策事業費を伺います。年々増加する不登校件数ですが、それだけ学校が子どもにとって、安全に楽しく学べるところになっていない反映なのだと感じています。昨年度は、児童は３８１人、生徒は４１８人、合わせて７９９人でした。今年度は残り僅かなのですが、直近現時点での今年度の不登校の児童・生徒数はそれぞれ何人なのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"現時点での暫定の人数となりますが、小学生、児童が４１１名、中学校、生徒が３７４名、合わせて７８５名の不登校の児童・生徒数となっております。","voiceIndex":56,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"不登校になると、本人もそうですし、親がまずとても不安になり、どうしたらよいかと情報を求めます。幾つか要望したいのですが、１つ目は、サイトにたどり着けない問題なのですが、検索エンジンで「不登校」・「品川」で検索すればサイトは出てくるのですが、肝心の品川区のホームページからは、検索してもヒットしませんし、カテゴリーからたどってもたどり着けないということで、ここは改善を要望します。","respondent":"丸谷教育総合支援センター長","answer":"ガイドブックのプリントアウトができないというところですけれども、イラストの版権等の観点から、印刷ができないような仕様となっております。","voiceIndex":58,"id":"exchange-027"},{"speaker":"安藤委員","kind":"提案","question":"これは要望です。新年度予算が可決された後には、これが掲載されると思うのですけれども、サイトやガイドブックにも、区の上乗せを含む経済的支援があるということが伝わるように、記載の工夫をお願いしたいと思いますが、まず１点、いかがでしょうか。ポータルサイトやガイドブックで、区内の不登校の親同士の交流の機会、親の会を紹介することを提案したいと思います。それぞれ伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"フリースクールの助成につきましては、予算が確定しましたら、サイトに掲載する予定です。ガイドブックの紙面の更新につきましても、時期が来ましたら併せて改訂のときに載せられるようにしたいと考えます。","voiceIndex":60,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は「おや親カフェ」には参加したことがあるのですけれども、すごくいい集まりなのです。それは要望したいと思います。次に、いじめなのですが、まず一昨年度と昨年度、さらに今年度の直近の、いじめ認知件数と重大事態の件数を伺いたいと思います。重大事態のうち、調査が終了したものは何件で、うち当事者が「公表希望なし」で調査内容が報告されなかったものは何件か、伺います。","respondent":"丸谷教育総合支援センター長","answer":"いじめの重大事態の件数ですが、令和５年度、１４件のいじめの重大事態を認定しております。そのうち調査が終了しているものは１３件で、その１３件のうち、非公表となっているものが１０件、現在確認中のものが３件となっています。","voiceIndex":62,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかし、報告書が「公表希望なし」とされ、何が起こったのか、一切示されていないのが現状です。今後の対策の手がかりがないと思いますので、要望したいのは、個人情報に配慮しつつ、可能な形で議会・区民に報告するよう求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"私からは、３７２ページ、教育費全般、教育無償化の影響についてお伺いいたします。３８９ページ、図書館運営費、電子図書館に関連して質問します。そして、効果検証をしっかりとしていく必要があると考えております。東京都も、私立高校も含めて実質、高校は無償化になっているので、東京の今の状況と、品川区の状況というのは、今どういった状況なのでしょうか。教えてください。","respondent":"丸谷教育総合支援センター長","answer":"都立高校と私立高校の関係性というところになるかと思います。現在、都立高校の一般入試まで終わっている段階ですけれども、複数の学校で定員割れというような状況は、他自治体と同様に出ているというところで把握しています。","voiceIndex":66,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"中学３年間は、授業料の自己負担がありますけれども、結局、高校３年間は無償となりますので、やはり、ではもう中学３年間の負担を確保しても、私立の中高一貫校を受験しようかなということが起きてしまうのではないかということを懸念しております。今始まったばかりですけれども、その辺りの状況というか、保護者からのお声などは把握しておりますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"中学の受験率については把握してはおりませんけれども、昨今、中学受験が首都圏を中心に加熱しているというのは、報道でも我々は把握しています。","voiceIndex":68,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのうち、私立の中学校も無償化しろ、小学校まで無償化しろなどという話になってしまうかもしれませんので、しっかり今のうちに、そうした公立離れの対策というのをやっておく必要があるのかなと思いますけれども、その辺りのご見解と、あと、こうなってくると、そもそも公教育とは何だっけという話になりますので、公教育の意義・必要性の観点から。","respondent":"中谷指導課長、柏木学務課長","answer":"地域性を活かした、その地域でしか展開できない教育を、保護者・地域が一体となって行うことで、次の世代への子どもたちの育成を行えることがとても大事であり、それを今実施していると認識しております。私立中学の入学の件ですけれども、数としては、教育委員会で把握しています。私立中学につきましては、年々、増加傾向ということがあります。","voiceIndex":70,"id":"exchange-033"},{"speaker":"筒井委員","kind":"確認","question":"無償化の影響というのは今後出てくると思いますので、しっかりとその辺りは注視して、対応をしっかりとお願いしたいと思います。続いて電子図書館に移りますけれども、品川区立図書館には電子図書館を導入されていて、今、図書館流通センターのサービスを使用されていると思いますけれども、図書館流通センターのＬｉｂｒａｒｉＥというシステムを使っているのでしょうか。その辺りをまず確認させてください。","respondent":"河内品川図書館長","answer":"おっしゃるとおりのシステムを採用しています。","voiceIndex":73,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。ぜひ電子図書館を進めていっていただきたいと考えています。教育委員会の事務事業評価でも、利便性が高いと。企画経営部の事務事業評価の目標が、令和１１年度には５,５００蔵書、貸出し件数を増やすということで、今、年間１,１００冊の蔵書を増やしていかないといけないペースだと思いますけれども、現在の進捗状況と、またそれについて課題がありましたらお知らせください。","respondent":"河内品川図書館長","answer":"一方で子ども読書推進計画におきましては、一層のデジタル化の社会の推進を踏まえまして、こういったものを拡張していくというところで進めていく予定です。","voiceIndex":75,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"単価が高いという問題はありますけれども、それと紙とのバランスを今後うまく取っていただいて、ぜひ拡充を進めていっていただきたいと思います。ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"３７５ページの就学事務費、３８１ページの教職員支援経費から質問いたします。児童や家庭の情報、緊急連絡先、健康状態の確認、予防接種状況やアレルギーの有無などなど記入して、学校の事務室に持っていきます。これらの書類は、この後、学校でどのように管理していくのでしょうか。例えば、エクセルに入力してデータ化したり、システムへの入力をしたりしていくのでしょうか。","respondent":"柏木学務課長","answer":"保管につきましては、施錠できるキャビネットに保管し、必要な際には鍵でそれを開けて出し入れして、また戻すという形で、きちんと管理しているものであります。","voiceIndex":79,"id":"exchange-037"},{"speaker":"せらく委員","kind":"確認","question":"データ入力についてはどなたがされるか、お聞きしたいと思います。確認なのですけれども、現状でも、この手書きの地図というのは、Ｇｏｏｇｌｅマップをプリントしたものにルートを記入して、貼り付けて提出することも可能なのでしょうか。具体的なことをこれまで申し上げましたが、入学手続の一部になるかとは思いますが、デジタルの活用についてはどのような方向であるか、お聞かせください。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"それと、オンライン化またはデジタル化ですが、こちらは学校等の相談等にもなりますけれども、すぐできるもの、できないものもあるかと思いますので、学校等とも確認しながら、できるだけ。通学経路の提出についてですけれども、Ｇｏｏｇｌｅマップ等からプリントアウトして、その上に手書きで記入していただくことも可能となっております。","voiceIndex":81,"id":"exchange-038"},{"speaker":"せらく委員","kind":"質問・要望","question":"その中の１例で、放課後、集合住宅のロビーで子どもたちが騒いでいるのを見かけた地域の住民が、学校へ電話して、学校は現場を確認して注意などの対応を行った。こちらはいかがでしょうか。電話委託は、入電後、代理で会話をし、お話の要件を教職員にフィードバックすると、以前、委員会で確認いたしましたが、フィードバックの方法としては、メールやメッセージアプリなどでやられているのでしょうか。","respondent":"中谷指導課長","answer":"まだこれらのスタッフの配置を行ったばかりではあるのですけれども、今後それぞれの方に業務に慣れていただくことで、電話対応なども担任の代行として、内容によってはそのスタッフだけで対応を完了できるようなシミュレーションも、今後できるようになると考えております。","voiceIndex":84,"id":"exchange-039"},{"speaker":"せらく委員","kind":"質問・要望","question":"確かに、勤務時間内のお電話は教職員が対応するものというところも１つあるかと思います。ツールを導入することでトラブルになりづらいのではないかと思いますが、その点はいかがでしょうか。","respondent":"荒木学校施設担当課長","answer":"それぞれ、現状では、利用実績を確認できているのは数校程度です。今後、必要性が高まれば、さらなる導入を進めていく考えです。","voiceIndex":86,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３７９ページ、生徒指導対策等経費、３８３ページ、市民科・各教科充実経費、３８５ページ、品川英語力向上推進プラン、不登校対策事業費についてお伺いいたします。１点目に、生徒指導対策等経費についてお伺いいたします。生徒・児童に今後、そのような方法で英語力を身につけてほしいと考えますが、区教育委員会のご見解をお伺いいたします。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"現在、毎日の健康観察をタブレット上で行っており、相談したいことがあればＳＯＳを出せる仕組みを整えています。状況に応じて関係諸機関とも連携して、支援につなげてまいります。スタッフも学級担任だけではなく、ＡＬＴ、ＪＴＥ、英語科専門の都や区の正規教員等で、他地区にはない層の厚さで熱心に取り組んでおりますので、ぜひ期待していただきたいと考えています。","voiceIndex":90,"id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"教職員や保護者など、大人の理解促進を含めて普及啓発が不可欠であり、非認知能力を育成する上で欠かせない遊びを学校で推進・啓発してほしいと要望いたしますが、区教育委員会のお考えとその方法についてもご見解をお伺いいたします。自殺予防の観点を念頭に置きながら進路指導をお願いしたいと思いますが、不登校児童・生徒の卒業後の進路について区教育委員会のご見解をお伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"遊びについてですけれども、他者と付き合う能力や、自分の感情をコントロールする能力、何かを完成させたときの達成感などを育むことができると認識しておりまして、休み時間や外遊び、室内遊びの時間に加えまして、生活科での昔遊びに親しむ時間や、また中学校等では。","voiceIndex":93,"id":"exchange-042"},{"speaker":"澤田委員","kind":"提案","question":"浅間台小学校についてお伺いします。もし屋内プールではなく、屋外へ建設される場合は、熱中症リスク軽減のためにも、高橋伸明委員から以前提案があったように、直射日光の影響を受けないような、日陰をつくるための手動のテントのようなものや、ひさしの設置など、実施設計がなされる今ならば、まだ検討可能ではないかと考えますが、区の見解をお聞かせください。","respondent":"荒木学校施設担当課長","answer":"浅間台小学校については、法規制や敷地条件が厳しく、屋内プールや屋根つきの屋外プールを計画することが困難ではありますが、ご提案いただいた手動のテントや遮光ネットなどを含めて、プール全体を覆うことのできるものを検討し、設置を進めてまいります。","voiceIndex":96,"id":"exchange-043"},{"speaker":"澤田委員","kind":"質問・要望","question":"子どもたちの安心安全のためにも、水泳の授業を安心して受けられるように、設置の検討をどうぞ進めていただければと思います。新しい校舎になり、機能的で現代的な校舎になることは大変喜ばしいことではありますけれども、旧校舎のレガシーとでもいいましょうか、記憶・歴史をつなぐ意味でも、ぜひ門柱の活用を望みますが、区としてのお考えをお聞かせください。","respondent":"荒木学校施設担当課長","answer":"こちらは、何十年間も児童の登下校を見守ってきた門柱です。安全性を確認した上で保存を進めてまいります。その活用方法につきましては、今後の設計で検討し、同窓会の代表者などが集まる建設準備懇談会などで、区からご提案させていただきたいと思います。","voiceIndex":98,"id":"exchange-044"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、就学支援費についてお伺いいたします。無償といえば、卒業証書は卒業生の皆さんにお渡ししておりますが、卒業証書入れについては学校により様々で、学校が支払っている場合もありますけれども、卒業生の保護者から徴収してお配りしている学校も多々あるとお伺いしております。証書入れを一律、区が負担していただくことを要望いたしますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"卒業証書入れのお問合せですが、多分、多くの学校が今、ＰＴＡで卒業対策としてお金を積み立てて、その中で購入していると認識しています。ＰＴＡからは、これまでそういうご要望はなかったものですから、ＰＴＡ等々で声も聞きながら、今後検討できればと考えています。","voiceIndex":102,"id":"exchange-045"},{"speaker":"澤田委員","kind":"確認","question":"そういうご意見を聞いていなかったということですけれども、私は結構聞いていて、いろいろ地域差などあるのかもしれませんけれども、もしよければ、ぜひまず聞いていただくというか、広く皆さんのお声を、聞いてくださっているとは思うのですが、またご確認いただければと思います。検討をどうぞよろしくお願いいたします。最後になりますけれども、オンライン英会話レッスンについてお伺いします。","respondent":"中谷指導課長","answer":"一貫教育を進めていく中で、９年間の中での英語の学びの滑らかな接続を図ることを目指しております。中学生で、現在、授業時数に対して学習量の多さや質の深まりの両面から、達成していく上での目標がやや高いというところが確認されております。","voiceIndex":104,"id":"exchange-046"},{"speaker":"澤田委員","kind":"質問・要望","question":"は成果や課題の洗い出し・修正などを経て、全校へ進めていただきたいというところですけれども、６年生になると、中学受験を控えているお子さんも多くなる中、今後５年生へとさらに対象年齢を引き下げ、子どもたちが精神的に余裕ある状態でオンライン英会話を始めることができればとも思いますが、区としての方向性・考え方を教えてください。","respondent":"中谷指導課長","answer":"９年生のゴールで２,５００語を身につけなければいけない。この中で、７年生から急にではなくて、やはり５・６年生から、しっかりと段階的にやっていくというところで、しっかり１つの研究を効果検証してまいりたいと考えています。よろしくお願いします。","voiceIndex":106,"id":"exchange-047"},{"speaker":"つる委員","kind":"提案","question":"３８７ページ、フリースクール等利用料助成、３８７ページ、マイスクール昼食費、３９９ページ、標準服購入費用保護者負担軽減事業、３７７ページ、就学支援費、３８９ページ、図書館運営費、３９５ページ、学校図書館経費、３７９ページ、平和に関する指導資料作成費について伺ってまいりたいと思います。フリースクールの助成につきましては、昨年の第２回定例会で提案させていただきました。","respondent":"丸谷教育総合支援センター長","answer":"フリースクールの利用助成を受けるための申請方法についてですけれども、まず東京都が実施しているフリースクールの助成を受けましたという証明をもって、区に申請していただくような手続を考えております。具体的な方法につきましては、現在、検討を進めているところです。","voiceIndex":110,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"保護者の方がそれぞれから助成を受けられるということは、これはこれで保護者の負担軽減になるというところで、本当に大きな課題というか負担の軽減の一つかと思います。それから、マイスクール昼食費に関連してなのですが、２０２３年１２月に会派で緊急要望させていただきました。その中でマイスクールの給食についても要望させていただいて、そこを今回反映していただいたのかとも理解しております。","respondent":"丸谷教育総合支援センター長","answer":"民間団体等に通う児童・生徒への支援につきましては、様々、課題の整理を今後していく必要があるかと思いますので、そういったものを整理しながら検討できればと考えているところです。","voiceIndex":112,"id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"引き続き、質問を重ねていきたいと思います。次に標準服に関してですが、ここについても、会派からも様々な形で質問や提案等、また要望等させていただいて、来年度実施していただくということであります。これは、買ったときにコストオンされているということで、ただですと言っていただいて、それはそれで助かったのですけれども、この辺の仕組みについてはどうでしょうか。","respondent":"柏木学務課長","answer":"そこは各販売店のサービスの考え方になってくるのかと考えています。転入生の対応等につきましても、今後検討させていただきたいと考えています。","voiceIndex":114,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな、そもそも論の話なども、品川区内の保護者の方々や、一般的にも全国的にも、制服そのものがどうなのだろうかなどという声もあります。これは報道ベースでもありますし、区民の方からも伺いました。その活用について１つ伺いたいと思います。そういったことで書店がなかなか立ち行かないという部分もありますけれども、この辺りについて教えてください。","respondent":"河内品川図書館長","answer":"こういったコーナーに置くことによって、平和の尊さについて皆さんにお伝えするとともに、さらに特集展示というのも図書館はやってありますので、そういったところに置くなど、皆さんの目に触れやすいようにというところで。","voiceIndex":116,"id":"exchange-051"},{"speaker":"つる委員","kind":"意見","question":"区内の書店からの購入の流れがしっかりとあるということは大事なことかなと思います。処分・買い希望についても、また改めて質疑したいと思いますが、この観点も含めて、書籍の充実をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、３９３ページ、学校ＩＣＴ活用経費、３８８ページ、図書館費、時間があれば３８５ページ、不登校対策事業費、マイスクールについてお聞きします。最初に、学校ＩＣＴ活用経費についてお聞きします。","respondent":"丸谷教育総合支援センター長","answer":"懸念点といたしましては、姿勢が悪くなったり目が悪くなったりというところが、今、言われていますけれども、そういったところを、健康チェックも子どもたちが行いながら、注意しながら活用を進めているところです。","voiceIndex":120,"id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"様々なことを気遣いながら進めていっていただいているのかなと思います。確かに成長期の子どもの視力低下という、そこだけが少し気になっています。今、海外ではデジタル化からの脱却を進める国も現れており、スウェーデンでは今までの方針を変更して、令和５年８月の新学期からは紙媒体に戻して、デジタルデバイスの使用時間を削減しています。次は、紙のほうの質問で、図書館についてお聞きします。","respondent":"河内品川図書館長","answer":"年間８００回を超えまして、８,０００人以上の方にご利用いただいている状況です。こうした幼い頃からの習慣化なども含めまして、こういった課題に取り組んでまいりたいと考えているところです。","voiceIndex":122,"id":"exchange-054"},{"speaker":"おぎの委員","kind":"提案","question":"期間を設けたり、小さいときからの習慣化であったりなど、いろいろな工夫をされているのだということが確認できました。そこで本日は、子ども司書制度を提案します。全ての子どもたちが楽しく本に親しみ、豊かな心を育て、言葉を学び、感性を磨き、表現力・創造力を豊かにする読書推進活動として、希望する児童にこの子ども司書制度を提案しますが、いかがでしょうか。","respondent":"河内品川図書館長","answer":"子ども司書制度のことでお尋ねいただきました。矢祭町につきましては、平成２１年に全国で初めてというところで、これにつきましては、友人や家族に読書のすばらしさ、大切さを伝えるという目的で事業として始めたという認識です。","voiceIndex":124,"id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"ぜひご検討をよろしくお願いいたします。マイスクールについては、時間がなくなってしまいましたので、また別の機会にお伺いします。文部科学省の令和７年度の予算、今年度予算を見ましても、不登校対策（ＣＯＣＯＬＯプラン）関連事業で、学びの多様化学校の設置促進や、新規で校内教育支援センター支援員の配置補助金が計上されるなど、社会全体で不登校問題に向き合う必要性を感じています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３７９ページの区教員経費に関わって、担任の欠員、教員不足解消について伺います。今、教員不足が深刻な状況になっていると思います。子どもたちの教育環境が深刻な状況になっています。一般質問では、担任が不在となって管理職が入った学級数が、令和６年度、延べ２２学級、令和７年度、延べ１６学級との説明でした。担任が不在になった理由は何でしょうか。人数も併せて伺いたいと思います。","respondent":"中谷指導課長","answer":"担任がいない、欠員という状況が、今申し上げた病気休職や退職、産育休代替等の理由による欠員というのが、義務教育学校も含めて、小学校では１４名、中学校では５名、計１９名ということになっておりまして、昨年度よりも減少傾向にあるです。","voiceIndex":128,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"１９クラスですか。担任が不在となった学校があったということで、そのうち１６学級が管理職で補充されたということだと思います。その仕組みがもしないのであれば、必要になってくるのではないかと思うのですけれども、いかがでしょうか。それと、メンタルの面で休業や退職などした教員の人数を伺いたいと思います。","respondent":"中谷指導課長","answer":"１つ目のご質問で、産休育休代替の補充というところについてですけれども、こちらは比較的、例えば今現在など次年度の開始が待たれる中で、４月１日からの補充というのは非常にスムーズにできている傾向がある一方で、年度途中で欠員となったときの補充というのが。","voiceIndex":130,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"担任がいないということは、やはり子どもたちも不安にさせますし、教育環境としてもよくないと思うのですけれども、補充できなかった場合に、子どもたちにどういった影響があると区では考えているでしょうか。伺います。やはり、そういった教員の多忙化を解消していくためには、今、授業が多過ぎるのではないかと思うのですけれども、教員１人当たり、１日何こま授業を持っているのか、伺いたいと思います。","respondent":"中谷指導課長","answer":"それから２つ目といたしまして、先生方がどのぐらいの授業のこまを持っているのかというところですけれども、今のご質問へのご回答にも関連していくのですけれども、おおよそ１日の時間割というのが、大体４時間から６時間の中で推移しているというようなところになってあります。","voiceIndex":132,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の固有教員が品川区はいますので、充てていくということをぜひ考えていただきたいと思います。実際、欠員が補充されても、ある義務教育の学校では、専科の先生がなったということで、理科や社会が教科書を写すだけで、実験も十分にできなかったりということや、算数の少人数学級も大きな体育館でやったりということもあって、実態もつかんで改善していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、３７９ページの生徒指導対策費と、３９９ページの学校給食食材費から伺います。私も同様に考えております。一方で、実は私は２０２２年６月の一般質問で、学校給食の質の確保を求めて質問しております。給食の質の向上を目指すためにも、区として食材の産直先を増やすことを検討すべきと考えますが、見解を伺います」という質問をしております。そちらとの関係は今後どうなるのでしょうか。","respondent":"柏木学務課長","answer":"今回、有機農産物等の導入に当たっては、現在、地元の業者、多古町も含めてですけれども、丁寧な説明や意見交換を行いながら、市場の動向や現場の実態に耳を傾けながら、持続可能な発注・供給が図れるよう、方策を検討していくこととしています。","voiceIndex":137,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問・要望","question":"要するに、多古町との提携はどうなるのか。多分、それは納入先も決まっていると思うのですけれども、そういう関係性はどうなるのでしょうかということを伺いたくて質問したのですけれども、お答えいただきたいと思います。既に資料提供させていただきましたが、３月７日の日本農業新聞に品川区の学校給食のことが取り上げられております。これらの懸念にどのようにお答えになるか、伺いたいと思います。","respondent":"柏木学務課長","answer":"食材として全て賄えるのかというご質問ですけれども、まず今回、導入事業につきましては、有機農産物だけではなく、特別栽培の農産物も対象としていますので、こちらの資料に鑑みますと供給は可能と考えています。","voiceIndex":139,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"特別栽培の野菜も入れるということですね。私もこのご意見に賛成なのですけれども、いかがでしょうか。私の乏しい知識ですけれども、栽培を始める前に、２年でしたか、まず、その土地は農薬も化学肥料も使わないという、まずは土を育てて、そこから取り組むわけですから、それを求める以上は、有機栽培してくれたら徹底的に、私たちは消費者の立場で食べて支えるからということを伝えるべきだと思うのです。","respondent":"柏木学務課長","answer":"対象野菜についてですが、学校に野菜を納品しております複数の地元の既存の事業者より、円滑かつ持続的に本取組を進めるよう、様々なご提案を頂いており、市場の動向や現場の実態に耳を傾けながら、接続可能な発注・供給が図れる方策を検討してまいります。","voiceIndex":141,"id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"当初の有機野菜１００％みたいなところとは少し違ってくるのかなと思います。流通業者はいろいろな提携先も持って、手段もお持ちでしょうから、もしかして納入という意味では大丈夫かもしれないですけれども、これが産地に与える影響というところまで、ぜひ品川区としては考えていただきたいと思うのですけれども、その点については何かお考えがあったら伺いたいと思います。","respondent":"柏木学務課長","answer":"今回、導入を決めた件につきましては、政府が製作しております「みどりの食料システム戦略」の、２０５０年の日本の農業の在り方について耕地面積の２５％を有機農地とするという大きな方針に基づき、それを踏まえた有機給食の導入を推進する。","voiceIndex":143,"id":"exchange-064"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう一つ、生徒指導対策費から不適切指導について伺いたいと思います。昨年の決算特別委員会でも、不適切指導についての子どもたちに対する聞き取り調査の手法について伺いました。相談者は、今日私が教育費について質問するということを知っているので、具体的な事例を取り上げて、改善策を求めてほしいというのがご要望でした。不適切指導についても同様と考えていいのでしょうか。伺いたいと思います。","respondent":"中谷指導課長","answer":"いずれにしましても、そこを把握させていただいた上で、事案を、まず事実がどうなっているかというところを確認するということを、第一優先として学校に投げかけていくのですが、その際にどこまで学校に伝えていいのか、もしくは伝えることが不適切な。","voiceIndex":145,"id":"exchange-065"},{"speaker":"吉田委員","kind":"質問","question":"ご相談者からの質問はここまでで、私はこの事例を伺ったときに、これは絶対、教員の方にも何かカウンセリングというか、そういうものが必要な事例ではないかと思ったのです。被害に遭っていると思っている生徒から見れば不適切指導ですけれども、やはりこういうのは大体、教員の方へも何かフォローが必要だと思うのですけれども、その辺についてのフォローはどうなっているのか、伺いたいと思います。","respondent":"舩木庶務課長","answer":"ただいま委員のご指摘の部分も含めて、教育委員会では、健康管理の一環として産業医または看護師の健康相談を随時受け付けておりますし、あと、学校のリスクについて総合的な相談窓口も設定しています。","voiceIndex":147,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"３９２ページの学校教育費に関わって、修学旅行、学校給食の食材、災害時の学校給食室の活用、最後に大井囃子について伺います。修学旅行ですけれども、無償化ということです。この無償化は、中学３年生の修学旅行に限定なのかを伺います。私は、小学校の鎌倉遠足、林間学校、卒業遠足についても、大切な教育活動ですから無償化すべきと思いますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"今回ご提案しています修学旅行の無償化につきましては、９年生の修学旅行のみの無償化となっています。","voiceIndex":150,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"ですから、そこ限定ではなくて、小学校の鎌倉遠足、林間学校、卒業遠足についても無償化すべきと思いますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"そのほかの卒業遠足等につきましては、今後、必要に応じて、財源等を含めて検討されることと考えています。","voiceIndex":152,"id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"その他についても、対応も含めて検討ということですけれども、ぜひ義務教育の完全無償化と考えておりますので、少しずつ新たな学校の姿、自治体の姿に挑戦していただきたいと要望しておきたいと思います。その上で、多古町について、引き続き関係を持ちたいと答弁がありましたが、これは、切らない、契約を続けるという意味なのか、関係は続けるけれども契約は切るということなのか、伺いたいと思います。","respondent":"柏木学務課長","answer":"多古町の件ですけれども、これまでも給食食材の納入だけではなく、中学校の農業体験や、栄養士や調理員の見学交流会等も実施してまいりました。そういう、これまでの関係がありますので、多古町等につきましては、引き続き関係を持っていきたいと。","voiceIndex":154,"id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"食材の納入も含めて関係を保っていきたいということは、引き続き、多古町の産直センターから給食の食材を納入するということでいいのか、また、ぜひ交流も含めて継続・充実させていただきたいと思いますが、改めていかがでしょうか。","respondent":"柏木学務課長","answer":"繰り返しの答弁になりますけれども、食材の調達・納入を含めて、また、コロナ以降、なかなか交流ができなかったなどありますけれども、これまでの関係性については引き続き保っていきたいと考えています。","voiceIndex":156,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ地元業者を含めて、多古町との関係も含めて、継続・充実を改めて要望しておきたいと思います。次に、災害時の学校給食室の活用です。つまり、災害時における避難所の食事の質の確保へ、学校給食室の活用が国から言われております。給食の民間事業者との連携、そして訓練への参加、具体化を頂きたいと思いますが、教育委員会としては、いかがでしょうか。","respondent":"柏木学務課長","answer":"調理代行等の災害時等の対応ですが、給食の調理代行と、あと学校の栄養士の委託等、仕様で決めてございまして、品川区内で火災・自然災害等が発生した場合の対応については、あらかじめ学校と協議して対応に備えておくこと、また誠意を持って対応することとしていますので。","voiceIndex":158,"id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"いわゆる火災というのが、首都直下型大震災を前提にした災害時の対応なのですけれども、全ての学校で学校給食室の活用が、既に取決めがされているということでよろしいのでしょうか。","respondent":"柏木学務課長","answer":"災害時の前提として、給食室、水道・ガス等がどうなっているかという部分はありますけれども、当然、給食室が使える際については、あらかじめ学校と協議して対応を整えているということになります。","voiceIndex":160,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、大井囃子保存会についてです。大井囃子保存会の方から、品川区から補助金を頂いているが、ずっと金額が同じとのお話を伺いました。そして、４０年間、金額が変わらないわけですけれども、ぜひ文化活動にも保存活動にも光を当てていただいて、４０年間ですから、物価高も含めて、社会情勢に合わせて奨励金を増額していただきたいと思いますが、いかがでしょうか。","respondent":"舩木庶務課長","answer":"実際、現時点で金額自体の引上げはございませんけれども、所有者との良好な関係性の構築や、２３区に目を向けますと、この保護奨励金の額がかなり上位に位置づいておりますので、適正な支援が行われているのではないかという認識でおります。","voiceIndex":162,"id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"４０年間変わっていないということで、他区に比べて高いというお話もありましたけれども、私は森澤区長になり、様々な事業が進んでいると考えています。一方で、歴史や文化について区長が目指す姿はよく分かりません。介護施設でのお囃子や獅子舞。ぜひこういう活動にも光を当てていただいて、４０年ぶりにはなりますけれども、引上げを検討していただきたいと思いますが、最後にいかがでしょうか。","respondent":"舩木庶務課長","answer":"繰り返しになりますけれども、保護奨励費の金額自体の考え方については慎重に判断されるべきものであると考えております。ただ一方で、しっかりと文化財の活用・保護に当たっては、様々な場面で引き続き、ご紹介も含めて対応してまいりたいと考えております。","voiceIndex":164,"id":"exchange-074"},{"speaker":"えのした委員","kind":"質問・要望","question":"私からは、３８３ページ、ウェルビーイングの理解を深める学習、同じく３８３ページ、市民科検討委員会についてお伺いいたします。ウェルビーイングの理解を深める学習について。こちらは新規事業で、市民科の充実であります。所管は違いますが、会派からも要望していた中学生向け防災も新規事業になりますが、これらは全て市民科で実施するのでしょうか。概要などを含め、お聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"事業内容ですけれども、ウェルビーイングの理解を深める学習ということで、教材開発を、ウェルビーイングに造詣の深い講師の先生をお招きして学校に入っていただきながら、指導案等も作成して実施していくという事業となっています。","voiceIndex":167,"id":"exchange-075"},{"speaker":"えのした委員","kind":"確認","question":"ウェルビーイングの実現は、市民科含め、各教科で行うということで、市民科だけではないのかなというところを確認いたしました。そして、先生を招いて進めるということで、市民科での実施の内容があまり詰め込み過ぎにならないように、進めていただければと思います。先ほど先生を招くとあったのですけれども、これは学校の教員の方は教えたりしないのでしょうか。お知らせください。","respondent":"丸谷教育総合支援センター長","answer":"今回想定している講師については、学校の教員向けにも、研修会、校内研修を開いていただいて、先生方の意識も高めてもらうようなことを想定しています。","voiceIndex":169,"id":"exchange-076"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認が取れました。文部科学省は、日本の社会、文化的背景を踏まえ、日本発、日本社会に根差したウェルビーイングを、教育を通じて向上させていくことが求められると言います。教員の負担にもならないように進めてください。次に、市民科検討委員会について、先ほどの、ひがし委員の質問と重ならないようにお伺いいたします。こちらは新規の予算だと思いますが、詳しくご説明をお願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"市民科検討委員会の内容についてですけれども、平成１８年度より導入しております、品川区の独自教科、市民科について、導入から、次年度で２０年目を迎えることになります。","voiceIndex":171,"id":"exchange-077"},{"speaker":"えのした委員","kind":"質問","question":"もう２０年と、節目の年で振り返りということを理解いたしました。大変重要だと考えます。今後の方向性というのはどのような感じになりますでしょうか。お知らせください。","respondent":"丸谷教育総合支援センター長","answer":"教員アンケート、児童・生徒アンケート等も今考えているところです。学識経験者の意見等も踏まえながら、また地域の方や企業の方の意見等も含めて、今後の市民科のよりよい充実を目指して改訂作業を進めてまいります。","voiceIndex":173,"id":"exchange-078"},{"speaker":"えのした委員","kind":"提案","question":"アンケートも取るということで確認が取れました。次に、オリンピック・パラリンピック教育についてお伺いします。そこでお伺いします。オリンピック・パラリンピック教育について、デフリンピックの授業などは実施されていますでしょうか。大会のポータルサイトでは、教育ワークショップ型プログラムが様々ありますが、区は認識されていますでしょうか。こちらはご提案になります。いかがでしょうか。","respondent":"中谷指導課長","answer":"既に人権教育推進校の台場小学校で実施しておりまして、この成果につきましても今後、皆で共有を図りたいと考えています。","voiceIndex":175,"id":"exchange-079"},{"speaker":"えのした委員","kind":"確認","question":"取組があるとのことで確認が取れました。私も、この映像教材「みんなで応援しよう！東京２０２５デフリンピック！本当に今年第１回、パリ大会から始まって１００年、今回、第２５回、日本では初めての開催となりますので、子どもたちにも絶好の、よい教育の機会と捉えております。進めてください。そこでお伺いします。これから区は、市民科も含め、先端的な教育をどのように進めていくのかお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"そこで、市民科の一貫プランを通じた探究学習というものを、今、各校がプログラムを検討しています。そうしたものを含めながら、今ご紹介のあった先端教育というものも含めて各校で進めるとともに、それを教育委員会としてしっかりと支援していきたいと考えております。","voiceIndex":177,"id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３７５ページ、校外授業費、それから３８３ページ、ウェルビーイングの理解を深める学習という２点で質問をします。実際には移動教室で行っている人数とほとんど変わりがないので、実際の授業としては、それほどの違いというのが事実上はないと思っていますけれども、なぜ希望者ということになっているのか、その理由をお聞かせください。","respondent":"柏木学務課長","answer":"５年生の夏季施設のほうを希望にしている理由ですが、１つが、こちらは夏休み中ということになりますので、教育課程外、授業ではないということで、希望制としています。","voiceIndex":180,"id":"exchange-081"},{"speaker":"塚本委員","kind":"質問・要望","question":"先ほどもありましたけれども、来年、修学旅行が無償化になるという予算が計上されたという中で、この林間学校についても無償化の対象として考えていくというところを、移動教室についてもというところをぜひご検討いただきたいと思いますけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"今回、標準服と修学旅行を無償化させていただきました。様々、無償化の項目について検討した中で保護者の負担感が高いものを選ばせていただいております。ご提案の、ほかの校外学習につきましては、今後、財源とともに必要性についても検討していきたいと考えています。","voiceIndex":182,"id":"exchange-082"},{"speaker":"塚本委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。こういった品川区学校教育要領等と、今回の品川教育ビジョンは、それぞれ関係はもちろんあるものだとは思っていますけれども、どのような、それぞれの位置づけ、関係性があるのか教えてください。","respondent":"舩木庶務課長","answer":"大きくはそのような関係性であるものと認識しております。","voiceIndex":184,"id":"exchange-083"},{"speaker":"塚本委員","kind":"質問","question":"そういうことでいうと、教育大綱と教育ビジョンというのは、やはりそれぞれが同じような目的・位置づけになっているのかなとも、今のご答弁で感じました。その辺はどのように整理されているのか、お伺いします。","respondent":"舩木庶務課長","answer":"それを踏まえて、教育委員会では区教育委員会の教育目標や教育方針などということを定めております。","voiceIndex":186,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"教育ビジョンにおいては、学びの羅針盤２０３０ということで、人生というか子どもたちの将来を航海に例えている。教育というものが、人生における航海の羅針盤ということで、大変にすばらしい内容かなとは思っております。アンティシペーションというところにもつながるかと思いますけれども、そこについて最後にお伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"現場の教員に向けては、こちらの概要版を示すことで概要的なことは理解していただきながら、内容につきましては、教育課程の中に今回示されるビジョンを盛り込んでいくということで進めているところです。","voiceIndex":188,"id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私からは、３８３ページの市民科・各教科充実経費に関連してと、３８９ページの学校支援地域本部事業経費に関連してお願いします。品川区は、区の教育の一環として租税教育を行っていると思うのですけれども、どのような形式、形態で行われているのか、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"品川区立学校におきましては、毎年６年生と９年生において、社会科の時間に税理士会や税務署の職員の協力を得ながら租税教室を行いまして、税の仕組みや、税が社会に果たす役割について学習を行っているところです。","voiceIndex":191,"id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"租税教育なのですけれども、税務署の職員の方が出前授業をしていると思うのですけれども、その内容について区教育委員会と話し合われたり、内容について区教育委員会がチェックしたりというのはされていますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"各学校が税務署の職員の方と事前に授業の内容等は打合せをしているところです。東京税理士会が「租税教育のための実施手引き」を発行しておりまして、この中に入っている例示されているものを基に授業をやっていただいていると、教育委員会では把握しております。","voiceIndex":193,"id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"何かといいますと、１５分間ほどのアニメを見るのです。イギリスは財政拡大を５.４倍にして、経済成長を２.４倍と。国会でも今まさに税の使い方について話合いが行われているということで、やはり子どもの教育の上で非常に、税の使い方をもっとしっかり知ってもらうのが大事だと思うのですけれども、その辺は、ぜひもっと積極的に区に関与していただきたいと思うのですが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"頂いたご意見は、しっかりと税務署にも伝えまして、改善が図られるように、関係性を築いていきたいと考えております。","voiceIndex":195,"id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"次ですけれども、会計年度任用職員の令和７年度の採用選考がホームページに載っていたのですけれども、そこで、８職種ほどの募集がありました。その中で、ほとんどの職種が、時給や月額給与等に変更がないというところで、やはりこの物価高であるというところを踏まえると、しっかりとその分、賃上げなどしていかなくてはいけないと思うのですが、その辺のご見解というか、お伺いできますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問","question":"であれば、すみません。学校地域コーディネーターについて、ピンポイントでお伺いします。よろしいですか。こちらは時給が変わっていないということですが、スクール・サポート・スタッフに関しては時給が上がっていて１,４４８円になっているのです。学校地域コーディネーターは１,２５０円ということで、時給が学校地域コーディネーターのほうが低いのです。何か理由があれば教えてください。","respondent":"中谷指導課長","answer":"今回の募集に関して、報酬についてなのですが、令和７年２月１４日現在のものを表として示させていただいておりまして、今後、給与改定や制度改正が行われた場合にはその額によりますというご案内をさせていただいているとおりでして。","voiceIndex":199,"id":"exchange-090"},{"speaker":"松永委員","kind":"確認","question":"私からは、３７９ページの帰国児童・生徒等支援費で、ＡＩ先生について、あとページ数が合っているか分かりませんが、３７９ページの生徒指導対策費の中で、先ほども質疑がありましたが、教員へのメンタルヘルス対策について、時間がありましたら３９５ページの学校環境整備の校庭について、人工芝について伺いたいと思います。初めに、３７９ページの生徒指導対策費について伺います。","respondent":"中谷指導課長","answer":"その中で、医療の面でできることと、学校の管理職でできることと、そこをしっかりと役割分担をさせていただきながら、ご本人に必要なアプローチ、サポートをしていくというようなことをやっております。","voiceIndex":203,"id":"exchange-091"},{"speaker":"松永委員","kind":"質問・要望","question":"モンスターペアレントについて伺いたいと思います。それが、例えばいじめなどといったところにつながってくるのではないかと思いますが、本区において、モンスターペアレントを理由に病気になった教職員の方がいたのかということで伺いたいのですけれども、その現状を、もしいれば、その方に対しての対策を教えていただきたいと思います。","respondent":"中谷指導課長","answer":"その場合に、例えばですけれども、おっしゃっていただいたような副校長補佐や、小学校の場合はエデュケーション・アシスタント、あとはスクール・サポート・スタッフは小学校・中学校、全てに配置しておるものでして、主にこういった役割の方々がそれぞれの役割を担っていく中で。","voiceIndex":205,"id":"exchange-092"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほど質疑がありましたが、本区においては教育現場で教職員の人数が少なくなるか、保護者からの要望・苦情に対しては電話対応というか、そういったところでされているとは思うのですけれども、私としては、先ほどのこともメンタル対策も含めて、教員への対策も含めまして、こうした心理士も含めて、一括して電話相談窓口となる場所をつくってはいいかと思いますが、区の考えをお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"一括した窓口を設置いたしますと、学校との関係性が保護者と切れてしまうというところから、一旦は学校で受けていただいて、それでもご納得いただけないようなことでしたら、我々教育総合支援センターにもＨＥＡＲＴＳの窓口があったり教育相談があったり。","voiceIndex":207,"id":"exchange-093"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ今後、そうした取組も注視していただければと思います。本区においても、子どもたちが１,０００人ぐらいいるのか、大体そのぐらいだと思うのですけれども、そこでしっかりと日本語教育をしていかなければならないと思いますが、人手不足ということもあるかもしれませんが、ぜひＡＩ先生を活用した日本語教育を取り入れていただきたいと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"現在、日本語の指導が必要な外国籍・日本国籍の方は、児童で７３名、生徒で２４名おります。現在、日本語教室を活用しておりますが、今、ＡＩの活用というものも進んでおりますので、状況を見ながら、できるものは活用できたらと考えます。","voiceIndex":209,"id":"exchange-094"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３８３ページ、学校と家庭の連携推進事業、４０１ページ、就学時等健康診断費、時間があれば３９５ページ、学校維持補修費についてお伺いします。最初に、３８３ページ、学校と家庭の連携推進事業に関連しまして、学校における市民科の授業です。市民科だけでなくてもいいのですけれども、この指導についてお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"メディアリテラシーの育成について、情報モラル教育を各学校では実施しております。","voiceIndex":212,"id":"exchange-095"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"午前中の質疑で、西村委員からも質問がありました。ぜひこれは推し進めていただきたいと考えています。規制をかけないでやっていただきたいと考えています。ぜひそれは家庭教育学級でも取り入れていただきたいと思っています。これはＰＴＡ主催なので、教育委員会からぜひ打診というか、示していただけると、すごくありがたいと思っていますけれども、いかがでしょうか。","respondent":"舩木庶務課長","answer":"しかし、確かにやはり情報のリテラシーや、いろいろな社会の移り変わりや時宜に即したようなテーマというのは、非常に家庭教育の中では必要なことかと思いますので、そういったご案内や、区が持っている、保有している情報などについては、必要に応じてしっかりと。","voiceIndex":214,"id":"exchange-096"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。学習目的でない視聴というのは、あくまで保護者からの意見であって、これは学習という中のＹｏｕＴｕｂｅで視聴するわけですから、ぜひ規制をかけないで、引き続きやっていただきたいと思いますけれども、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"学校が必要に応じてよいと判断したものはフィルタリングの解除も行っておりますので、そういった中で子どもたちの学びがしっかりとできるような環境整備には努めていきたいと考えております。","voiceIndex":216,"id":"exchange-097"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。次に、４０１ページ、就学時等健康診断費に関連しまして、これは衛生費で質疑いたしましたけれども、百日ぜきの流行と３種混合ワクチンについてお尋ねさせていただきたいと思います。品川区のホームページに、３月７日付で、百日ぜきが増えていますという警告が掲載されております。現在の品川区の教育現場における百日ぜきの流行状況についてご報告をお願いします。","respondent":"柏木学務課長","answer":"百日ぜきの学校での状況ですが、今年度につきましては、現在把握しているところで、４校で６名、発生しています。そのうち３校の５名につきましては、１月以降の発生となっています。","voiceIndex":218,"id":"exchange-098"},{"speaker":"高橋（伸）委員","kind":"質問","question":"小学校では百日ぜきの流行がこれから広がっていく可能性もあります。小さな赤ちゃんの百日ぜき感染による悲劇を防ぐには、小学校における百日ぜきの流行を抑えなければなりません。それで、現在の百日ぜきの流行に対し、学校現場ではどのような百日ぜきに対する感染対策、生徒・保護者に対する啓発が行われているのか、教えてください。","respondent":"柏木学務課長","answer":"感染予防としては、こちらは感染経路自体が飛沫感染または接触感染ということになってありますので、せきエチケット、あと手洗いについての周知を進めてあります。学校からも家庭についてそういう周知がされているものと考えています。","voiceIndex":220,"id":"exchange-099"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３９５ページ、学校環境整備事業、これは契約についてお伺いします。３９９ページ、給食運営費、それと教育費全体で、これからの教育についてお伺いしていきます。考え方として、私はすばらしいと思うのです。幾ら物価高になっても、実は１０円上げるだけでも、保護者の負担をお願いするのは、値上げをするのは、なかなか今まで厳しかったのです。５年間で１,１２３件。そこをお願いします。","respondent":"柏木学務課長、荒木学校施設担当課長","answer":"ＳＤＧｓ未来都市に選定された品川区としても、政府の方針と軌を一にする形で、可能な範囲で学校給食での有機農産物の利用を推進することで、環境保全農業、環境負荷を低減する持続可能な日本の農業に寄与していきたいと考えています。江戸川区の事例だと、スケジュールが間に合わずといった記載もあったのですけれども、そういったことがないように、事前に施設側と調整して、しっかりと手続を踏んだ上で発注しておりますので、まずご懸念には当たらないと考えています。","voiceIndex":224,"id":"exchange-100"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"分かりました。４点の視点で伺っていきます。怒らない大人たちがいる中で、どうやって教育をしていくのかということです。今、いろいろ投資の話などもあって、子どもたちにもしっかり、マネーリテラシーを教えていかなければいけない。その辺も含めて教えてください。そういったギフテッドの子たちなどを含めて、今の教育とこれからの教育をどのように考えているのか、教えてください。","respondent":"中谷指導課長","answer":"今の学習指導要領も、この考え方を踏まえながら、学校教育法で定めている学力の３つの要素というのがありますが、知識・技能、思考力・判断力・表現力等、そして主体的に学習に取り組む態度。","voiceIndex":227,"id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"この点について、取扱いをされている事業者から、今後は私たちの取扱店はどうなってしまうのでしょうかという心配の声などが上がっているわけです。取扱店では、保護者とのメリットの関係もあるので、今後どのようになっていくのかという心配の声がありますので、ぜひ事業者とよくよく、今の状況を聞いていただきながら、事業展開をお願いしたいと思いますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"同様な声等も頂いておるところです。頂いた声も参考に、今後、具体的な内容について検討を進めていきたいと考えています。義務教育学校の対象学年につきましては、今、対象学年も含めて検討を進めているところです。","voiceIndex":230,"id":"exchange-102"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問にまいります。いじめ防止対策です。令和６年度の教育委員会事務事業の点検および評価の報告を拝見いたしました。私は、このご指摘は大変に大事なご指摘と受け止めているわけですが、まずこのご指摘について、教育委員会はどのように受け止めていらっしゃいますでしょうか。そもそも品川区の学校風土とは、どういうものが重要であるのか。その辺をまず、お聞きします。","respondent":"丸谷教育総合支援センター長","answer":"今回、滝先生からは様々なご指摘を頂いております。それぞれ真摯に受け止めまして、今後の事業改善に努めてまいりたいと考えております。","voiceIndex":232,"id":"exchange-103"},{"speaker":"こんの委員","kind":"質問・要望","question":"当然、それはされている。こうした教育を展開していただきたい。そうした自己肯定感を高める取組を、授業では一部しているということも認識しておりますが、先生たちの自己肯定感を高める取組ということが、ひいては生徒にも影響し、親御さんにも影響してくるところから、こうした取組をすることが学校風土を高めていく、よくしていくと私は考えるのですが、その点についてご見解をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"ご指摘のとおり、職員が前向き・意欲的なモチベーションを持っていないと、子どもたちに影響すると考えておりますので、こうしたよい取組を増やしていくということに今後も注力して、学校風土の向上に努めていきたいと考えております。","voiceIndex":234,"id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"子どもへの自己肯定感の向上といったところは、教員同士でもあるというご答弁を頂きました。当然、教員の方たちは、そうしたことが大事という教育の１つの重要なことでは承知はしていると思いますが、それが日常的にされないというところに、何か弊害があったときに、こうした問題が起きてくることにつながってしまう。このように思うことでありますが、もう一言頂けますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"昨今、職場内の心理的安全性ということもよく言われるようになってきました。こうした考え方も、区立学校全体に広げていきたいと考えております。","voiceIndex":236,"id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問","question":"４０１ページの学校施設建設費と、３７７ページの会計年度任用職員給与費について伺いたいと思います。歳入のところでも伺ったのですが、学校プールについてです。改築された学校は４６校中２６校になっていると思います。そうすると、改築された学校で、開閉屋根なし屋上プールというのは１７校になるということでいいのか、伺います。その点についても伺います。","respondent":"荒木学校施設担当課長","answer":"改築済み、工事が完了している学校に関して言えば、１３校ということになってあります。深さの調整に関しましては、屋内の温水プールと、あとは屋上に設置している開閉式屋根のプールで、床の昇降ができるということになってあります。","voiceIndex":239,"id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、屋上の屋根なしプールでは、深さの調整というのはやることができないという仕組みなのか、その点も教えてください。その点についても伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"もう一点です。クラス数に関する基準ですが、現在はおおむね最大、各学校で３０クラスを超えてくる学校につきましては、プールの授業日数、設定した授業時数を効率よくこなしていくために、昇降式の床、そして開閉式の屋根を用いたプールとしているという状況です。","voiceIndex":241,"id":"exchange-107"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどの浅間台小学校に関する答弁では、日よけつきの手動のテント、シェードの設置を検討するということだったと思うのですけれども、そういうことからすると、源氏前小学校でも、そういうところで設置していきますということでいいのか、その点を伺いたいのと、基本的に、そういうことであれば、屋根なしプールについては、日よけのシェード。","respondent":"荒木学校施設担当課長","answer":"今後、先ほど、午前中にも説明しました浅間台小学校も含めまして、これから設計に着手する学校については、このような上部を覆うものの検討はできますので、今後はしっかりそういったところを含めて進めてまいります。","voiceIndex":243,"id":"exchange-108"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。すごい猛暑なので、多くの授業が中止になってしまって、年間、二、三回しかできないという状況になっているということで伺ったのです。例えば保護者の方から荏原文化センターや戸越台中学校など、温水プールを、夏の期間でもなくてもいいので使えるように配慮していただけないかというご要望を頂いたのですが、いかがでしょうか。","respondent":"荒木学校施設担当課長","answer":"は１点目の、体格の差によるプールの水深ですが、改築の屋上のプールに限らず、既存の学校のプールでも、水を抜いたり注水したりという対応で、水深を調整しています。","voiceIndex":245,"id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"有機野菜はサイズがばらばらなので、調理する際には規格外のものを多数扱わないといけない、あるいは調理する温度管理や時間管理など、大変苦労が及ぶわけですが、調理師の方に対しても、先ほどの質疑の中では、議決後に丁寧な説明をされる、理解を求めるということでありましたが、私は、調理師の方には、今からでもしっかり区の方針を示して、理解を得るような取組を行うべきだと思いますが。","respondent":"柏木学務課長","answer":"調理師等への説明ですが、これまで答弁していますが、今回、議決いただいた後、具体的に丁寧に説明をしていきたいと考えています。","voiceIndex":248,"id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"区として、教育委員会として、子どもの給食に対して有機野菜等を提供することは本当にすばらしいことなのだという思いを、我々にしっかり伝えていただきたいし、また、そういう意味では、関係する、特に調理師の方の理解を今からでも得ていただくような取組があってこそ、我々も議決できるものだと思います。改めてお伺いしたいです。","respondent":"柏木学務課長","answer":"今、委員からご指摘がございましたので、それにこだわらずにはいきたいなと、今、考え直しています。いずれにしても、速やかに関係者につきましては、丁寧に説明をしていきたいと考えています。","voiceIndex":250,"id":"exchange-111"},{"speaker":"田中委員","kind":"質問","question":"関係者への丁寧な説明は当然ですが、我々に対しても、本当に有機野菜を取り込むことが子どもにとっていいことなのだと理解させるような答弁をぜひお願いしたいと思います。特に、中学生の、おいしい給食を食べたいという声に対しては、今回の有機野菜等の食材を扱うことで解決されると思われますでしょうか。お伺いします。","respondent":"柏木学務課長","answer":"それと今回の有機野菜とは別問題と考えています。これまでも学校給食費は、予算全体について、１食当たりの単価を５０円程度引き上げて、来年度につきましても引上げということで予算を計上しています。これによって、質および量の担保をしっかり図っていくこととしております。","voiceIndex":252,"id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"対応をお願いしたいと思います。続いて、制服に関してです。これも重複を避けますけれども、今回、給食の場合は一括調達を検討するということではありましたので、ぜひ丁寧な対応を取っていただきたいと思いますが、今回の制服に関しては、制服を無償化する。それに当たって一括購入をするということであります。これは、無償化の前提が一括購入ということになるのでしょうか。お伺いします。","respondent":"柏木学務課長","answer":"１つとして、一括購入という案もあることです。ただ、先ほど別の委員からございましたけれども、販売店等のご意見等も参考にさせていただきながら、具体的な策については、これから検討していきたいと考えています。","voiceIndex":254,"id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、仮に一括購入といったときに、予算が今回、１億１４２万円になります。例年、同じぐらいの規模の一括購入をするとしたら、４,０００万円以上の購入なので、議決が必要となるかと思います。議決を経るのは、当初予算に盛り込まれたものとして議決するのか、今後は第２回定例会、第３回定例会等で議決を求めてこようとされているのか。その辺をお伺いします。","respondent":"柏木学務課長","answer":"一括購入ですけれども、支払い自体を、これまでそれぞれの保護者が個別に販売店から購入していたというものを公費にするということで、区から事業者へ一括してお支払いするという意味ですので、標準服を統一するとか、１メーカーに全部決めるとか。","voiceIndex":256,"id":"exchange-114"},{"speaker":"田中委員","kind":"意見","question":"先ほど質疑にもありましたように、無償化に当たっては、無償化にならないと思いますけれども、今の流れで、購入していただくご家庭に制服購入券のような形でお配りすることで負担感を減らしていくということも、私はスムーズな制度導入につながるものと考えていますので、ぜひ検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":258,"id":"exchange-115"},{"speaker":"こしば委員","kind":"質問","question":"私からは、３７５ページ、文化財保存活用事業についてと、時間がありましたら４０１ページ、学校施設建設費に関連しまして、小学校の校舎の中での「一足制」について、お伺いしていきたいと思います。文化財保存活用事業についてです。初めに、品川区の有形無形の文化財保護について伺います。保管する状況といいますか、気をつけていることなどを、まず教えていただければと思います。","respondent":"舩木庶務課長","answer":"我々、文化財の所管としましても、文化財の様子などといったところを日々気にかけて、しっかりと後世に継承するために管理がなされているかというところで、関わりを持ちながら進めているところです。","voiceIndex":260,"id":"exchange-116"},{"speaker":"こしば委員","kind":"質問","question":"善良なる管理の義務があるということは分かりました。所有者が、なかなかこの近くに住んでおらず、遠方にいるなどして、文化財や、その文化財の周辺の環境をなかなか整備できない、清掃できないといったものもあるかと思います。その辺り、品川区で具体的に何か、定期的に連絡を取るなどのアプローチをしているのか、具体的に教えていただければと思います。","respondent":"舩木庶務課長","answer":"区にお住まいではないというところにつきましては、地域の例えばボランティアの方の力をお借りして、そういった文化財の周りの清掃等にご協力を頂くケースもありますし、日常の管理や修理などでお困りの際には、実態としましては、我々、地元の自治体である品川区。","voiceIndex":262,"id":"exchange-117"},{"speaker":"こしば委員","kind":"質問・要望","question":"実際に、例えば西大井の地域ですと、伊藤博文公の墓所もあります。続きまして、文化財の展示についてお伺いいたします。ですから、なかなか展示されていない文化財を、やはり有効に、ぜひ区民の方の目に触れるような機会をつくっていただきたいと思います。文化財を、地域センターや共有スペースといったものに展示していく取組などをぜひご検討いただければと思いますが、ご見解を伺います。","respondent":"舩木庶務課長","answer":"私どもの文化財、来年度いろいろと遺物を整理していくようなことも予定しておりますけれども、この辺りは文化観光戦略、広い意味で、やはり都市の価値という意味では、伝統文化都市、都市ブランディングなどの考え方にも通じるところがあると思いますので。","voiceIndex":264,"id":"exchange-118"},{"speaker":"こしば委員","kind":"質問・要望","question":"先ほど出張展示ということもお聞きしました。そういったものは例えばＶＲ技術も今ありますので、例えば歴史館などといった共通のスペースで、ＶＲのゴーグルを使って、ぜひ区民の方に見ていただく機会も検討していただきたいと思いますが、お考えをお伺いいたします。","respondent":"舩木庶務課長","answer":"そういったことも含めて、今、ＶＲなどのご提案も頂きましたので、今後の活用の方法については検討していきたいと考えております。","voiceIndex":266,"id":"exchange-119"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ検討を前に進めていただきたいと思います。時間が少なくなりましたけれども、「一足制」についてお伺いいたします。学校の昇降口で、外履きから上履きに履き替える「二足制」というのは、これまで長らくどこの学校でも見られた、ごく当たり前の光景でした。改めて、区でこの「二足制」の歴史を踏まえて、どのようにこれまで分析されていたのか、評価していたのか、教えていただければと思います。","respondent":"荒木学校施設担当課長","answer":"感染症対策として、昇降口付近における密を解消するために、令和３年度から検討を開始いたしました。区立学校の改築の際、狭い敷地内の建て替えが大半でしたので、その中で昇降口や下足箱の間の適切なスペース確保という課題があったことも理由です。","voiceIndex":268,"id":"exchange-120"},{"speaker":"こしば委員","kind":"意見","question":"もう一つの側面も多分あると思います。毎年１２月に区民避難所を実施しております。高齢者の方も「一足制」のほうが入りやすい、校舎を利用しやすいという意見もありますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":270,"id":"exchange-121"},{"speaker":"若林委員","kind":"質問","question":"４０１ページの学校改築推進経費について伺います。築６０年以上の学校が１０校弱あるという中で、どうしても、三木小学校、大崎中学校は、やはり、まちの環境がほかとは少し違うと。今年度、三木小学校等の改築について、地元、西品川三丁目を含む地域に対してどのように説明をしているのか、まずお聞きします。","respondent":"荒木学校施設担当課長","answer":"２点目に、昨今の区立学校全般の改築状況です。区内の就学人口が増加傾向にある中、教室不足となる学校を優先的に改築しております。その上で３点目に、三木小学校の建て替えに向けては、狭隘道路などの課題整理を進めていくことをご説明させていただきました。","voiceIndex":273,"id":"exchange-122"},{"speaker":"若林委員","kind":"確認","question":"本会議の中でご答弁も一定程度頂きましたので、そこの確認をします。三木小学校ですが、大崎中学校も含めて、既存校舎の老朽化への対応は急務であるというご答弁でした。築何年までに対応するのかをお聞きします。","respondent":"荒木学校施設担当課長","answer":"それぞれ狭隘道路や狭小敷地、あと法規制が厳しい敷地など、工事困難な学校が存在いたします。それらについて、工事期間の短縮や工事費縮減に向けて様々な建て替え手法を検討し、老朽度や地域バランス、就学人口などを踏まえて、学校改築を順次進めていくという考えです。","voiceIndex":275,"id":"exchange-123"},{"speaker":"若林委員","kind":"質問","question":"質問の中でも取り上げましたけれども、品川区立学校施設長寿命化計画というのがあります。ここでは築８０年を「目標に」、言葉遣いはあれですけれども、目途にという表現がありますが、これは、いわゆるそこまでに対応するということにはならないでしょうか。","respondent":"荒木学校施設担当課長","answer":"既存校に関しましても、こういった同じ流れで、２０年間ごとに大規模改修などを実施してまいりますが、当然、老朽化が進んでいる現状がありますので、８０年にこだわらずに順次着手していくという考えです。","voiceIndex":277,"id":"exchange-124"},{"speaker":"若林委員","kind":"質問","question":"新築の場合は８０年、既存の場合は、普通に考えると８０年よりももっと前にと解釈できますけれども、そういうことでよろしいでしょうか。","respondent":"荒木学校施設担当課長","answer":"今、委員がおっしゃいましたとおり、既存校舎に関しましては、８０年を待たずに順次改築に着手してまいります。","voiceIndex":279,"id":"exchange-125"},{"speaker":"若林委員","kind":"確認","question":"次のご答弁で、工事期間の検証とその短縮や、工事縮減、建て替え手法について、課題を整理して検討すると。この「整理」や「検討」というのは、誰が整理・検討するのかを聞きます。検討の開始時期と、また検討を始めて、その結果を出す時期についても確認します。","respondent":"荒木学校施設担当課長","answer":"その際に必要があれば、まちづくり部門など関係所管と、道路拡幅などの可能性について連携を図っていく考えです。期間は特に明確に定めておりませんが、順次、検証・検討がまとまった段階で説明させていただきたいと思います。","voiceIndex":281,"id":"exchange-126"},{"speaker":"若林委員","kind":"質問","question":"誰がという質問に対しては、教育委員会がという主語になる、答弁になるということで、今理解いたしました。本会議でもご答弁がありませんでした。三木小学校で言えば、築６７年。今のご答弁で言うと、築８０年までには着手しなければいけないという考えであると。これはもう、一定、公式な見解だと思います。その検討については、速やかに年度内等に結果を出していくということで、いかがでしょうか。","respondent":"荒木学校施設担当課長","answer":"工事期間の検証につきまして、速やかに着手させていただきたいと思います。それを踏まえてどういった建て替え手法が取れるかということに関しては継続して調査してまいりますが、まずは工事期間の検証結果というものは、検証次第、速やかにご説明させていただきたいと思います。","voiceIndex":283,"id":"exchange-127"},{"speaker":"若林委員","kind":"質問・要望","question":"私や、地域で関わっている議員も含め、地元からは毎年、何回かにわたって、特に三木小学校の改築については、大変強い、また大きな要望・期待の声が例年届けられております。これもまさに年度が変わったら、予算が成立後、速やかに、「教育委員会の対応としてこういうふうにいたします」ということを、地元に対して丁寧に説明をまずはしていただきたいと思いますけれども、いかがでしょう。","respondent":"荒木学校施設担当課長","answer":"地元の方々に対しましても、検討状況・検証状況については、地域からの求めに応じまして、今後も丁寧にご説明させていただきたいと考えております。","voiceIndex":285,"id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"これは、木密、いわゆる脆弱な地域は、担当部門で淡々とやっているわけです。一方で、避難所の老朽化というのは、地域の方にとっては、また子どもを守る施設、子どもが生き生きと日中過ごす地域として大変に大切に思っているということで、教育委員会当局からは、結果が出た後には、まちづくりとしっかり連携を取っていただきたいと、改めてお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"３９９ページの学校の給食運営費と、それから標準服購入費用保護者負担軽減事業、無償化についてお聞きします。この２つに関して共通項があります。予算というのは細かくは調整可能かもしれません、これからになると思いますが、ある程度の大体の大枠というのは決めて予算に挑むのではないのでしょうか。上がっている数字の信頼がもう全くないと私は思ってしまっているのですが、これはいかがですか。","respondent":"柏木学務課長","answer":"区の事業といたしましては、これまでも方針をまず出させていただいて、その中である程度、概算にはなりますけれども、それなりに試算した概算の予算で要求させていただき、実施に向けて検討し、年度内で実施していくという事業はございましたので。","voiceIndex":289,"id":"exchange-130"},{"speaker":"西本委員","kind":"確認","question":"学校給食と標準服を今挙げましたけれども、今回の予算はそれだけではないです。供給をどうするのだ。安定供給できるのか。それをどうやって調理するのだ。それを踏まえて、教育長、これはいいとしているのですか。確認はどこまでしているのですか。現場の皆さんの働きに関して、子どもたちの安全に関して、親たちの不安も含めて、これを解消するという形での交渉や事前の話合いはできているのでしょうか。","respondent":"柏木学務課長","answer":"これまで答弁させていただいていますように、具体的なことはこれからですけれども、導入までまだ時間がありますので、そこはきちんと関係者等に、具体的に、そして丁寧に説明しながら、事業の精度を高めていきたいと考えています。","voiceIndex":291,"id":"exchange-131"},{"speaker":"西本委員","kind":"確認","question":"今回の議論の中では全く聞いていないと私は捉えました。なので、非常に現場は混乱していると思います。きちんと準備をしていないから、このようなことになるのではないですか。その中で少し確認しますが、オーガニック給食で、寄附とありました。この寄附は、どこの業者からどのような形できているのでしょうかということ。そういうふうに私は思うのですが、この不透明なところをどうされるのですか。","respondent":"舩木庶務課長、柏木学務課長","answer":"具体的な内容につきましては、本予算案を議会に議決いただいた後に、しっかりとこういった本当に貴重なご厚意をお受けする手続を進めてまいりますので、現時点につきましては答弁を差し控えします。標準服の契約の件ですけれども、こちらは今、今年度より実施しております補助教材費の無償化につきましては、各学校が授業で一斉に活用する補助教材費について、各学校の契約で実施しています。","voiceIndex":293,"id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"寄附の件に関しては、今の段階では言えないということなので、これはきっちりと、どういう会社で、品川区とどのような関係がある会社なのか、どういうお気持ちを持って寄附という形をしていただけるのか。それはしっかりと議会に報告をお願いしたいと思います。そして、標準服の件です。標準服です。それで、では何で標準服の無償化にしたのですか。理解は得られないと思いますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"標準服の無償化ですけれども、こちらは繰り返しの答弁になる部分もありますけれども、無償化するに当たって、様々なものについて検討させていただきました。その中で、保護者の負担感が大きいものという形で、今回、２事業について予算の提出をしています。","voiceIndex":296,"id":"exchange-133"},{"speaker":"西本委員","kind":"質問・要望","question":"負担の軽減は分かりますけれども、これは税金なのです。税金を使ってやるのですから、透明性のある形にしなくてはならないし、このままでいいのかという議論がまず先だと思います。それから給食については、ぜひ現場の状況をしっかり把握して、対策をしっかりして、見直しを含めて考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-134"},{"speaker":"せお委員","kind":"提案","question":"こちらは、エデュケーション・アシスタントなども含めて、学校を支えてくださる支援員などについてお伺いします。もし中学校が一貫校に進まなくて、ほかの学校に行ってしまう。まだきれいな制服をお持ちのお子さんは、会派のえのした委員からも提案があったのですけれども、標準服リサイクルに回せるよう、学校にお返しいただく。こういったやり方でもいいのではと思うのですが、見解を伺います。","respondent":"柏木学務課長","answer":"リユース事業は、区として推進していくものになりますので、保護者についても、そういうふうにご協力いただけるように、教育委員会として、また実施する福祉部門としても、そういう部分でご協力いただけるように周知していきたいと考えています。","voiceIndex":300,"id":"exchange-135"},{"speaker":"せお委員","kind":"確認","question":"ぜひ議論のほどよろしくお願いします。フリースクールについて伺います。こちらは確認なのですけれども、フリースクール等利用料助成を始めることになった経緯を教えてください。","respondent":"丸谷教育総合支援センター長","answer":"フリースクールを利用しているご家庭がありますけれども、かなり利用料の負担が大きいということで情報が入っております。東京都が助成金を出しているというところで、まだまだ足りないという部分がありますので、区として上乗せで助成していくというところでの経緯です。","voiceIndex":302,"id":"exchange-136"},{"speaker":"せお委員","kind":"質問","question":"そして不登校支援ですから、マイスクールが４校ある。先日も会派でマイスクール西大井に伺って、マイスクール八潮にも以前に伺いましたが、マイスクールは、子ども一人ひとりの特性などをすごく理解されていて、スタッフの方も本当によくご存じで、工夫もされていました。１０年後にフリースクール利用助成がなくなっている、廃止しているぐらいの大きな方針があると進んでいくのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"フリースクールについても１つの選択肢として考えているところでございまして、併せて学校の中の安心安全な環境づくりというものも進めてまいります。","voiceIndex":304,"id":"exchange-137"},{"speaker":"せお委員","kind":"質問・要望","question":"一般的にですけれども、事業などを考えて見直しをしていく、検討しているところに、新しいものを入れていくというのは、あまり手法として聞かないのかなと思いました。探究学習の進め方の基本ベースなどを区教育委員会でつくったり、あとは企業や団体とも連携できるベースをつくったりなど、そのような準備段階のところは、この市民科検討委員会で検討されるのでしょうか。教えてください。","respondent":"丸谷教育総合支援センター長","answer":"市民科検討委員会では、今後、市民科の中で、探究学習も含めて、抜本的な見直しも含めて検討していくものです。当然、区内にはたくさん、多くの企業から支援を受けている学校も多くありますので、そうした連携も進められるようにしていきたいと考えております。","voiceIndex":306,"id":"exchange-138"},{"speaker":"せお委員","kind":"質問・要望","question":"ウェルビーイングの理解を深める学習自体は悪いとは思わないのですけれども、そういった進め方のところを、ぜひ検討していっていただきたいと思います。ほかの自治体に先駆けて、２０年前にできた市民科ですから、市民科を活用しながらも、時代に合った主体的・対話的で深い学びが全校で実現できるように、検討をお願いします。副校長補佐も併せて見通しを聞かせていただきたいと思います。","respondent":"中谷指導課長","answer":"令和７年度のエデュケーション・アシスタントの任用の状況見込みですが、５４名の枠のうち、４８名が既に面接を終え、任用者が決まり、１校を除きまして９割で、今、任用確定という状況になってあります。","voiceIndex":308,"id":"exchange-139"},{"speaker":"せお委員","kind":"提案","question":"見通しがほとんどついているということで、安心はしました。地域からは、子どもたちのためにいろいろしてあげたいけれども、自分はこれ以上、あとほかの人を探してくるのは困難といったお声もありました。ですから、産官学連携というか、民間企業などと連携した人材の配置なども、ぜひ検討していただきたいと、こちらは要望いたします。改めて、こちらの見解を伺います。","respondent":"唐澤特別支援教育担当課長","answer":"特別支援学級支援員につきましては、現在、学級数に応じて配置しております。今後も就学相談等で、特別支援学校の判断になったものの、総合的な判断により、区立学校に通っているお子さんについては追加して配置できるような形、このような体制を取っていければと考えています。","voiceIndex":310,"id":"exchange-140"},{"speaker":"せお委員","kind":"意見","question":"本当に認知症サポーター養成講座というのは、すごい人数が受けてくださっていて、結構理解が進んでいて、本当にあの講座はいいなと、私も受けさせてもらいましたけれども、そういったところで、特別支援教育はと、地域の方でも理解がないからという形で避けてしまう方もいらっしゃるので、ぜひ広く受講していただいて、理解と、あとは、もし支えてくださる方がいれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":312,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"２０２２年から、産婦人科医が都立高校でユースヘルス相談をしています。令和７年度の予算は、モニター式の一体の電子黒板を配備して、電子黒板を導入するということが予算化されていますが、現場の先生からすると、このスクリーンは実は黒板が使いにくい状況なのですが、どのような導入計画になるのでしょうか。改築の際にはこの電子黒板を改築校に全部入れるのかということをお尋ねします。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"都立高校における産婦人科医による生徒からの相談受付ですけれども、区立学校の中学校養護教諭、この事業自体は把握している教員もおると思いますけれども。改築校につきましては、こちらはあくまでもリースの満了に伴ってということになりますので、改築校だから全て電子黒板になるというわけではございません。これも、リースの満了に伴って、随時、替えていくという計画です。","voiceIndex":314,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"６年生からやるということですが、実施校を減らしたということは、本当は５年生からやる予定だったのを減らしたのか、それとも６年生でやるのに、実施校が全校ではなくて数を減らしたのかということをお尋ねします。これが１,０００万円ということは、測地測量しないということは、次に基本設計をしないということですから、学校改築が１校、年度が遅れるということではないでしょうか。","respondent":"加島財政課長","answer":"それが予算編成の過程になるわけですけれども、企画経営部から一方的にこれをこうするというのではなくて、所管部局と企画経営部とが、事業の目的、実施方法等、対話を重ねながら協議をしまして、綿密な検討を重ねてきた結果、それが今日、今。","voiceIndex":317,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは所管の方に答えていただけるならお尋ねします。オンライン英会話レッスンはいいことだと思います。全校でやったほうがいいと思います。でも、実施校を精査したということは、予算の関係で減らしたのでしょうかということです。もしお答えできるなら、社会科見学も同じです。お願いします。","respondent":"中谷指導課長、柏木学務課長","answer":"先ほどのお話のとおり、予算の額の調整というところにおいて、まずは１校からという結論に至ったというものになります。私からは、社会科見学の件ですけれども、こちらは様々な無償化の検討をしていく中で、１つ、社会科見学のバス代について他の学年にも拡大をということで提案したところですが、こちらは繰り返しの答弁でありますが、その検討の中で。","voiceIndex":319,"id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和５年度の決算の様子を見て、こうやって要求されていると思います。もう時間がないのですが、今お話があったように企画のほうで削ったと。逆に私は、増やしたことは全然言っていないのであれですけれども、いろいろな部門で増やしたこともあると思います。文京区のように、企画の査定、区長の査定も含めた予算編成過程の公表。品川区は要求と予算だけですけれども、その点についてはいかがでしょうか。","respondent":"加島財政課長","answer":"今、予算の中で「削った」という言葉がございましたけれども、私どもは、先ほど申し上げたとおり、所管部局と対話をしながら、その事業の目的や実施方向、実現可能性について何度も対話を重ねながら、本日予算の編成を行ってきたところです。","voiceIndex":322,"id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"私からは、３９９ページ、標準服購入費保護者負担軽減事業、時間が多分ないかもしれませんが、３８１ページの品川学校支援チーム経費を伺います。何とか重複しないところがあったので、よかったなと思いながらお伺いしたいのですけれども、かすっている部分が結構あるので、どうしようかなというところもあります。ここから始めたいのですけれども、標準服が必要になる理由とは何なのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"標準服の設定についてですけれども、様々な意見はあると思いますけれども、例えば教育の質を均一化するためということで、全ての生徒が同じ標準服を着用することで、生徒間の格差をなくし、教育の質を均一化するという期待や、教育環境を整えること。","voiceIndex":325,"id":"exchange-146"},{"speaker":"松本委員","kind":"質問","question":"ここでお伺いしたいのですが、先ほどほかの委員からもありましたが、標準服ということで、本来は義務ではないというところかとは思うのですけれども、ただ一方で、では本当に義務ではない、例えば私服で通ってもいいのかというところは、どういう運用になっているのか。仮に運用として私服で通ってもいいと言いながらも、本当に私服で通っている子どもたちというのはいるのかというところはいかがでしょう。","respondent":"丸谷教育総合支援センター長","answer":"ただ、標準服の生地が皮膚に合わないというようなお子さんや、締めつけられるような感じがするといったお子さん一人ひとりのニーズに合わせて各校で対応している。私服や、ほかの着用のものに切り替えるというような対応は、個別には行っているところです。","voiceIndex":327,"id":"exchange-147"},{"speaker":"松本委員","kind":"提案","question":"ここで考えたときに、品川区は学校選択制という、選択をとても重視している教育スタイルを取られているので、例えば学校選択制もありますけれども、例えば学級の中で私服の学級をつくってみたりして、提案して私服の学級を選べるようにする。誰かから言われるのではなくて、自分で私服の学級・クラスに通えるという試行を行ってみてはいかがかと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"標準服を１つテーマにして、子どもたちが自ら、自分たちで考えていくということは、非常に大切な試みかなとは考えているところです。","voiceIndex":329,"id":"exchange-148"},{"speaker":"松本委員","kind":"質問","question":"これは、やはり先入観もあると思うのです。もうそれはあるものだと思ってしまうから、そこの枠組みにとらわれるというところがあるので、教育としては、そういうことを１回、ゼロベースで考えてみましょうということも大事ではないかと思います。これは今、区立中学で様々、制服があるかと思うのですけれども、これもまた、ここから伺いたいのですが、なぜ制服は各校で違うのでしょうか。お願いします。","respondent":"丸谷教育総合支援センター長","answer":"そうした意味で、愛校心を持つ、地域の学校という意味で、地域からも愛される学校づくりといったものが、標準服には込められていると捉えています。","voiceIndex":331,"id":"exchange-149"},{"speaker":"松本委員","kind":"質問","question":"ましてや今回は無償化するわけですから、区が区民の方たちの税金で、区の中学生たちの制服を無償化するということなので、そうすると、区に対して愛着を持ってもらうというのも１つ、大事なのではないかと思います。質問をすると、この発言ができなくなるので、統一の話をすると、販売店をどうするのかという話が今日も少し出ていました。なので、これはやり方次第。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":333,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"３９９ページ、学校運営費についてお聞きします。その理由は、保護者の経済的負担を軽減するというものです。教えてください。これについても教えてください。そして、教育は誰もがひとしくということならば、公立中学校の生徒だけでなく、区内・区外を問わずに、インターナショナルスクール等や私立学校に通学している生徒も対象にするべきではありませんか。教えてください。","respondent":"柏木学務課長","answer":"無償化に対するお問合せですけれども、今回、品川区で実施している無償化につきましては、本来であれば国において実施とは思いますけれども、区としては、どんな立場や境遇にあっても選択が限定されずに、自分が望むように生きられる社会をということで。","voiceIndex":335,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"今、ほかの学校に対してどうなのだ、私立学校に通学している子はどうなのだという質問もしましたが、後でお答えください。このように、大半の世帯が生活苦しいわけだから、もし無償化できる余裕があるなら、苦しい世帯を先に優先して支援するべきだと思いますが、これに対して学校教育では子どもたちにどのように教えているのですか。このような理念は教育委員会にはないのでしょうか。教えてください。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"そこでは、税の使われ方や意義についての学習を深めているところです。市民科の学習の中では、困っている人を助けるということは当たり前のこととして、学習は進めているところです。私立等については各設置者が検討すべきものと考えています。所得の少ない方への援助等につきましては、学校用につきましては就学援助の制度の中で、一定の制限がありますが、所得の少ない方の援助を実施しています。","voiceIndex":337,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"私が言っているのは、このままいったら、もう所得制限がない無償化が、そういう支援がどんどん増えてしまうのではないですかということです。一定の人ではないですか。今ここで私は、次に申し上げることをお聞きします。教育格差です。今、教育委員会は何をやるのですか。経済的負担を軽減するために動いているのですか。子どもたちを助けるために動いているのではないですか。こんなことでいいのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"様々な教育課題がありますけれども、例えばいじめ問題、不登校問題、不登校支援につきましても、十分な予算をつけながら、いじめの解消や不登校支援につなげているところです。そういったところがおろそかにならないような取組は、今後も引き続き続けてまいります。","voiceIndex":340,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"私が言っているのは、教育委員会は何を優先しているのですか。どうやったら助けていけるのか。だけど、結果はどうですか。今、品川区の中で、もう小学生の総数が１万７,６００名、中学生の総数が約５,０００名。そして、公立小学校から公立中学校へ、進学率を計算したら５５％です。これは、公立学校に対する信認がないということですか。こういうことに対して、どのように責任を感じているのですか。","respondent":"柏木学務課長","answer":"ですので、先ほどセンター長からもご答弁がございましたけれども、不登校対策等についても、いじめ対策についても、予算を増やして実施しています。それと、私立の進学率ですけれども、若干増えているところは事実です。","voiceIndex":342,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"そういう数字を、教育委員会の数字を見て、私は言ったのです。それを計算したら、そういう結果になった。どうやって人を集めているのか。やはり私は、そこにもっと真剣に取り組んでほしい。私が議員になったときは、２５％ぐらいの方が私立または国立中学校に行っていた。今、４０％、４５％も行っているというのは、私は考えるべきだと思うのです。その辺はどうですか。もう一度ご答弁をお願いいたします。","respondent":"中谷指導課長","answer":"そして今、９年間の一貫教育の成果というものは常に把握しておりまして、特に次年度については、義務教育学校を設立して１０年になるという節目において、いま一度、この９年間の一貫教育の成果というのがどこにあるのかというのをしっかり発信しようということで。","voiceIndex":344,"id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"ある区内公立中学校の中学３年生の定期テストを私は見せていただきました。英語、数学、国語の点数が４０点以下の生徒が１５％もいました。そういう気持ちで指導していかないと、教えていかないといけないのではないですか。先生は３年たったらいなくなってしまう。こんなのでいいのですか。東京都がくれないですから。もらえないですから。これに対してどのようにお考えですか。お答えください。","respondent":"中谷指導課長","answer":"一方で、理科や社会といった、数字で目に見えている課題というのがございまして、こちらについて、教科部会を立ち上げて、有識者の方や校長先生方と議論を深めているところです。こういった取組を、授業がよりよくできることにつなげてまいりたいと考えています。","voiceIndex":346,"id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"提案","question":"私からも、３９９ページの学校給食食材費から有機農産物の活用について伺いたいと思います。は全ての野菜ではなくて、一部の野菜から始めてはどうかといった提案の声も届いていますが、いかがでしょうかということ。そして、そうした提案や懸念の声といったものが、意見書として学校栄養職員会から学務課に提出されていると思いますけれども、把握はされているでしょうか。伺いたいと思います。","respondent":"柏木学務課長","answer":"対象野菜については、学校に野菜の納品を行う複数の地元の既存の事業者より、円滑かつ持続的に本取組を進めるよう、様々なご提案を頂いております。市場の動向や現場の実態に耳を傾けながら、接続可能な発注・供給が図れる方策を今後検討してまいります。","voiceIndex":349,"id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現場の声というところで、市場の声は聞かれているようですけれども、ほかの委員からも多々質問があるように、現場としてはプレス発表で初めて聞いたということで、混乱を来しているわけです。なので、丁寧に現場の声を聞き、中小の業者の経営も守っていただきたい。これは本当に求めておきたいと思います。ここの理由を区はどう考えているのか、お考えを教えてください。","respondent":"柏木学務課長","answer":"一律にどうかというのは、私どもは、学校はおいしい給食を提供していると考えていますけれども、やはり、食育等の観点からも、また国の基準等からも、いろいろな食を提供するということを実施しておりますので。","voiceIndex":351,"id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区立小・中学校の４６校中、栄養士は、東京都の採用、都費の栄養士が２３人。２校を担当し、１校配置されているという２３人です。配置されていない２３校に、民間の栄養士が配置されている。とても権限が狭いのです。これは本当に現場で確認されております。こうしたところを、ぜひ把握していただきたいと思います。調理師の民営化はやめて、直営にするよう求めますけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"栄養士の委託につきましては、都の配置が２校に１校ということですので、それ以外のところについては業務委託で栄養士を配置していますが、ほとんど栄養士と同様の業務について実施していただいております。","voiceIndex":353,"id":"exchange-159"},{"speaker":"大倉委員","kind":"質問・要望","question":"岐阜市の「みんなの森ぎふメディアコスモス」というところ。今、１人で静かに本を読んだり勉強したりするスペースというところから、みんなで話し合って議論しながら勉強する図書館といった流れも今あるというお話で、その中で、こうした子どもたち、児童・生徒が、大人も含めてですが、グループで勉強や話合いができるような環境づくりをぜひ進めていっていただきたいと思いますが、いかがでしょうか。","respondent":"中谷指導課長、河内品川図書館長、丸谷教育総合支援センター長","answer":"こちらの中で、全ての幼稚園・保育園・小学校の教員が一堂に会して、エリアで協議することができるような場づくりができる研修会になっておりまして。知る権利というところは非常に大事なところで、今後また学生が気軽に、学習にもぜひ活用していただきたいと思っているのですが、そういった工夫をしながら。現在の部活動指導員の配置状況ですけれども、今年度、６０名の枠がありますが、現在４１名の登録があります。","voiceIndex":357,"id":"exchange-160"},{"speaker":"大倉委員","kind":"提案","question":"代表質問でもお聞きしたのですが、確認です。確認なので、そこができないのかどうかということを教えてください。次に学校の建て替えのところなのですが、これも以前もご提案させていただいておりまして、様々、学校の改築、建て替えの際には、通っている子どもたち、児童・生徒は当然ですが、地域の卒業生も併せて、様々、触れ合う機会を取っていただきたいということで要望しています。","respondent":"丸谷教育総合支援センター長、中谷指導課長、荒木学校施設担当課長","answer":"学校に配当された予算の範囲内で、併用させるかどうかは学校の判断になってまいります。時給に関しましては、今年度１,２５０円だったものを次年度１,４８０円に上げていくという見込みになってあります。ですので、こういったＶＲ、ＡＲというものも含めまして、今後どういった形で記録・保存していき、発信していけるのかということを。","voiceIndex":361,"id":"exchange-161"},{"speaker":"大倉委員","kind":"確認","question":"一点、地域コーディネーターはなかなか、１年目で辞めてしまう方というのが多いと伺っております。実際に、部活動指導員と外部指導員を併用している学校の方から、併用は実はできないのですという、制度がありますということで、確認が私のほうに来ましたので、改めて、別に併用はできると。ぜひこの辺は、これから前向きに検討していっていただければと思いますので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":365,"id":"exchange-162"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３９９ページ、標準服購入費用保護者負担軽減事業について伺ってまいります。区内の義務教育学校６校の中には、後期課程・中学校に該当する７年生からではなく、５年生で標準服のデザインが変わる学校があるということですが、それは６校中、何校なのでしょうか。そして、なぜ義務教育学校では一般的な７年生進級ではなく、５年生進級のタイミングでのデザインのチェンジ・買換えなのか。","respondent":"柏木学務課長","answer":"だから、ボタンを右につけたり左につけたりできるようになっているという形で、５年生以上は男性用・女性用という上着に変わってくるです。","voiceIndex":367,"id":"exchange-163"},{"speaker":"あくつ委員","kind":"質問・要望","question":"保護者負担の軽減と児童・生徒の円滑な学校生活を実現するという事業目的を達成するためには、義務教育学校での標準服の無償化については、７年生のタイミングだけではなく、先ほどもありました、５年生もしくは７年生に進級するタイミングのどちらかを選択できるように、柔軟な運用を行っていただきたいと思いますが、これはできるのかできないのかも含めて、はっきりしたご答弁をお願いいたします。","respondent":"柏木学務課長","answer":"本事業ですけれども、令和７年度中に標準服を購入する、令和８年度の新７年生を対象としておりますが、それまでの間に義務教育学校の対象学年については、柔軟な対応も含めて検討していきたいと考えています。","voiceIndex":369,"id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問","question":"もう一度、答弁をお願いしたいのです。では、これは前向きに、ＰＴＡ会長ほか皆さんには、５年生から制服はチェンジできる、無償でできるとお答えしていいかどうか、もう一度答弁をお願いしたいと思います。続いて質問します。その中で、体操着を利用している学校があれば、何校あるのか教えてください。","respondent":"柏木学務課長","answer":"先ほどの答弁の件ですが、前向きに検討してまいります。続きましてリユースの活動ですが、義務教育学校、あと中学校全校、全１５校とも何らかの形でリユース事業を実施しています。体操着のリユースですが、９校が体操着をリユースしていると確認しています。","voiceIndex":371,"id":"exchange-165"},{"speaker":"あくつ委員","kind":"質問・要望","question":"お伺いします。ＳＤＧｓ未来都市モデル都市として、このリース事業の持つ意義、品川区が行うというものの意義を教えてください。これは区民の方からもありました。「学用品はリユースしたほうがいいんじゃないですか」というご意見もありましたが、この辺りを教えていただければと思います。今回これを要望させていただきたいのですけれども、現在、体操着には名札をつけなければいけないことになっています。","respondent":"柏木学務課長","answer":"名札ですが、刺しゅうの名札を使っている学校があるのは確認しています。その拡充、取付け・取り外しについても、今後、事業者等と、拡大を含めて検討させていただきたいと考えています。","voiceIndex":373,"id":"exchange-166"},{"speaker":"まつざわ委員","kind":"確認","question":"私からは、予算書３７５ページのクラブ・部活動等経費と、３８５ページの不登校対策事業費について質問します。は地域部活動の移行です。先ほどの答弁で、６０分の４１、６０人いる中の配置が４１人と進んでいるということは確認しました。一方で文化部の考え方です。文化部と今の状況というのがどういうふうになっているのか、お聞かせください。","respondent":"中谷指導課長","answer":"地域部活動の文化部についてのご質問に対して、お答えします。今年度、「しながわ地域 ＴＥＡＭ ＡＣＴ」の文化部の設立を検討していくために、指導課としてアート部の設立を決定したところです。","voiceIndex":376,"id":"exchange-167"},{"speaker":"まつざわ委員","kind":"提案","question":"品川区は全区で音楽部というのがあって、やはりそれだけ、何というのですか、音楽に力を入れている区だと私は思っていますので、例えば音楽部員が少なくなった部活、そしてまた文化部も含めて、そういったものをしっかりと統合して、チーム品川と言うと大きくなってしまいますけれども、ある程度、地区地区でチーム品川という部分にスポットを当てて。","respondent":"中谷指導課長","answer":"絵を描くというようなところの部分もあれば、例えばデジタルで作る、３Ｄプリンターを使ったものもぜひとか、あと音楽に関する声なども頂いているところですので、関係各所からの前向きな意見も頂けているので、生徒の声と、それから何が実現できるかというところを。","voiceIndex":378,"id":"exchange-168"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ検討して進めていただきたいと思います。次に、６０分の４１という部分で、指導者のご苦労というのは多分あると思っています。新聞記事なのですけれども、日本体育大学。これは、まず連携協定を結んでいる自治体から派遣すると、新聞には書いてありましたけれども、例えばこの体育大学との協定をしっかりと結びまして、この指導者の課題解決の一助にするべきと思いますが、ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"日本体育大学と東京都教育委員会との連携協力に関する協定締結が令和５年１２月に行われていると承知しております。こちらのことについて、都内の各自治体で、大学生の派遣に至るまでの具体的な内容の提供について周知を待っているというところになっております。","voiceIndex":380,"id":"exchange-169"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"私も去年の第２回定例会の一般質問で言わせていただきましたけれども、まず不登校支援は、親が子どもよりも一番、精神的なストレスを感じているので、やはり親支援をしっかりしていかないと、その家庭が明るくならない。その中で、まず相談窓口、そして支援プログラム、現在、品川区がやっているのは、どんな取組があるのかお聞きしたいのと、その件数、また、利用率を教えてください。","respondent":"丸谷教育総合支援センター長","answer":"保護者への支援というところで、我々はマイスクールの一環で「ファミリークラブ品川」という取組を行っております。今年度につきましては、８月３日に行ったものは、保護者が３６名の参加、１１月にも行っておりますけれども、こちらも延べ６５名の参加という形になってあります。","voiceIndex":382,"id":"exchange-170"},{"speaker":"まつざわ委員","kind":"意見","question":"例えば保護者の中、３６名、６５名の保護者の悩みというのは、例えば何が一番多いのかなという聞き取りです。それで、また支援、「ファミリークラブ品川」に来ていただいた方の保護者の満足度、また課題として指摘されているようなお話があるのか、聞かせてください。","respondent":"丸谷教育総合支援センター長","answer":"課題というところですけれども、やはりなかなか簡単な復帰というところは難しいというところは、課題として挙げられているところです。","voiceIndex":384,"id":"exchange-171"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"課題として、復帰が難しい。これは大変な、重要なことですね。そしてまた、何ですか、低学年で不登校になるというのはなかなか少ないというケースがありますけれども、保護者が例えばひとり親など、そこに、親が支援に持っていくと、働くことがなかなかできないといった意味では、例えば専門医をつけていく必要があると思いますけれども、見解をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"ご提案の支援につきまして、早急にというのは難しいとは思いますけれども、真摯に受け止めまして、検討したいと思います。","voiceIndex":386,"id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7013#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":125584,"voices":388}},{"id":"r07-20250321-3","meetingId":"r07-c-budget","date":"2025年3月21日","dateIso":"2025-03-21","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時１７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"せお委員","kind":"質問","question":"初めに、施政方針から伺います。「貯蓄がないと生きていけない社会であるにもかかわらず、所得が増えず、貯蓄もできず、将来の見通しが立たない、自助による生存・生活ニーズの充足が困難であるのが今の社会ではないでしょうか。品川区は区民税の増など歳入が伸びていますが、施政方針にもありました２０４０問題など、先行き不透明な状況にあります。現時点での区のお考えをお聞かせください。","respondent":"森澤区長、久保田企画経営部長","answer":"令和７年度予算案では、これまでの取組をいま一度、人を基軸として、次元の異なる形で磨き上げ、中学校標準服をはじめとする、義務教育に係る保護者負担の軽減や、大学生への給付型奨学金の創設。引き続き、事業の効果等を検証しながら、社会情勢等の変化に応じた事業の見直しや、需要の減少した事業の縮小・スクラップを進めるとともに、行政評価の在り方や仕組みについても、他の自治体の事例を参考にしながら。","voiceIndex":2,"id":"exchange-001"},{"speaker":"せお委員","kind":"質問・要望","question":"ここからは、款別の質疑を踏まえて質問します。私たちの会派では、品川区の学校に給食の野菜を納入している３つの事業者の代表の方々にお話を伺いました。以上のことを踏まえ、まずはトライアルで、「有機野菜の日」などとイベント的に１０月以降行っていただき、そこから必ず効果検証を行っていただきたいと要望しますが、１０月以降のスケジュールを含めた区の見解をお聞かせください。","respondent":"米田教育次長","answer":"こうした考え方も肝要と考えております。アンケート調査の実施や定期的なモニタリング、効果の測定・検証等を行い、より効果的な施策となるよう、随時、施策の改善を図ってまいりたいと考えております。","voiceIndex":5,"id":"exchange-002"},{"speaker":"せお委員","kind":"質問","question":"有機農産物とはまた違った給食の課題がありましたので、ここからご質問いたします。ちなみに、令和５年度、令和４年度も、最下位ではない年はあるものの、ほぼ同様の結果でした。栄養バランスは考えてくださっているので安心してはおりますが、子どもたちの満足度を高めるには、肉類は必要ではないでしょうか。そこで、この結果は区として把握されていましたでしょうか。今後の取組について見解を伺います。","respondent":"米田教育次長","answer":"そのため、調査時の報告より、供給量は多くなっているものと認識しておりますが、毎年行っております栄養士による標準献立作成会につきましては、委員から頂いたご意見も踏まえ、改善策を検討し、児童・生徒の学校給食に対する満足度を上げてまいりたい。","voiceIndex":7,"id":"exchange-003"},{"speaker":"せお委員","kind":"質問","question":"障害児通所支援等利用者負担無償化についてお伺いします。ベーシックサービスを批判するつもりは毛頭ないのですが、１点だけ気になるのは、障害児通所支援等で利用者負担を無償化しても、そのサービスを利用できる人が限定される点です。このような放デイの課題は区として把握されていましたでしょうか。さらに、現在までの障害児通所施設の充実に向けた取組を教えてください。","respondent":"寺嶋福祉部長","answer":"先ほど委員からありましたように、令和に入ってから新規に２０か所を開設したということで、鋭意、こちらも開設に取り組んでいるところですけれども、それ以上に利用者ニーズが増加傾向にあるということで、供給が十分追いついていないということも。","voiceIndex":9,"id":"exchange-004"},{"speaker":"せお委員","kind":"提案","question":"これから提案しますけれども、課題を解決するのに施設数を増やすだけでは少し足りないかなと思っています。１つ目のご提案です。現在、重症心身障害児や医療的ケア児を受け入れれば助成が出ますが、自宅などで１人で過ごすことは困難で、療育施設においてＡＤＬを少しでも多く獲得したい知的障害児受入れの際にも、助成をつけることで受入れ拡大につながらないでしょうか。こちらも見解を伺います。","respondent":"寺嶋福祉部長","answer":"医療的ケアや重度心身障害のあるお子さんのほか、知的障害のあるお子さんについても、こちらも具体的な担い手の確保という課題の解決を模索しつつ、必要な加算についても積極的に検討を進めてまいります。","voiceIndex":11,"id":"exchange-005"},{"speaker":"せお委員","kind":"質問・要望","question":"前向きにご検討いただくということで、ぜひ品川区の状況を把握しながらも、そういった検討を進めていただきたいと思っています。次はハード面です。すまいるスクールに療育施設を併設するというのは少しハードルがありますが、すまいるスクールに短時間の療育ができるような専門家の配置を行っていただく、そういった検討も今後行っていただきたいのですが、こちらも見解をお聞かせください。","respondent":"寺嶋福祉部長","answer":"所管等とも確認いたしましたけれども、児童センター改修時における放課後等デイサービスの併設につきまして、まず現在改築予定の児童センターについては既に設計が完了しているということで、また、当面、新規の改築予定というのが今すぐにはないということなので。","voiceIndex":13,"id":"exchange-006"},{"speaker":"せお委員","kind":"提案","question":"様々ご検討いただけるということで、期待しております。予算特別委員会で、こうやってあえて様々な新しい提案をするのは、今言わなければならないことがあるからですので、まず早急にご検討をお願いしたいと思っています。児童発達支援は今回は取り上げませんでしたが、こちらも課題がありますので、違う機会で取り上げたいと思っています。そちらは要望で終わります。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-007"},{"speaker":"こしば委員","kind":"質問・要望","question":"せお委員に続きまして、３項目について総括質疑を致します。１つ目に大学奨学金と地域防災について、２つ目はデジタル商品券の在り方と進め方について、３つ目は広町二丁目を含めた大井町について、順に伺います。より多くの受験生に奨学金のチャンスを与えていただきたいと考えますが、奨学金の対象人数が今回１００人であることの根拠について、併せて教えてください。","respondent":"佐藤子ども未来部長","answer":"検討の経緯ですが、マスコミ等でも報道されているとおり、大学生の奨学金の必要性がさらに高まっております。現在実施している高校生の応援奨学金の学生や、子ども食堂フォーラムに参加した児童等からの要望等も受けまして、事業化に向けた検討を重ねてまいりました。","voiceIndex":17,"id":"exchange-008"},{"speaker":"こしば委員","kind":"質問・要望","question":"翌年度からは、対象人数を１００人から２００人に増やすと聞いております。つまり、初年度に受給対象になった方は２年目に入るわけですが、２年目以降については、効果測定といったものはあるのでしょうか。進学先によっては給付型の奨学金を受けることができなくなってしまいますので、これは一方では不公平感も感じますが、その辺りのお考えについて教えていただきたいと思います。","respondent":"佐藤子ども未来部長","answer":"ただし、全ての学部が社会において重要な役割を果たしていることは十分認識しております。そのため、国や都の支援策の動向を注視しつつ、区独自の子ども・子育て支援策についても引き続き検討を重ねてまいります。","voiceIndex":19,"id":"exchange-009"},{"speaker":"こしば委員","kind":"質問・要望","question":"対象外となる受験生の支援を、今後もあらゆる方面で検討・模索していただきたいと考えます。さて、奨学金を申請するに当たりましては、先ほど部長からの答弁もございましたが、ボランティア、地域活動への参加が条件と言われております。品川区の１３地域の中で、町会・自治会が抱えている課題について、区の認識をお伺いいたします。今後の町会・自治会の見通しについても併せて教えてください。","respondent":"川島地域振興部長","answer":"今後の見通しということにつきましては、これまで新たに個別課題に対応するための伴走支援なども導入して取り組んできたところですけれども、活動の担い手不足ということにつきましては、持続可能な町会・自治会活動に向けて大きな課題の一つであり、対策が非常に難しい状況です。","voiceIndex":21,"id":"exchange-010","title":"町会・自治会支援"},{"speaker":"こしば委員","kind":"質問・要望","question":"訓練内容も変わらない。地域防災力の向上には、防災士の資格取得に向けた補助により、若年者の参入が期待されますが、より多くの若い方の訓練参加を様々な切り口から取り込んでいただくことに、区が主体となって取り組まれることを望みますが、お考えはいかがでしょうか。奨学金受給の条件に、防災訓練への参加や、運営に参加してもらうことを検討いただきたいと思いますが、お考えを教えてください。","respondent":"滝澤災害対策担当部長、佐藤子ども未来部長","answer":"このような状況を受けて、令和７年度の防災訓練は、各地区が一律にＰＬＵＳ ＯＮＥ事業を実施するのではなく、各地区防災協議会の新たな取組を区が柔軟に支援すべく、様々な形で防災訓練を支援できる補助金を交付いたします。奨学金応募者のボランティア等に関わる意欲、地域貢献度、持続性等を重視し、多様なボランティア活動を対象にする方向で検討を進めております。地域の安全に大きく寄与する防災活動や消防団も含め、検討を進めてまいります。","voiceIndex":23,"id":"exchange-011"},{"speaker":"こしば委員","kind":"質問・要望","question":"奨学金の受給者については、全体の中で偏ることのないよう、区内全域に広がるイメージで決定していただきたいと考えますが、区のお考えを教えてください。奨学金の給付は持続事業ですので、効果測定は定期的に行うことで、この制度の形骸化といったものを防ぎ、実効性のある事業になると考えますが、併せて考えを教えてください。","respondent":"佐藤子ども未来部長","answer":"奨学金の受給者につきましては、公平かつ適切に選定するため、地域貢献の視点、学業成績、面接などを総合的に考慮する方向で検討を進めているところです。地域の偏りなどを防止するための方策については、関係部署と連携しながら検討を重ねてまいります。","voiceIndex":26,"id":"exchange-012"},{"speaker":"こしば委員","kind":"質問・要望","question":"寄附された方のご意向に沿って、これからも実効性のある効果測定を行っていただきたいと思います。続きまして、デジタル商品券の在り方と進め方についてお伺いいたします。そして、大型店舗の利用となりますと、個人の商店や商店街への影響もあることから、理解を求めることが必要と考えますが、商店街連合会とはどのように協議をされてきたのか、併せて教えてください。","respondent":"川島地域振興部長","answer":"従来の取扱い店舗以外でも利用されるよう、大型店舗も含めた検討を進めてきたところです。これをきっかけにしまして、若者の方と新たな層の商店街店舗での買物のきっかけとなることも期待しています。","voiceIndex":28,"id":"exchange-013"},{"speaker":"こしば委員","kind":"提案","question":"ただ一方で、消費者目線に立ちましたら、昨今の物価高騰は深刻な問題であります。その観点から、大型店舗の利用には、生鮮食品のみを対象にするなど、利用の制限を設けるのはいかがでしょうか。もしくは、大型店舗でも地域に根差した、生鮮食品を主に扱うスーパーを対象にするなど、様々な試行を通じまして、来年度はこの効果を検証することも提案いたしますが、いかがでしょうか。","respondent":"川島地域振興部長","answer":"すみません。先ほど、商店街連合会との協議の答弁が漏れておりましたが、しっかり協議を進めた上で対応しています。それから、ただいまの、例えば大型店舗での購入品目につきまして、品目を限定したらどうかといったご提案についてです。","voiceIndex":30,"id":"exchange-014"},{"speaker":"こしば委員","kind":"質問・要望","question":"決済システムの運用についてお聞きします。これから事業者のプロポーザルが始まると思われますが、選考に当たっては、ＱＲコード決済の事業者を複数にすることを選考基準の一つとしてご検討いただきたいと考えますが、お考えを教えてください。その際は、区の商店街連合会と連携して、決済システムの導入が速やかに行われるように取り組んでいただきたいと思いますが、見解をお伺いいたします。","respondent":"川島地域振興部長","answer":"デジタル商品券のプロポーザル審査におきまして、提案事業者に対しては、商店街や品川区商店街連合会等と連携し、導入システムの利用方法を説明すること、それから、特にデジタル機器の操作に苦手意識を持つ店舗に対し、デジタル化のメリットや。","voiceIndex":32,"id":"exchange-015"},{"speaker":"こしば委員","kind":"質問・要望","question":"そのポイントに、デジタルサイネージによる大井町の宣伝や、大井町西口を描いた特大のエリアマップを設置するなどして、広町の人々を誘引する仕掛けなど、視認性の高い掲示物の設置を、土地所有者のＪＲ東日本に働きかけていただきたいと考えますが、見解を伺います。大井町駅西口と広町の間で走行させることで、南北の回遊性にもつながると考えますが、併せて見解をお伺いいたします。","respondent":"品川広町事業担当部長、溝口防災まちづくり部長","answer":"これに加えて、来場者を周辺地区に誘導するソフト面の取組についても協議を重ねておりまして、周辺地区の町会や商店街、ＮＰＯまちづくり大井、さらには慶應義塾大学ＳＦＣ研究所とも連携しまして、駅前中央通りの車道の一部を歩道化し。委員ご案内のとおり、グリーンスローモビリティにつきましては、低速で移動するモビリティであることから、運行の実施に当たっては、渋滞の発生防止、また停車場所の選定など、様々、警察との調整や課題の解決が必要となっております。","voiceIndex":34,"id":"exchange-016"},{"speaker":"こしば委員","kind":"質問・要望","question":"先ほど部長からもご答弁がありましたとおり、様々な方々、また団体から多くの声を聞き、回遊性の向上に取り組んでいただきたいと思います。大井町駅周辺の現状のレンタルシェアサイクルの利用について、状況を教えてください。レンタルサイクルポートの設置を広町二丁目エリアに設置されることを前向きに検討いただきたいと思いますが、いかがでしょうか。","respondent":"溝口防災まちづくり部長","answer":"広町二丁目エリアにおけるシェアサイクルポートの設置につきましては、地域の回遊性の向上の観点からも、設置に向けて関係者と具体的な調整を現在進めているところです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"こしば委員","kind":"質問・要望","question":"回遊性だけでなく、ＪＲ大井町駅周辺の歩行者の安全にもつながるので、実施を求めてまいりたいと思います。最後に、広町二丁目は大井第二地域の管轄で、大井一丁目権現町会のエリアになると伺っております。新住人との連携については、町会があくまでも原則であり主体となりますが、持続可能なまちづくりのためにも品川区の支えを併せてお願いいたしますが、最後にお考えを教えてください。","respondent":"川島地域振興部長","answer":"このガイドブックなどを活用しまして、来年度はより実効的な支援を進めてまいる予定です。広町地区の開発に伴うマンションの住民の方への対応につきましても、町会からのご意見やご要望に丁寧に対応してまいります。","voiceIndex":39,"id":"exchange-018"},{"speaker":"こしば委員","kind":"質問","question":"ご答弁ありがとうあります。様々な取組を通じまして、新住民と町会との橋渡しに向けて、今後も実りある支援を強くお願いいたしまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-019"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"１点目は、火災発生時の初動体制について伺います。もう一方の火災では、発生の一報から２時間を超えて、職員が現場に到着されたと伺っています。一定規模の火災において、今後スムーズな支援体制の構築のために、平日・休日、日中・夜間対応について、当番体制による消防無線の傍受体制や、区役所内外にも明確に分かるような出動フローの作成、支援体制の拡充を要望しますが、いかがでしょうか。","respondent":"滝澤災害対策担当部長","answer":"しかしながら、ただいま課題についてご提示いただいたところですので、複数の火災が発生した場合などを含め、現時点での対応における問題点を分析して、消防との連携強化や、さらなる支援体制の充実に向けて必要な拡充施策があるか、また。","voiceIndex":43,"id":"exchange-020"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"今回のように、火災用に準備していた居室が足りなくなった場合、従前居住者用住宅の空き室を調整して、緊急な利用ができるように要望しますが、区の見解をお聞きします。今回同時期に複数の火災発生により、複数の長期避難者が発生しましたが、ソレイユ戸越以外の２つの従前居住者用住宅にも、火災被災者が滞在可能な居室を常設で準備・確保することを求めますが、区の見解をお聞きします。","respondent":"鈴木都市環境部長","answer":"区としましては、一定期間での滞在が必要となった方に対しても、従前居住者用住宅の空き室等の状況に応じて、受入れについてその都度、個別に検討を行うなど、火災に遭われた方に対し、しっかりと寄り添った対応を行ってまいります。","voiceIndex":45,"id":"exchange-021"},{"speaker":"ゆきた副委員長","kind":"提案","question":"道路の空洞調査の拡充について質問します。公明党は、平成２４年第３回定例会で、前年に発生した東日本大震災の際、仙台市立病院前の道路が広範囲に陥没し、救急車の通行ができなくなった事例から、道路下の空洞調査の実施を提案し、品川区では３年間の空洞調査が実施されました。そこで、現在までの空洞調査により確認できた空洞の規模と箇所数についてお聞きします。","respondent":"溝口防災まちづくり部長","answer":"私からは、空洞調査についてお答えします。令和３年度から令和６年度までに確認できた、対応が必要な空洞は、８か所確認できており、全て既に修繕が終わっているところです。空洞の規模といたしましては、大きいもので直径１メートル程度の空洞も確認されたところです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"ゆきた副委員長","kind":"確認","question":"品川区でも一定の対策が取られていることを確認しました。その上で、区民の陥没事故に関する不安を払拭するためにも、緊急の空洞調査を実施すべきと考えますが、いかがでしょうか。品川区においても、点検で蓄積したデータを活かし、陥没ポテンシャルマップの導入により、継続的に危険度の優先順位を可視化できる体制づくりが必要と考えますが、見解を伺います。","respondent":"溝口防災まちづくり部長","answer":"区としても来年度以降につきましては、内径２メートル以上の下水道管路のルートを空洞調査の対象に追加することを予定しておりまして、引き続き下水道局と連携を図りながら、今回の事故の対応についても区として道路管理者として進めていきたいと考えているところです。","voiceIndex":49,"id":"exchange-023"},{"speaker":"ゆきた副委員長","kind":"提案","question":"款別審査で確認したとおり、２３区初となる図書館中心の複合機能施設として、今後区民の新たなにぎわいの場として品川区の都市ブランディングをさらに向上させる目玉になる可能性を秘めています。大きな期待の一方で、過去に例のない１１項目もの機能を導入する上、従来とは異なるコンセプトと仕組みで整備・運営されることから、確認と提案をしてまいります。１点目は、事業手法について伺います。","respondent":"久保田企画経営部長","answer":"令和５年度に設置いたしました跡地活用方針策定委員会におきまして、行政需要や地域のニーズ、また地域住民とのワークショップ等から、コンセプトを、「多様な人々が集い・学び・助け合い・心と体の健康を育む交流拠点」と整理したところであります。","voiceIndex":51,"id":"exchange-024"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"２点目は、デザイン・ゾーニングと図書館機能の強化について伺います。款別審査で確認したところ、図書館の入る構造物について、旧荏原第四中学校と同規模の４階程度の高さが想定されるが、性能発注という事業手法の特性上、計画案では詳細を示していないとのことでした。その点を強調した事業者選定を望みますが、いかがでしょうか。今回の機能の中で期待される最も重要なものは図書館機能であると考えます。","respondent":"久保田企画経営部長","answer":"来館者数の目標設定等についてですけれども、民間業者の提案も聞きながら検討していくこととしておりますが、現時点では、同施設内に整備されますカフェや屋内キッズプレイルームなどとの連続性を重視するとともに。","voiceIndex":53,"id":"exchange-025"},{"speaker":"ゆきた副委員長","kind":"質問","question":"３点目は、学習・自習スペース、そして防災機能の確保について伺います。そこで、区として学習・自習スペースのニーズをどのように捉えているのか伺います。サードプレイス、学びの拠点という複合施設において、区民ニーズを踏まえた上で、図書館機能との連続性を維持しながら、独立して、無料・有料を含む仕切られた自習・学習スペースを確保する必要があると思いますが、いかがでしょうか。","respondent":"久保田企画経営部長","answer":"自習・学習スペースの整備に当たりましては、庁内での議論を深めるとともに、民間事業者とのサウンディングにおきましても、ただいまご説明しました区民ニーズをしっかりと事業者に伝え、反映させるよう。","voiceIndex":55,"id":"exchange-026"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"基本計画では、跡地の活用策として、地域住民の皆様からご要望が一番多かった、防災拠点としての機能が明確に示されています。そこで、解体建設中に災害が発生した場合の地元町会の避難先として、帰宅困難者対策の一時滞在施設であり、補完避難所として指定されている近隣の都立大崎高校を活用できるように、東京都と協議していただきたいと考えますが、ご見解を伺います。","respondent":"久保田企画経営部長","answer":"施設整備後におきましても避難所運営等の主体は変わりませんが、本施設は指定管理施設として、事業者が施設管理の役割を担うため、地域の防災訓練への参加や、発災時における緊急対応を行うなど、ソフト面においても防災機能の向上が図られるよう。","voiceIndex":57,"id":"exchange-027"},{"speaker":"新妻委員","kind":"提案","question":"２０２５年度予算案では、ウェルビーイング予算２.０として、中学校標準服・制服や中学校修学旅行費を所得制限なく無償化、所得制限のない給付型大学奨学金制度の創設、所得や子どもの人数を問わない、第１子、０歳から２歳保育料無償化、「小１の壁」解消支援、朝の児童の居場所確保など、公明党が提案・要望してきたことが反映され、品川区でのベーシックサービスが展開されていることを評価いたします。","respondent":"米田教育次長、佐藤子ども未来部長","answer":"ご質問のうち、教育委員会の部分に関してお答えします。区立小学校・義務教育学校（前期課程）の給食費無償化の令和７年度の予算規模についてですが、約１２億６,０００万円を予定しております。私からは、区内幼稚園の児童・生徒数についてお答えいたします。給食の提供の有無・形態等々、様々ありますが、現在、区立幼稚園には約４３０人、私立幼稚園には約１,８００人の園児が在園しております。","voiceIndex":62,"id":"exchange-028"},{"speaker":"新妻委員","kind":"提案","question":"見解を伺います。導入に当たっては、今後の給食業務に支障が出ないよう、これまで学校給食の食材を支えてくださっている地元地域の納入業者、八百屋、また栄養士・調理師をはじめ、給食に関わる現場の方々のご意見をしっかり聞いていただきたいと要望します。併せて見解を伺います。寄附をお受けしても、このまま当初予算を維持し、安定した給食の提供と質の向上につながるよう要望します。見解を伺います。","respondent":"米田教育次長","answer":"令和７年度当初予算では、有機農産物等の活用推進分について一般財源を充当しておりますが、当該分の一般財源は、年度途中での食材費高騰など不測の事態にも対応できるよう、今後の歳出状況をにらみつつ、企画経営部と協議しながら検討してまいります。","voiceIndex":65,"id":"exchange-029"},{"speaker":"新妻委員","kind":"質問・要望","question":"改めて、安定した給食の提供を要望いたしまして、次の質問といたします。次に、高齢者まるごと支援について伺います。毎回３０人前後の方が集まり、輪投げや茶話会など、交流されています。特に落語の開催では５０人ほど集まり、非常に好評だとのお話を伺いました。そこで、地域での見守り活動の重要性について、区の認識を伺います。見守り活動助成事業について拡充を求めますが、見解を伺います。","respondent":"寺嶋福祉部長","answer":"活動の必要性についての区の認識ですけれども、地域での見守り活動に関しても、大変重要な取組と区でも認識しています。ほかの事業、例えば救急代理通報システムや、民間企業との協定による見守りといったものとも補完し合いながら、施策を進めているところです。","voiceIndex":67,"id":"exchange-030"},{"speaker":"新妻委員","kind":"質問・要望","question":"前向きなご答弁を頂きまして、ありがとうあります。支援する側、当事者が手間なく申請できるよう、パンフレットには申請書を添付することや、電子申請用のＱＲコードの掲載を要望いたします。他地域でも徹底した周知を要望します。例えば、高齢者クラブの集い、町会・自治会の集い等へ、支え愛・ほっとステーションのスタッフ等が出向いてのお知らせや出張申請などを行うなど要望しますが、見解を伺います。","respondent":"寺嶋福祉部長","answer":"支え愛・ほっとステーションと連携した周知ですけれども、こちらについては効果的な方法、効率的な方法をさらに検討しまして、さらなる周知の強化に努めてまいりたいと考えております。","voiceIndex":69,"id":"exchange-031","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"提案","question":"高齢者の方が知らないということがないように、周知も、また改めて要望して、次の質問に行きます。新年度は終活支援パッケージ事業として取組が進むことになり、歓迎します。「あんしんの３点セット」の登録の際は、終活の考え方をお伝えしながら、ご本人の尊厳が尊重されるよう、登録を進めていただきたいと思いますが、周知はどのように行っていくのか、お伺いします。ここで答弁を頂きたいと思います。","respondent":"寺嶋福祉部長","answer":"終活支援パッケージの事業内容のご質問です。現在、社会福祉協議会が実施している「あんしんの３点セット」の１点目は、ひとり暮らしの高齢者の方の見守りや日常の生活支援を行う「あんしんサービス契約」です。","voiceIndex":71,"id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"ひとり暮らしの高齢者など、区民の方から、「財産はないけど、自分の死後の手続や葬儀、お墓のことを誰かにお願いしたい」といったお声が多くあります。「あんしんの３点セット」の公正証書遺言作成での死後事務委任が有効です。将来的に登録者が増えた場合の人的な整備については、区民のニーズに応えられるよう、社会福祉協議会の整備を求めます。それぞれ見解を伺います。","respondent":"寺嶋福祉部長","answer":"こういったことからも、区と十分に連携を図って本事業をますます進めていこうということで、取り組みたいと考えています。","voiceIndex":73,"id":"exchange-033"},{"speaker":"新妻委員","kind":"質問・要望","question":"今こそ、いつ起きてもおかしくない大災害を想定し、区は、災害関連死を一人も出さないとの強い決意の下、避難所の整備に臨んでいただきたいと要望いたします。プレス発表では、スフィア基準に対応した避難所の整備とありましたので、「ＴＫＢＢ」の「Ｔ」はトイレ、「Ｋ」はキッチン・温かい食事、「Ｂ」はベッドとお風呂について確認します。本年度、品川区は全区民へ携帯トイレを３日間分、配布しました。","respondent":"滝澤災害対策担当部長","answer":"品川区トイレ確保計画を作成することで、発災後の時間経過における避難者数の増減に対して、各区民避難所で使用できる災害用トイレの過不足をお示しする予定であり、過不足の状況に応じて、今後の災害用トイレの確保の対策を具体的に進めてまいりたいと考えております。","voiceIndex":75,"id":"exchange-034"},{"speaker":"新妻委員","kind":"提案","question":"キッチン・温かい食事の提供です。昨年の第１回定例会一般質問で会派から、「現在、区と防災協定を締結している飲食業生活衛生同業組合や企業と２件の炊き出しのほかにも拡充を」と提案し、「引き続き、飲食業関係者と連携した体制整備をしていく」との答弁がありました。その後の食事の提供に関する防災協定の進展状況と、キッチンカーの整備状況を併せて伺います。","respondent":"滝澤災害対策担当部長","answer":"キッチンカーに関する災害時協力協定についてですが、これまで実績はございませんでしたが、令和７年度に新たにキッチンカー事業者との協定締結を予定しております。","voiceIndex":77,"id":"exchange-035"},{"speaker":"新妻委員","kind":"質問・要望","question":"各避難所への配置数や配置場所、活用の仕方をお伺いします。保管場所の確保とともに、さらに増やしていくよう要望します。最後に、例えばトイレトラックの助けあいジャパンのように、水循環型シャワーにおいても、多くの自治体が導入し、災害時には相互協力をし合うネットワークづくりを、森澤区長が中心となって行っていただきたいと思いますが、いかがでしょうか。それぞれお伺いいたします。","respondent":"滝澤災害対策担当部長","answer":"区といたしましては、２３区初の導入自治体として、トイレトラックと同様に、各自治体への情報提供を積極的に行い、被災地支援の助け合いの輪を全国へ広げていけるよう取り組んでまいりたいと思います。","voiceIndex":79,"id":"exchange-036"},{"speaker":"山本副委員長","kind":"質問","question":"区民の皆様から納めていただいた貴重な税金を有効活用するという意味で、民間の当たり前である、無駄を削減するという観点から、庁舎整備資金の負担軽減について伺います。税金の使い方に対する考え方について伺います。貴重な財源は一円も無駄遣いできないという考え方でよいでしょうか。ここまで事業費が上昇している中、できるだけ関連費用を削減したいという考えかどうか、区の見解を伺います。","respondent":"久保田企画経営部長、黒田新庁舎整備担当部長","answer":"税金の使途につきましてですが、私どもは無駄のないように、最大限の効率化と適正な執行に努めることが重要であると認識しております。この考え方を基本に、区民の幸せの実現のための施策の推進に努めているところです。このような中におきましても、令和７年度予算編成に当たりまして、実施設計を進める中で、庁舎に求められる災害などの拠点機能や行政機能などは維持しながら、内装仕上げ材、機械設備などの各仕様を見直しすることなどによりまして。","voiceIndex":84,"id":"exchange-037"},{"speaker":"山本副委員長","kind":"確認","question":"ご説明ありがとうございました。無駄にはしないということと、区の負担がこれだけ増えているということについて確認いたしました。続けます。これまで款別審査でもご答弁がありましたが、改めて庁舎整備資金に対する資金調達について、来年度の調達内容とそれ以降の方針についてお教えください。それから、現在想定している金利水準と利払い額についてお教えください。","respondent":"加島財政課長","answer":"次年度以降、令和１１年度までの調達方針につきましても、現時点では同様に考えております。次に、銀行等引受け資金を選択した理由ですけれども、特別区のルールに基づきまして、低金利での資金調達が見込めることなどが主に挙げられます。","voiceIndex":87,"id":"exchange-038"},{"speaker":"山本副委員長","kind":"質問","question":"分かりました。１年ごとの調達ごとに期間５年間ですが、２０年の償還ペースなので、その後の借換えを含めて通算４回の調達となることで理解いたしました。具体的な数値で表してみます。分かりやすくするため、総調達額である４１３億円を４００億円とし、一括で調達した計算として比較いたします。そこで伺います。定時償還を組み合わせることを検討したのでしょうか。このような考えに対する見解を伺います。","respondent":"加島財政課長","answer":"令和７年度につきましては、証券発行による方式のほうが金利が安価であることから、証券発行方式での満期一括償還を選択いたしました。","voiceIndex":89,"id":"exchange-039","title":"町会・自治会支援"},{"speaker":"山本副委員長","kind":"提案","question":"であるならば、ご提案する定時償還型については、銀行が引き受ける方式ではなく、定時償還ができる、市場で公募する市場公募債での調達を検討し、比較して、より安いほうを選択するほうが有効ではないかと考えます。そこで伺います。このような比較はしたのでしょうか。そうすれば、品川区だけではなく２３区全体で調達コストの削減ができると考えますが、いかがでしょうか。おのおのご見解を伺います。","respondent":"加島財政課長","answer":"初めに、比較検討というところですけれども、特別区のルールに基づきまして、現時点で最も金利が低い証券発行による銀行等引受け資金を選択いたしましたので、市場公募債との具体的な比較検討は行いませんでした。","voiceIndex":91,"id":"exchange-040"},{"speaker":"山本副委員長","kind":"提案","question":"お考えは分かりました。現在の期間５年ごとの調達では、５年ごとの借換えのタイミングで金利が上がるリスクがあります。そこで、現在の調達と２０年定時償還型との比較検討を提案いたします。いかがでしょうか。グリーンボンドについて、財政的な観点とＳＤＧｓ推進の観点の双方から見解を伺います。住民参加型市場公募債について、庁舎への愛着、区へのエンゲージメントを高める手法としての見解を伺います。","respondent":"加島財政課長","answer":"初めにご質問いただきました件ですけれども、特別区における銀行等引受け資金につきましては、償還方法が５年または１０年の満期一括償還方式となっております。次年度以降の調達につきましても、現時点では５年満期一括償還を考えております。","voiceIndex":93,"id":"exchange-041"},{"speaker":"山本副委員長","kind":"質問","question":"考え方について分かりました。それぞれメリット・効果があります。これまでいろいろと申し上げましたが、４００億円を超える調達に対する金利負担の影響は大きく、銀行引受け債だけでなく、様々な手法を検討した上で、コスト削減やその他の目的も踏まえてしっかりと最適な調達手法を検討するべきであると考えます。改めてご見解を伺います。ご見解を伺います。いかがでしょうか。以上、ご見解を伺います。","respondent":"加島財政課長","answer":"そういったシミュレーションの中で、金利の動向も踏まえまして、各年度における投資的経費の最適規模につきまして検討してまいりたいと考えております。","voiceIndex":95,"id":"exchange-042"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご答弁ありがとうあります。次に、縦割り行政に横串を入れ、コスト削減や効率運用を図るという観点から、中学校標準服無償化の方法について伺います。そこで、具体的な手法について伺います。区が認識する課題をお教えください。既にクーポンという考えも他議員から示されていますが、さらに一歩進んで、紙ではなくデジタルクーポンでの配布を要望いたします。いかがでしょうか。おのおの見解を伺います。","respondent":"米田教育次長","answer":"ご提案のデジタルクーポンの活用についてですけれども、標準服の購入方法については、現在検討を進めているところですが、委員からご提案の内容も含めまして、販売店、保護者ともに負担の少なく効率的な方法について検討を重ねてまいります。","voiceIndex":97,"id":"exchange-043"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。この配布方法、デジタルクーポンの検討に当たっては、区の施策全体を踏まえての検討が重要であると考えます。このような考え方について見解を伺います。そのような観点で、事業単体だけではなく、区全体としての事業者選定を進めることが重要であると考えますが、併せて見解を伺います。","respondent":"久保田企画経営部長","answer":"組織横断的な検討等のご質疑にお答えいたします。現在も区政全般にわたる課題につきましては、企画経営部が中心となりまして、各部署と緊密に連携し、横断的な事業調整を行っております。","voiceIndex":99,"id":"exchange-044"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご回答ありがとうあります。区民目線に立って、コスト削減や効率化運用を区全体で図るという観点から、区として効率的・効果的な施策判断を今後もしていただけるよう要望しまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-045"},{"speaker":"吉田委員","kind":"提案","question":"質問の視点としては、政策案を議会に提案する前に、その政策に関わる人たちへ先に情報提供し、意見を聞くという手順を入れることは是か非かということと、また一旦決まった政策・事業を、現場の意見、事業の利用者として想定できる人たちの意見で変更することは可能かということです。そういう事例として理解してよろしいでしょうかというのが質問です。その２点について、まず伺います。","respondent":"寺嶋福祉部長","answer":"一方で、整備の方向が決まった後ということになりますけれども、個別の説明会を実施しまして、当事者の方のご意見を丁寧に聞きながら、可能な限りでそういったご意見を反映できるようにも努めているところです。","voiceIndex":103,"id":"exchange-046"},{"speaker":"吉田委員","kind":"提案","question":"先ほど、質問の仕方が悪かったかもしれないですけれども、就労継続支援Ｂ型については、どんな事業をやるかということについて、当事者、利用したいと思っている人たちの意見を聞いてほしいということだったのですけれども、そのときのご答弁では、あくまで事業者の提案を待つということだったので、その点についての当事者と事業者の提案とのバランスといいますか、決定の過程について伺いたいと思います。","respondent":"久保田企画経営部長、寺嶋福祉部長","answer":"予算案を議会にご提案してご審議いただいて、いろいろと意見をもらうことが、これまでたくさんありますので、私どもとしましては、具体的な事業の執行に至るまでには。就労継続支援Ｂ型の業務内容というご質問がございましたけれども、先ほど事業者の提案に任せるという、一部の発言の部分だけだと私は理解しているのですが、これは事業者側から見てどういったことが提供できるかという視点では、当然。","voiceIndex":105,"id":"exchange-047"},{"speaker":"吉田委員","kind":"提案","question":"分かりました。今度、事業者も当事者ですから、最初に手を挙げて提案したときと事業内容が変わるとなると、当然、契約金額の中身も変わると思いますし、その辺については大丈夫なのでしょうかということが１つ。あるいは、障害者団体から、「いや、こういう事業者もあるのだけれども、その辺についての委託は考えられないのか」など、ご意見は伺ったのかということを確認したいと思います。","respondent":"寺嶋福祉部長","answer":"こういった提案型みたいなものはほかの場合でも通常あり得る話なので、それはぜひトライアルしてみようということで進んだので、先ほどご指摘があったようなほかの事業者がということについては、例えば今回この超短時間就労支援事業がかなりの効果を上げまして。","voiceIndex":108,"id":"exchange-048","title":"町会・自治会支援"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。そういう積み上げの中から始まったということですが、でも一方で、やはり民間の事業者として、そういう就労支援をやっているところも現にあるわけですし、それなりの実績も上げておられるので、そういうところへの丁寧な説明なども、やはり今後、品川区全体でこういう事業を広げるに当たっても必要な手順ではないかと思うのですけれども、その点についてはいかがでしょうか。","respondent":"久保田企画経営部長、寺嶋福祉部長","answer":"事業のいろいろな変更の部分の話ですけれども、先ほど福祉部長からは福祉の部分でのご答弁がありましたが、全体的な形としましては、福祉部長が説明したような流れということは我々も十分認識しておりますし。我々の立場としては、むしろやっていただける事業者を探すのが、特に福祉に関してはなかなか大変な部分がありまして、そういった意味では、先ほど委員からお話があったような、区内でやりたいという声がもしあるようでしたら。","voiceIndex":110,"id":"exchange-049","title":"町会・自治会支援"},{"speaker":"吉田委員","kind":"提案","question":"就労支援については、具体的な固有名詞というのも変な日本語ですけれども、そういうご意見を頂きましたので、「では今後、積極的な提案などがあれば、福祉部に持っていくようにということでお答えしていいですよね」という確認と、それから、いろいろな事業についても、このような一度決まったような政策は、そもそも決める前に丁寧に現場の意見を聞きながら。","respondent":"寺嶋福祉部長、久保田企画経営部長","answer":"その範囲で、区として必要なものについて協議させていただきまして、可能な限り実施していければと考えております。先ほどもご説明しましたとおり、可能な範囲でということになりますけれども、そういった意見を踏まえながら、より効果的な事業を執行していくよう努めていきたいと考えているところです。","voiceIndex":113,"id":"exchange-050"},{"speaker":"吉田委員","kind":"提案","question":"議会に対しても政策提案というふうにまとまってしまう段階で、今、現場ではこのような議論が始まっているのだけれどもというような報告で、議会としての考えはどうですかというのを、しかるべき委員会などに提案されて、そこに議員もかみながら、最終的な決定というふうにつなげていけるといいかなと私は思うのですけれども、その点についても、今もそうやっているとおっしゃるかもしれませんけれども。","respondent":"久保田企画経営部長","answer":"変更があった際には、常任委員会や特別委員会等にも、これまでも報告させていただいて、ご意見を聴取していますので、そういった取組も今までどおり進めていきたいと考えているところです。","voiceIndex":116,"id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"予算案前に、予算案でということは重々承知なのですけれども、この予算案で一個一個、これは賛成、これは反対という議論は難しいので、そういうことでいうと、このたびの有機野菜の導入というのは手順から外れていたのではないかというのが皆さんのご意見だと思います。ぜひ、これからはおっしゃったとおり進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、区長の施政方針と再開発について伺います。これこそが政治の責任とし、旧来型の「自己責任」の社会モデルから転換し、将来の不安を取り除く新しい社会モデルを示すことが求められていると述べています。区長の言う、国の抱える構造的課題とは何か、伺います。今後、自己責任の社会からの転換をどのように進めるのか伺います。","respondent":"久保田企画経営部長","answer":"所得が増えず、貯蓄もできず、将来の見通しが立たない、自助による生存、生活ニーズの充足が困難であるということが、今日の今の日本社会の構造的な課題なのであり。","voiceIndex":120,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"来年度以降も石破首相は、軍事費をＧＤＰ比３％、１８兆円に増額することを否定せず、自民・公明・維新は、命を削る医療費の４兆円削減を進めようとしています。ぜひこの社会変革を進めていただきたいと思います。この自己責任社会を転換していく上で、１つ、大きな懸念があります。いかがでしょうか。これから福祉や教育を充実させるための財源をどう考えているのか、伺います。","respondent":"久保田企画経営部長","answer":"財源についてのお尋ねですが、今般の予算案における、所得制限によらない各種無償化の施策等につきましては、区政の全６６９事業を対象に実施しました事務事業評価により捻出した一般会計予算の１％、２０億円を主な財源としています。","voiceIndex":122,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"共産党は、日本国憲法第２６条の具体化へ、学校給食の無償化は１４年前から求め、学用品等の無償化も求めてきました。大学生への給付型奨学金も、実施を求める請願が区内大学生から２度出され、自民・公明などの反対で不採択でしたが、共産党は１５年前から繰り返し実施を求め、ついに予算案に計上されました。区民要望を取り入れ、施策を前進させてきたことを評価し、さらに拡充していただきたいと思います。","respondent":"米田教育次長、寺嶋福祉部長","answer":"６年生・７年生で実施しております移動教室についてのお尋ねですが、既に宿泊費やバス代等を公費で負担しているものです。今後につきましても、ご利用者の声、それから他自治体の実施状況等も把握しながら、引き続き充実した支援に努めてまいりたいと考えております。","voiceIndex":124,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで濱野前区政は、保健師と社会福祉士が配置されている他の自治体よりしっかりケアができていると説明してきましたが、区内の実態把握や、熱中症予防などの啓発、認知症ケアなどが不十分で、医師会からも、在宅医療のために相談窓口に保健師や社会福祉士は必須だと要望がありました。いかがでしょうか。２３区最低の高齢者・障害者福祉からの改善を求めます。いかがでしょうか。","respondent":"寺嶋福祉部長","answer":"一方、高齢者福祉におきましては、入院中の紙おむつ代助成における所得制限の撤廃や、それから、今お話が出ました地域包括支援センターの在り方検討に取り組むとしたところです。","voiceIndex":127,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々、２３区最低の福祉改善を、ぜひしっかりと進めていっていただきたいと思います。この間の高橋・濱野区政によって、２３区最低の福祉がずっと続けられてきました。武蔵小山の再開発、小山三丁目第一・第二地区に住む世帯数と、要介護認定を受けている人は何人いるのか伺います。ここで生きたいという地域住民が住み続けられるまちづくりを、どう進めていくのか、伺います。","respondent":"鴇田都市整備推進担当部長","answer":"区としましては、介護が必要な方々も含めまして、地域住民の声に耳を傾け、準備組合に対しては丁寧な対応を行うよう、引き続き指導してまいります。","voiceIndex":129,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"介護認定については、人数は答弁がありませんでしたけれども、８０代の方、あるいは介護を受けている方がいらっしゃるというお話もありました。やはり、こうした高齢者を追い出すのが再開発です。今後も住民の声を聞くということですので、それならば、住民を追い出し、開発企業のもうけを生み出す再開発推進をやめるよう、強く要望して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、同和問題についてとジェンダーについて伺います。款別審査でも伺いましたが、私たちはアポを取った上で、同和生活相談室を視察に行きましたが、相談室は見せてもらえず、事務室にすら入れてもらえず立ち話。改めて、同和相談の年間件数、実人数、相談手段別の件数、相談内容、そして新年度予算で同和の新聞・雑誌購読料や研修費など、それぞれの額と、同和に関わる予算の総額を教えてください。","respondent":"柏原区長室長","answer":"これは、同和関連に関するものですけれども、新年度予算に計上した額が３３３万２,０００円余です。それから、同和に関する研修費です。こちらが１５１万円余です。総額で申しますと、６２０万円余が同和に関する予算ということで計上させていただいてあります。","voiceIndex":133,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"総額は、所管を超えて計上されているものも合わせますと、私たちの計算では約１,５４０万円ほどになります。同和差別の実態がどのようにあるのか明らかにされない中、同和だけ相談室を特別に設けることや、意識調査であえて同和について聞くことは、逆に差別を生み出すことになると思いますが、いかがでしょうか。同和相談は一般の人権相談と統合して、特別扱いは見直すべきと考えますが、いかがでしょうか。","respondent":"柏原区長室長","answer":"これらの課題につきましては、それぞれに固有の問題を抱えているところではありますけれども、今年度新設しております人権・ジェンダー平等推進課を中心といたしまして、不断のアップデートを図りながら、より一層。","voiceIndex":135,"id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ見直していただきたいと思います。次に、ジェンダーについて伺います。品川区では昨年、ジェンダー平等推進条例が制定されました。条例制定から間もなく１年。この間、どんなバックラッシュがあったのか。これまでジェンダー平等に取り組む中で、見えてきた課題があればお聞かせください。","respondent":"柏原区長室長","answer":"これからも引き続き、条例の基本理念等について、ＳＮＳ等も使いながら、周知を含め、丁寧にお伝えし続けていきたいといったところと、講座やフォーラムなどの事業といったところも、様々な立場や困難にある方に参加していただける内容となるように。","voiceIndex":137,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"バックラッシュについては、常にジェンダー問題に付きまとってきますので、ジェンダー平等を願う区民と共にはねのけ、前へ進めていただきたいと思います。条例制定に伴って、様々な講座やフォーラムなどを積極的に実施していると思います。私たちも参加してきましたが、大変勉強になります。取り組まれてきた講座や、その中身、参加者からの感想などを幾つか教えてください。","respondent":"柏原区長室長","answer":"今年度、ジェンダー平等推進センターにおいて、全８回の講座を実施して、幅広い内容を取り上げているところです。今年度の主なもので申し上げますと、女性のための防災講座、それからワーク・ライフ・バランス講座、また男性のための生き方講座などを実施してきております。","voiceIndex":139,"id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"様々、講座をやられているわけですけれども、私は昨年の１１月の斉藤章佳さんを講師に迎えた講座に参加させていただきました。この講座の参加人数と中身を具体的に教えてください。","respondent":"柏原区長室長","answer":"斉藤章佳氏をお迎えしての講座の内容です。こちらにつきましては、１１月２２日に、ＤＶ講座というテーマにしまして、斉藤章佳氏を講師にお招きして、「性暴力から身を守るために知っておきたいグルーミング－加害者臨床の知見を通して考える－」といった内容で実施したものです。","voiceIndex":141,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"性加害者には正しい対応が必要で、被害者に対して大変なことをしてしまったとしっかり反省させることが大事です。対応する教員や職員、大人が正しい対応を学ぶことが必要だと思いますが、いかがでしょうか。今後の講座の周知をさらに広げていただきたいと思いますが、いかがでしょうか。","respondent":"柏原区長室長","answer":"対面とオンラインを併用した形での実施しています。来年度も、いろいろな方に様々ご参加いただけるように、内容や周知を様々工夫して実施してまいりたいと考えています。","voiceIndex":143,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"続いて会計年度任用職員について伺います。現在、区の管理職の女性の割合を教えてください。女性が８割を占める会計年度任用職員ですが、１年ごとの公募はやめ、継続雇用を求めたところ、公募によらない任用制度をできるだけ早い段階で導入するとのことでした。歓迎したいと思います。さらに、同一価値労働同一賃金を求めたいと思います。正規職員と同等にするよう求めますが、いかがでしょうか。","respondent":"柏原区長室長","answer":"一方で、現在、年度ごとの任用であることから導入していない経験加算や、公募によらない再度の任用制度などにつきましては、他自治体の状況などを調査・検討するとともに、常勤職員、国、他自治体、民間などとの均衡を踏まえて。","voiceIndex":145,"id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは強く要望しておきたいと思います。次に、昨年、第４回定例会で、私の一般質問で、選択的夫婦別姓の実施を国に求めようとの質問に、区長は「私としては早期に実現すべきものと考えている」との答弁でした。以前の区長会で、杉並区長の呼びかけで、同性婚法制化を求める要請書を、森澤区長を含む９区の区長が連名で国へ提出。リプロダクティブ・ヘルス・ライツについての区の認識を伺います。","respondent":"柏原区長室長","answer":"これにつきましては、女性は妊娠・出産する可能性がありまして、ライフサイクルを通じて、男性とは異なる健康上の問題に直面するといったことがあります。こうした問題の重要性について、男性を含め、広く社会全体の認識を高めるための理念と考えているところです。","voiceIndex":147,"id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"選択的夫婦別姓のところは、ぜひ区長に答えていただきたかったなと思います。品川区はリプロを、選択する権利と捉えているのか、伺いたいと思います。リプロは権利であるとの立場に立ち、望まぬ妊娠で苦しむ女性を生まない対策を、区として取ることが求められていると思いますが、いかがでしょうか。緊急避妊薬があることや入手方法などを、区として発信していただきたいと思いますが、いかがでしょうか。","respondent":"柏原区長室長、阿部健康推進部長","answer":"私からは、リプロダクティブ・ヘルス・ライツの部分についてお答えいたしますが、女性はライフサイクルの中で妊娠・出産などがある場合に、様々な健康上の課題に直面することが考えられるといったことから、誰もが健康で自分らしく。こうした状況を踏まえまして、区のホームページ等による周知につきましては、情報を伝える対象や内容等について慎重な検討が必要であることから、区薬剤師会と情報交換するなど、引き続き調査・研究をしてまいります。","voiceIndex":149,"id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"自分で決められる権利だというところまで言っていただきたいと思います。リプロはジェンダー平等を進める上で大変重要ですので、よろしくお願いしたいと思います。共産党は、ユースクリニックの設置を求め、今年１月からユースヘルスケアしながわほけんしつが本格実施されています。そして、対象年齢の拡大を求めますけれども、いかがでしょうか。","respondent":"佐藤子ども未来部長","answer":"最後に、対象年齢の拡大につきましては、まだ事業が始まって３か月少しというところですので、状況を見ながら、適宜対応していきたいと考えております。","voiceIndex":152,"id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ拡大していただけたらと思います。緊急避妊薬があることなど、情報提供もされているということですので、ぜひ引き続き、対象も拡大して進めていっていただきたいと思います。ピルコンは包括的性教育を各地域で実施していて、若い世代のスタッフや地域や学校に入って性教育の話をしていますけれども、品川区でもぜひピルコンに性教育をしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"米田教育次長","answer":"今後、ユースヘルスケアしながわほけんしつとも連携し、そこで得られた子どもや保護者のニーズや取組結果を踏まえ、教育の展開の仕方について検討してまいります。","voiceIndex":154,"id":"exchange-069"},{"speaker":"藤原委員","kind":"質問・要望","question":"西大井についてお伺いします。これについて、担当部長、どういうふうにお考えか教えてください。次、駅について伺います。どうか止めていただきたいという思いを何回も質問しましたが、教えてください。それについては、いかがでしょうか。ホームドアはいかがでしょうか。補助２０５号線と滝王子通りが交差する三角地の再開発はどうなっているでしょうか。ぜひ延長していただきたいと私は要望してきました。","respondent":"鈴木都市環境部長、溝口防災まちづくり部長、柏原区長室長、川島地域振興部長、鴇田都市整備推進担当部長、辻文化観光スポーツ振興部長","answer":"ＪＲからは、改札に必要な用地がないことからも、改札口の設置は。都市計画課が所管になりますが、今後、都市計画道路の第５次事業化計画といったところも検討されると聞いておりますので。平和の像の移設そのものについては、駅全体の整備等々の中で、きちんと平和の像が見えるような形で周知できるような部分で考えられるように。喫煙所の利用開始日につきましては、３月３１日の午前１０時を予定しております。引き続き、こういった協議会の活動について、まちづくりの検討状況などを確認していくとともに。","voiceIndex":157,"id":"exchange-070"},{"speaker":"藤原委員","kind":"質問","question":"次に介護予防についてお伺いしますが、実は品川区の高齢者の方々というのは、ほとんどが８割方、元気高齢者なのです。ですから、要支援・要介護にならないためにどういうふうにしていくかということが大事だと私は思っています。健康課と高齢者福祉課はどういうふうに共同でやっていくか、教えてください。この３点セット、プラス、シルバー大学と考えていますが、その辺についてはいかがでしょうか。","respondent":"寺嶋福祉部長、川島地域振興部長、辻文化観光スポーツ振興部長","answer":"高齢者クラブ、シルバー人材センターといったところですけれども、元気高齢者の方、またフレイル予防といったことにつきましては。引き続き、高齢者の生きがい増進と、地域社会の活性化に貢献する取組に努めていけるように、支援をしっかり行っていきたいと考えています。今開いているシルバー大学に来ている方は、本当に生き生きして元気な方が多くて、これからも様々な意見を取り入れながら進めていきたいと考えています。","voiceIndex":164,"id":"exchange-071"},{"speaker":"藤原委員","kind":"質問・要望","question":"介護士の処遇改善をお伺いしますが、品川区は２３区でトップクラスの処遇改善をしてくださいました。その辺の分析はどういうふうにしているのか。でも、介護士たちは自転車に乗って、あの雪の中までも訪問介護で訪問してくれて、介護が必要な方に伺ってくれていると思います。こんなことがあっていいわけないではないですか。違いますか。その辺についてもいかがでしょうか。","respondent":"寺嶋福祉部長","answer":"こういったところに着目して、そうではない、いわゆる規定どおりの最初の想定どおりの訪問介護を行っている事業者については、何か特別な支援ができないかという辺りも含めて、区としても何か積極的に考えていきたいと考えております。","voiceIndex":168,"id":"exchange-072"},{"speaker":"藤原委員","kind":"質問","question":"訪問介護だけではない。企画部長、財政調整についてお伺いしますが、今回、５５.１％から５６％になりました。その辺についてもお伺いします。これについてどう考えるか、教えてください。そして、新井副区長、東京都でのキャリアもあるわけですから、これから２人の部長・課長の答弁を聞いて、それをどう思うか。その辺についてお伺いしたい。でも、新井副区長に伺うと、いつも、「そんなことはないよ。","respondent":"久保田企画経営部長、加島財政課長、新井副区長","answer":"これは、将来、設置予定の区の児童相談所の分も含めた規模であることから、この間の都区財政調整協議における１つの到達点として。それに対応する結果として、今回２００億円から３００億円に拡大したものと、特別区では推測しています。お尋ねいただきました都区財政調整制度に関してですけれども、今回、都区合意に至った経過に関しては、区長会側、それから都側が真摯に向き合った。","voiceIndex":170,"id":"exchange-073"},{"speaker":"藤原委員","kind":"意見","question":"最後に私は、こんな社会になったらいいなと思っていたことがあります。そうしたら、ある方の施政方針の中に、その社会が出ていました。「生まれた境遇や環境によって未来が決定されるような社会ではなく、だれもが生きがいを感じ、自分らしく暮らしていける社会を。」と。森澤区長、私は信じています。区長ならこういうふうにしてくれるだろうと。もちろん、議会側も協力して。ご決意をお話しください。","respondent":"森澤区長","answer":"引き続き、「誰もが生きがいを感じ、自分らしく暮らしていける」、みんなが安心して暮らしていける、そういったウェルビーイングな社会を、区議会の皆さんと共につくっていければと考えています。","voiceIndex":174,"id":"exchange-074"},{"speaker":"筒井委員","kind":"質問・要望","question":"給食食材の野菜に有機農産物等を導入すること、いわゆるオーガニック給食について伺います。区民の皆様に広く知っていただくという観点から、改めての確認を含めた質問と要望をします。オーガニック給食にするとおいしくなる、質がよくなるといった因果関係はないということでよろしいのでしょうか。今回の導入の主な理由は、農林水産省の方針などに沿って行ったものということでよろしいのでしょうか。","respondent":"米田教育次長","answer":"有機農産物等の導入についてですが、１０月から予定しているものです。","voiceIndex":177,"id":"exchange-075"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。今、有機農産物ばかりがクローズアップされておりますが、特別栽培農産物も導入されるとのことです。その割合はどの程度なのでしょうか。その割合にした理由と効果も教えてください。","respondent":"米田教育次長","answer":"現在、作付面積等を鑑みますと、有機農産物と特別栽培農産物の割合ですけれども、おおむねの見込みではありますが、有機農産物が約５％から１０％、特別栽培農産物が約９０％から９５％ということで想定しています。","voiceIndex":179,"id":"exchange-076","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"オーガニックにしますと、本日も野菜に虫が混入するのではないかという疑問もありました。野菜がふぞろいになってしまうのではないか。それに伴って調理師・栄養士たちの負担が増えるのではないかなどの懸念が上がっていますけれども、この懸念に対しての区のご見解はいかがでしょうか。","respondent":"米田教育次長","answer":"今後速やかに既存の事業者に丁寧な説明や意見交換を行い、現場の実態や市場の動向に耳を傾けながら、持続可能な発注・供給が図れる方策を推し進めてまいりたいと考えています。","voiceIndex":181,"id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"ふぞろいの件についてもご説明願います。有機農産物等は通常の野菜より価格が高いため、今回から入札での一括購入を検討されているということです。これにより単価をできる限り下げることができること、および、随意契約と比較して透明性の確保ができることは歓迎されるべきものと言えます。給食で使用するだけの量を一括購入できるのでしょうか。今までの随意契約で何か問題点や課題などあったのでしょうか。","respondent":"米田教育次長","answer":"いわゆる形状等についても、これは市場の関係者の方から意見などをお聞きしつつ、私どものほうで実際受け入れたり、それを調理するに当たって一定程度、現場の負担の軽減につながる手法や納入条件の設定などというものを検討してまいりたいと考えています。","voiceIndex":183,"id":"exchange-078"},{"speaker":"筒井委員","kind":"質問","question":"供給については一括購入しても大丈夫ということなのでしょうか。そして、肝心の税増額の件ですが、今回の有機農産物等の購入費用約２,８００万円を、今後、毎年寄附してくださる方が現れたということです。今回は購入費用額が一旦、予算計上されてしまうこととなり、後で寄附分をもって相殺するということになるのでしょうか。この点、持続可能性について区のご見解を教えてください。","respondent":"米田教育次長","answer":"こちらについて現時点で、継続してというお申出を受けているところではありますが、そちらについては、本事業の実施状況を見ながら寄附者がご判断されることもあろうかと今考えているところです。","voiceIndex":185,"id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"区民負担はないような方法で、ぜひよろしくお願いします。したがって、対外的にここまでのご答弁内容をホームページや記者会見などで発表すべきと思いますが、いかがでしょうか。他の事業と同様に、事務事業評価による効果検証を行っていくのでしょうか。今後重大な問題が発生した場合などは、当然、見直しを行っていかれるのでしょうか。お知らせください。","respondent":"米田教育次長","answer":"本事業につきましては、導入予定の１０月に向けて検討を進めてまいりますので、その間、説明も丁寧に進めてまいりたいと考えているところです。","voiceIndex":187,"id":"exchange-080"},{"speaker":"筒井委員","kind":"提案","question":"分かりました。続いて、羽田アクセス線新駅可能性地域まちづくり検討について伺います。経済効果や地域活性化に資するかどうかの点は考慮されていますでしょうか。続けていきます。そこで、現状の都立潮風公園のまま、東京都と積極的に連携しての利活用や、この際、協議の上、潮風公園を都から品川区に移管し、Ｐａｒｋ－ＰＦＩを導入しての民間活力も使った東八潮の利活用を提案しますが、いかがでしょうか。","respondent":"鈴木都市環境部長","answer":"区としましては、東京都によりプランに基づく公園改修、再整備計画検討などが進められる際には、区民利用のさらなる利用促進につながるよう、水辺をより身近に感じられるような施設の整備、民間活力やノウハウの導入などについて、今後、時期を捉え。","voiceIndex":189,"id":"exchange-081","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問・要望","question":"力強いご答弁をありがとうあります。最後に羽田新ルートについて伺います。したがって、Ａ滑走路・Ｃ滑走路の使用を前提としない固定化回避の検討をするべきであり、区としてもそのような旨を国に求めるべきですが、いかがお考えでしょうか。例えば、無理をして羽田空港にこだわらず、羽田新ルート導入当時より機能強化が進みつつある成田空港や茨城空港の活用を提言すべきですが、いかがでしょうか。","respondent":"鈴木都市環境部長","answer":"今回ご質問いただいた内容も含め、区民の方からは、さきに行いました全区民アンケートなどにより様々な意見を頂いているところです。区としましては、こうした声を国に直接しっかりと届けるとともに、区民への丁寧な説明を、引き続き国に対し求めてまいります。","voiceIndex":191,"id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"本当に区民負担がこのままでは、Ａ滑走路・Ｃ滑走路の使用を前提とするならば、検討会を何回やっても同じ結論、堂々巡りになりますので、区としては、もうこの状況ならば、Ａ滑走路・Ｃ滑走路の使用を前提としない固定化回避検討会を立ち上げるべきと強く求めるべきだと思いますけれども、その点、いかがお考えでしょうか。","respondent":"鈴木都市環境部長","answer":"区としましては、今後もこの固定化回避検討会において、区民負担軽減につながる具体的な取組の内容の提示と早期の実施を行うよう、国に対し引き続き強く求めてまいります。","voiceIndex":193,"id":"exchange-083"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。区の申入れ書等々の行動は高く評価するものですけれども、このままですと同じような結論になってしまうと思いますので、そろそろ新たな動き、次のアクションが必要なのかなと思いますので、その点も含めてぜひよろしくお願い申し上げます。質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-084"},{"speaker":"せらく委員","kind":"提案","question":"品川区議会日本維新の会を代表して総括質疑を行います。初めに、官民共創について伺います。そこで、官民共創のさらなる発展のために、現在の状況や課題、今後の方針について、具体的にお伺いしたいと思います。民間企業や団体が参加しやすい環境を整えるための工夫を伺います。現在の応募状況、選定方法について、課題解決型事業、実証実験提案型への応募件数について教えてください。以上、お伺いします。","respondent":"久保田企画経営部長","answer":"課題解決型では、各部署から課題を募り、現在６つの課題を発信し、提案を募集しております。官民連携で課題解決を進める機運を醸成するため、職員向けのワークショップも併せて実施しています。","voiceIndex":198,"id":"exchange-085"},{"speaker":"せらく委員","kind":"質問","question":"実証実験型事業の第１号として採択されたマチルダについてお伺いします。利用者の６６.３％は子どもがいる家庭だったという結果も報告されています。勤務時間プラス通勤時間の預かりという保育園からの説明もよく分かりますが、３０分もお迎えが遅れるものではないと思い、家族の時間を持つための夕飯の買物に対しての制限は変えていくときではないかと考えますが、子ども未来部の見解を伺います。","respondent":"久保田企画経営部長、佐藤子ども未来部長","answer":"実証実験を行うに当たりましては、様々な利用者がいることを想定した上での実証実験であり、利用される方には、それぞれのご事情があることは認識しております。一方、区では、産休・育休中の在園資格の拡大を図るなど、区としてできる対応を進めているところで、保育園の運営については、社会の変化に応じて柔軟に見直していく必要があると考えております。","voiceIndex":200,"id":"exchange-086"},{"speaker":"せらく委員","kind":"確認","question":"それぞれご答弁ありがとうあります。保育園の部分はやはり法令があるということで、なかなか区独自で対応するのは、ニーズに応えていくのは難しいとは思いますが、区としては、法令が変われば、こういったニーズに応えていけるという認識でしょうか。確認させてください。確認させてください。","respondent":"佐藤子ども未来部長、久保田企画経営部長","answer":"子育て世帯の負担軽減は、区の重要課題の一つと認識しております。区としては、法令の枠内でできる限りの対応を行いつつ、同時に国や法令等の動向を注視し、改正等があった場合は迅速な対応ができるように努めてまいります。あくまでも実証実験として行っていますので、保育園の送迎等についても、現行の枠組みの中で利用していただきたいと考えております。","voiceIndex":203,"id":"exchange-087"},{"speaker":"せらく委員","kind":"質問・要望","question":"確認させていただきました。要望や意見交換の機会に、ぜひ話題にしていただきたいと思います。次の質問に移ります。周産期グリーフケアについて質問いたします。この話題については、以前からも議会でも議論があったことを会議録からも確認しております。区では職員に対し、具体的な周産期グリーフ支援についての研修を行ったことがあるということを確認いたしました。区としての見解を伺います。","respondent":"阿部健康推進部長","answer":"そのため、個別の情報共有の仕組みをつくることは困難です。医療機関におけるグリーフカード配布等の取組につきましては、一部自治体で新たに始めるという情報もあり、その自治体の実施状況の把握に努めてまいります。","voiceIndex":206,"id":"exchange-088"},{"speaker":"せらく委員","kind":"質問・要望","question":"ご答弁ありがとうあります。当事者が必要としたときに、支援や相談先の情報提供はしっかりお願いしたいと思います。産後ケアについて、区では母子の産後ケアとして事業を展開していますが、流産や死産を経験した方も、心のケアを含めた産後ケアが必要ではないでしょうか。お考えを伺います。こういったケースは、おくやみコーナーへの案内ができると思いますが、こちらも確認させていただきたいと思います。","respondent":"阿部健康推進部長、川島地域振興部長","answer":"私からは、まずは産後ケアについてお答えいたします。産後ケア事業につきましては、お子さんを亡くされた方への対応についてもできる限り考慮するようにと、厚生労働省のガイドラインにも記載があります。今ご例示いただきましたような対応がないように、窓口の取扱い等もしっかり注意して行っていくというのは当然ではありますが、例えば現状でも死亡届を受け付けた際には、ご遺族のつらい気持ちに寄り添いながら。","voiceIndex":208,"id":"exchange-089"},{"speaker":"せらく委員","kind":"確認","question":"次の質問に移ります。次は、学校についてお伺いいたします。給食や校務ＤＸなどについて質問します。頂いた栄養表を確認すると、小学校高学年の１食当たりのある月の平均栄養価は、エネルギー６２０キロカロリー、カルシウム３２２ミリグラム、鉄２.３ミリグラム。そこで、品川区の小学校に通う子どもたちの成長の傾向についてお伺いしたいと思います。給食の残量についても実態を教えてください。","respondent":"米田教育次長","answer":"学校給食についてのお尋ねです。初めに、委員ご指摘の給食の栄養についてですが、献立によっては国の摂取基準を下回る日もありますが、月単位で見ますと必要な栄養を摂取できていると認識しています。","voiceIndex":211,"id":"exchange-090"},{"speaker":"せらく委員","kind":"質問・要望","question":"残菜率についてなのですけれども、前年と同様ということですが、その残菜率の求め方をもし教えていただければと思います。給食の試食に伺った際に、栄養士の方から、物価高騰により予算内でのやりくりが大変とのお話を伺いました。私は部分的に一括調達することで、価格の圧縮と独自性を担保することができると考えますが、お考えを伺います。お考えを伺います。","respondent":"米田教育次長","answer":"今年４月からも増額を予定しております。過去の例では、令和４年９月に物価高騰による増額をした際は、補正予算により対応しております。この時期はまだ私費会計でしたので、公費により増額分を対応したという事例です。","voiceIndex":213,"id":"exchange-091"},{"speaker":"せらく委員","kind":"質問・要望","question":"できる部分から推進していく方向であることを確認しました。間もなくＤＸ推進基本方針の改定が予定されていますので、学校の手続や公務、テレワーク環境の整備などの働き方について、計画に反映して推進していただきたいと思いますが、いかがでしょうか。今後の具体的な推進内容についても併せて伺いたいと思います。集金業務についてのキャッシュレス化などをどのように進めているか、現状をお聞きします。","respondent":"米田教育次長","answer":"デジタル化を進めるに当たりまして、システムの導入が必要な場合も考えられますが、現在、令和９年１月予定の国のシステム標準化に伴い、システム変更を検討しております、学校事務システムや校務システムの中で、ＤＸ化の推進も併せて検討を行ってまいります。","voiceIndex":215,"id":"exchange-092"},{"speaker":"せらく委員","kind":"質問・要望","question":"ＤＸの推進は、ぜひ計画にも反映していただきたいと思います。次に、以前、会派の松本委員の質問で、中学生にはヘルメットを公費で支給していて、一方で小学校は防災頭巾を保護者が購入していることを指摘していました。会議録を見ていると、「学用品の無償化」と、あと「補助教材の無償化」という２つの言葉が使われているようですが、こちらの違いについてもお聞きしたいと思います。","respondent":"米田教育次長","answer":"学用品と補助教材の違いについてですが、学用品は児童・生徒が学習や学校生活などに使用するものの総称で、例としては、文房具、衣類、かばん等と認識しております。補助教材は、本区では学習において教科書と併せて使用する教材としております。","voiceIndex":217,"id":"exchange-093"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。学用品と補助教材の違いをご説明いただきまして、ありがとうあります。款別審査でも、教職員の負担軽減をはじめとしたＤＸについて質問してまいりました。教職員がしっかり子どもたちのための教育ができる環境整備をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-094","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"質問・要望","question":"総務費では、新庁舎建設は、住民参加と情報公開の下、庁舎跡敷地も含めて検討し直すべきであり、進めるべきではありません。住民要望の強いコミュニティバスの大崎ルートの運行とともに、区営住宅に申し込み、落選した世帯に、月１万円の家賃助成を行います。修正案に盛り込んだ事業は４９事業で、予算の使い方を、暮らし・福祉優先に切り替えれば、さらに多くの区民要望を実現することができます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-095"},{"speaker":"田中委員","kind":"提案","question":"なので、減額修正に関しては、区長への強制権はあると思うのですが、実行する権限はあると思いますが、増額修正の場合は、区長に執行権があるということは、ご提案いただいたことを実際に実行に移す観点では、さらなる取組が、区長の理解も含め、区長の側の対応が求められるのですけれども、そこへの対応はどう考えていらっしゃるのかということと、あと予算編成権の件でいうと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":224,"id":"exchange-096"},{"speaker":"安藤委員","kind":"質問","question":"ご質問ありがとうあります。予算編成権の区長部局との関係との質問だと思うのですけれども、その前に開発の経費ですが、今回削ったところは、区の単費のところの再開発検討経費の部分なのです。例えば、もう既に建築されているものや、あるいは事業認可されて事業化されているものなどを止めるというのはかなり難しいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-097"},{"speaker":"田中委員","kind":"質問","question":"すみません。それはそれで、日本はいわゆる民主国家ですので、反対意見もしっかり通していただいた中で、最終的には議論した上で議決することになると思うのですけれども、一方で、そのときに反対の方の意見は伺えるのですけれども、逆に地権者の方や、まちづくりを進めていきたいという方の意見はどのように捉えていらっしゃるのか。そこをあえて今回はお伺いしたいと思い、発言させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-098"},{"speaker":"安藤委員","kind":"意見","question":"地権者の方にはたくさんいろいろな方もいらっしゃる。最近、特にそれが増えているので、私たちはそういった、周辺住民の方も含めてだと思うのですけれども、やはりまちづくりというのは、区長もおっしゃいましたけれども、そこに住む住民の方々が主体になっていくということが重要なので、今、実態として、今進んでいる再開発というのはそういうふうになっていないという認識です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":227,"id":"exchange-099"},{"speaker":"田中委員","kind":"意見","question":"もうここで、議論が尽きないので、まとめます。地権者の方の中の賛成者の声をどう酌み取るかという部分で、再開発は決してよくないことではなくて、防災性も向上するし、機能強化にもつながるしという意味で、私はまちづくりはあるべきだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":228,"id":"exchange-100"},{"speaker":"まつざわ委員","kind":"提案","question":"民間喫煙所の助成拡大、町会・自治会支援、産前・産後支援、産後ケアの拡充、子どもの食の支援、第１子保険料の無償化、私立幼稚園保護者補助金の拡充、介護職員等住まいの支援、外国人介護人材の就労・就学支援、７３歯科健診の実施、障害児の通学支援、マンション防災、自転車空間の本格整備、中学生標準服の無償化など、会派からの要望が多数予算化されました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-101","title":"町会・自治会支援"},{"speaker":"若林委員","kind":"提案","question":"さて、公明党は以上のような議論を行いつつ、この１年、区民生活の具体的な施策拡充へ、多くの提案・要望を重ねてまいりましたが、予算案には、所得制限のない中学校の標準服・修学旅行費・終活支援サービスの無償化等が計上されたほか、朝の児童の居場所確保・朝食支援、子ども・若者の区政参加や高齢者等住まいへの支援、補聴器購入費助成拡充、また児童発達支援センター、障害者・生活介護延長などや。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-102"},{"speaker":"大倉委員","kind":"提案","question":"今後も、ＡＩやＩｏＴなどの最先端技術の活用や、利便性・効率性の向上につながるデジタル化のさらなる推進、デジタルデバイド対策、産前・産後子育て支援の充実、学校教育の充実、障害者福祉・高齢者福祉の充実、地域経済活性化施策の推進、防災対策の強化、環境対策の推進、庁舎建て替え、羽田新ルートの問題、多様性の推進、職員人材育成強化、デジタル地域通貨やポイントサービスの推進など。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":235,"id":"exchange-103"},{"speaker":"安藤委員","kind":"提案","question":"住民追い出しの再開発など、批判すべきもの、転換や修正が求められるものについては、今後もこれまでどおり厳しく批判し、正していくことには変わりありません。地域包括支援センターの検討経費は、共産党が、福祉予算の抑制のために２３区で品川区だけが地域に包括センターをつくってこなかったと告発し、現場の声を届け、議会で求め続けてきました。住民に寄り添い、踏み込んだ対応を強く求めます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":237,"id":"exchange-104"},{"speaker":"須貝委員","kind":"質問・要望","question":"令和７年度予算に対する品川改革連合の意見表明を致します。令和７年度の一般会計、国民健康保険事業会計、後期高齢者医療・介護保険・災害復旧の特別会計の各予算に賛成いたします。買い控えや節約で消費が減少、中小企業は値上げできず、人手不足と資金難で廃業や倒産が増えているので、区は公平な支援をしていただきたい。以上で、品川改革連合の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-105"},{"speaker":"松本委員","kind":"質問・要望","question":"私も、森澤区長が出演された、２月１３日の「ＡＢＥＭＡ Ｐｒｉｍｅ」を拝見いたしました。行政運営においては、高齢者世代、現役世代のみならず、投票権のない、あるいはまだ生まれていない将来世代のことも熟慮するよう求めます。区におかれましては、これらについて検討され、予算の執行や今後の施策に反映していただくよう要望し、品川区議会日本維新の会の意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7015#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":125668,"voices":250}},{"id":"r07-20250325-10","meetingId":"r07-cm03","date":"2025年3月25日","dateIso":"2025-03-25","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"せっかくなので、セムカンのお話があったのですが、４月からの試行というのは、確かに少し早過ぎるのではないかと思いますので、そこの点については同感ですけれども、私たちも何人かで講習を受けたのですが、領収書の全面公開とか、ネット公開という点では、実際にやろうとすると、物すごく事務手続が大変で、なかなか現実的ではない面もあったのですが、あちらのツールですと、そういったことが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-001"}]},{"id":"topic-02","title":"傍聴規則の改正","agenda":"傍聴規則の改正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"少しお伺いしたいのですが、全国市議会議長会の標準市議会傍聴規則の例にならってということだと思うのですが、そちらにはあって、そちらの例以外で、品川区議会独自に追加した項目はあるのか。もしあるとしたら、この案についてどこら辺なのかということを伺いたい。それが１つ。それと、「じい的」と読むのですか、「しい的」というのですか。","respondent":"大澤区議会事務局長","answer":"どちらでもいいそうです。","voiceIndex":37,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"第６条のところです。第６条のところで、続いて、「他人に迷惑を及ぼすことを疑うに足りる顕著な事情が認められる者」というのは、あまりにも抽象的で、こちらは違う意味での恣意的な運用がされてしまうおそれがあるので、あえてこれを入れなくてもいいのではないかと思うのですけれども、そこら辺についての考えはいかがでしょうか。","respondent":"大澤区議会事務局長","answer":"最後の部分ですけれども、そこはもともと改正前から入っていた部分なので、あえて消すという必要もないのではないかなというふうには認識しています。","voiceIndex":39,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"最後のところですけれども、入っていないと思うのですけれども、どうでしょうか。あえて入れなくてもいいと思うのですけれども、どこに入っていましたか。私、見当たらないのです、改正前。","respondent":"大澤区議会事務局長","answer":"改正前の(7)の「議事を妨害することを疑うに足りる顕著な事情が認められる」ということを「他人に迷惑を及ぼす」という表現に変えていて、意味的には同様かなと思っていますけれども。","voiceIndex":41,"id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"そうですね、議事を妨害するというものと、新しいところの会議を妨害するというのが同じだと思うのですけれども、その後に「または」ということになっているので、あえて「他人に迷惑を及ぼすこと」という抽象的な表現が入っていると私は理解しておりますので、次回でやりますけれども、あえてこちらに入れる必要があるのかなと、今、考えているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-005"}]},{"id":"topic-03","title":"申し合わせ確認事項の改正","agenda":"申し合わせ確認事項の改正","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"予算・決算特別委員会の開会時間を９時半に早めるというところを試行して、それぞれ１回ずつやったというところで、当初の話は試行ということだったのですけれども、２回やってみて、私としては、悪くないのではないかと思うのですけれども、正式にこちらに書き込むということなので、ご提案された議長も、客観的に見て、２回経て、どうだったのかというか、そこら辺のご評価をお伺いした上で。","respondent":"渡辺議長","answer":"というのは、全部の情報を把握できているわけではないですが、まず議会内、あるいは、区の職員、この辺り、当事者間で聞いている話で主なものを挙げると、まず、議会側では、やはり連日続く予算・決算特別委員会なので、終了後に理事者との打ち合わせ。","voiceIndex":49,"id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6979#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":11455,"voices":57}},{"id":"r07-20250326-5","meetingId":"r07-cm03","date":"2025年3月26日","dateIso":"2025-03-26","committee":"総務委員会","time":"午前１１時３０分～午後 ０時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"取り上げる順番を入れ替えまして、(2)第６３号議案、八潮南特別養護老人ホーム増築その他工事請負契約の変更","agenda":"取り上げる順番を入れ替えまして、(2)第６３号議案、八潮南特別養護老人ホーム増築その他工事請負契約の変更","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"地中障害物が出たということだと思うのですけれども、この障害物は、大体どのようなものなのかということと、汚染土というところで、汚染の調査をするのか、もう汚染されているということが分かったのか伺いたいと思います。","respondent":"長尾施設整備課長","answer":"地中障害物の内容ですけれども、主にコンクリートがらになります。大きさが、大きいものですと２ｍを超えるようなコンクリートがらなども出てきている状況です。汚染土につきましては、今回の工事に着手する前に事前調査はしておりました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。コンクリートがらが主だということは、ずっと埋まっていた、今回、増築することで掘ったら出てきたということなので、要は、学校の校庭になる前のものが出てきたということですね。以前は、どのようなものが出たりということと、それだけ埋まっているということが、建築上、正当なのかというか、それだけ埋めてしまっているというのは、正しいのかというか、そこら辺を教えてください。","respondent":"長尾施設整備課長","answer":"この場所自体が、八潮団地が建つ前、昭和４０年頃に埋立てをした場所になっております。埋立てをして、実際の建物は昭和５６年頃から昭和５８年頃にかけて建てられたようです。その後、昭和５８年にまち開きというか、入居がスタートしたというような経緯になっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"汚染なのですけれども、どういう類いの汚染なのですか。その後処理に、除染をすればいいのかどうかみたいなことも教えてください。これ、すごく大きいなと思うのですけれども、これはやはりこのぐらいかかるものなのか、２ｍのコンクリートがらが出てくると、そのぐらいかかってしまうのかなと思うのですけれども、これはそういう状況だと、このぐらいかかるという認識でよろしいのか、どうでしょうか。","respondent":"長尾施設整備課長","answer":"汚染が確認された土については、もともとは一部と見込んでいたのですが、それを処分する量が、全部汚染土として適切に処分することが必要になってきますので、そういうところを適切に行った結果、この金額になってしまうということです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"大変大がかりな土壌汚染を排除する、直さなければいけないということで、このように大がかりな工事になるとは思わなかったのですが、前に大崎の東急の、ちょうど電車が通っている付近で、やはり地中埋設物があって、そのときは、年代がどうだか分からないのですが、埋設物があったときに、瑕疵担保責任といって、そのとき施工した業者が、その分は業者負担になったという話をそのときに聞いたのですが、今回。","respondent":"長尾施設整備課長","answer":"今、委員からお話があったような民地の売買された土地に対しての地中障害物ということですと、一般的には、契約の中で、特約で地中障害物の取扱いについて決められていれば、それに従ってということになると思うのですけれども、今回の場所についてで言いますと、当時。","voiceIndex":13,"id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"瑕疵担保責任というのは、遡ってできるように法律は改正されたと思うのですが、これだけの大がかりな工事になると、区でこれだけの金額を出してもやらなければいけないというのは、何か少し残念だというか、口惜しいというか、区民の方もなかなか納得がいかないと思うので、何かあるのかなと思ったのですが、そういうこともご検討されたということだと思いますので、これで話を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-005"},{"speaker":"大倉委員","kind":"質問","question":"今いろいろお話を聞かせていただいて、おおよそ分かったのですが、この８億６,０００万円余の内訳はどのようになっているのか教えてください。","respondent":"長尾施設整備課長","answer":"３つ目として、もともと汚染がない土だと見込んでいたものを、汚染がある土として適切に処分するというところで、こちらが２億４,０００万円程度。最後は、工期が延びますので、その分の経費などもかかってまいります。そこの部分で７００万円程度というところになります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"説明で分かりました。１つだけ、工期が延びるのですね。工期が延びると、代表質問でも言ったのですけれども、結局、その会社は、例えば３か月と仕事を決めているわけですね。でも、こういうイレギュラーが起こると、結局、３か月延びるということは、その会社はさらに３か月やらなければいけない。でも、仕事はそこだけではないから、結局その次の仕事も見つけてくるわけですよね。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"責任の所在が、そもそも昭和３１年頃から始まって、昭和４０年頃に埋立てられたということで、事業者に求められないとしても、東京都が関わっているという部分では、東京都への費用負担を求めることができないのかというところを確認させていただきたいのと、もう１つ、工期が延びるということで、一応、年度末の３月３１日までという日程が出されていますが、ということは。","respondent":"長尾施設整備課長","answer":"資料では、延長７９日と書いておりますが、土日等も含めて、４か月、工期を延ばしている状態ですので、もともと予定していた開設時期からは４か月ほど延びるというような見込みになっております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"新妻副委員長","kind":"質問","question":"分かりました。今、区内で工事をしている中で、こういうことが起こり得るところはあるのでしょうか。物価高騰でのインフレスライドでの上乗せはあったにせよ、今回、インフレスライドではない上乗せでしたので、今、品川区が抱えている工事の中で、こういうことが起こり得るところは、調査といいますか、何かそういうものはどうでしょうか。","respondent":"長尾施設整備課長","answer":"ただ、今回の八潮の埋立地の中でこういうことがあったということを踏まえて、今後の事前調査の仕方であるとか、仮に想定外のことが出てきた場合に、どう迅速に対応するかといったところの工夫は検討しておきたいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"やっていると思うのですが、そこはやっていなかったのでしょうか。それともう１点、それぞれコンクリートならば、土留めをするにしても何にしても、それぞれ砕けばいいわけですよね。一般的にコンクリートでも何でもやるのは。同時に重機で砕いて、そのまま搬出するだけなら、そんなに大がかりな工事にもならないのかなと、今、気がついたのですが、その２点だけ教えてください。","respondent":"長尾施設整備課長","answer":"それを想定した上で工事の準備をしていたのですけれども、少し想定を上回る物が地下の深いところに、事前の土壌汚染の調査では５０cmまで、ボーリング調査という土を掘ってやる調査については、敷地の中で５か所程度、一般的にその程度で十分なので。","voiceIndex":23,"id":"exchange-010"}]},{"id":"topic-02","title":"第６２号議案、品川区特別区税条例の一部を改正する条例","agenda":"第６２号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"マイナンバーカードと運転免許証の一体化ということで、マイナ免許証、これはマイナ保険証と違って強制ではないといいますか、選択できるというところだと思うのですけれども、品川区内で免許証を持たれている方、そして、そのうちどれぐらいの方が、今、一体化されているのかということは、区では把握はできないものでしょうか。教えてください。","respondent":"吉野税務課長","answer":"今まさに始まったばかりですので、その数につきましては、まだ把握できておりません。","voiceIndex":37,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"確認","question":"始まったばかりですけれども、確認できるようになったら、区では把握できるようになるのでしょうか。","respondent":"吉野税務課長","answer":"例えば、税務課のほうで、こういった種別割の申請に来られた場合には、その件数は把握できるかと思うのですけれども、全体の数となりますと、そこは把握できません。","voiceIndex":39,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"私は運転免許がないので、便利になるのかどうか分からないのですけれども、このマイナ免許証をなくした場合に、申請を両方やらなければいけないとか、結構複雑だと聞いたのですけれども、それと、メリットがまだ不明瞭なところがあって、これからどんどん変わっていくのではないかという見方もあるのですけれども、これはやはりそういう形で変わっていく可能性もあるのですか。","respondent":"横田デジタル推進課長","answer":"急ぎの場合で、すぐ運転したいという場合は、運転免許証を再発行してもらうという手続になろうかと思います。今後、その辺りが改善されていくかというところは、今、警察のほうで検討しているところになります。","voiceIndex":42,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"メリットもいろいろあるという話なのですけれども、これは区として、宣伝ではないですけれども、こういうメリットがありますよみたいなことをやるのですか。区としては、国が決めたことだからと、あまり手を出さないのか、推進をしていくのか、どのような感じですか。","respondent":"横田デジタル推進課長","answer":"区としましては、中立的な立場にありまして、ただ、こういうことが始まりましたということは、先日、区のＸで投稿しています。","voiceIndex":44,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"これはこういうふうに変わっていくので、利用できる人はしてもらって、しない人はしないでいいのですけれども、窓口でお願いがあるのですが、１０月頃になると問題はないそうですが、例えば、今、免許証を更新して、仮に１０月前後ですか、その頃にマイナンバーカードの期限が来て有効期限が切れた場合に、一体化した場合、もう１回一体化の手続をしなければいけないという、そういうことがあって、結局。","respondent":"吉野税務課長","answer":"私どものほうに例えば申請に来られた場合などは、やはりその期限のところはきちんとご本人様にはお伝えしたいと思います。関係の課とも、その辺のところは詰めていきたいと思っています。","voiceIndex":46,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"意見","question":"マイナンバーカードと運転免許証の一体化そのものは、マイナンバーを推進するものであるので反対なのですが、今回の改正内容を見ますと、障害者が軽自動車税の減免を受ける際に不利益にならないようにということなので、それは必要だと思いますので、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6983#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":11142,"voices":58}},{"id":"r07-20250326-10","meetingId":"r07-cm03","date":"2025年3月26日","dateIso":"2025-03-26","committee":"議会運営委員会","time":"午後 １時５０分～午後 １時５０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6981#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":764,"voices":8}},{"id":"r07-20250414-10","meetingId":"r07-cm04","date":"2025年4月14日","dateIso":"2025-04-14","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"それに伴って、(2)で委員会合意ができる調査事項については、具体的な政策提言、政策要望としてまとめて、例えば、年度内に中間と最終など、タイミングを計って議会から区長へ提出機会を設けるといったことも考えていきたいと思っています。４番目は公共交通です。最後に、定員が書いてありますが、設置数は２から４ぐらいで、定員は８から１３ぐらいということでお示しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-001"},{"speaker":"こんの委員","kind":"提案","question":"２点目が、地域共生社会対策特別委員会ということで、こちらは、今年度から重層的支援体制が本格実施いたしますので、これについては、年代層限らず、様々なご相談事の重層的なところに対応していく課題は、それこそ、これも横断的な所管になりますので、この観点をというところで、ここに書かせていただいております、重層的支援体制を、いま一度、地域福祉計画の中から確認させていただきながら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"},{"speaker":"山本委員","kind":"意見","question":"私たち、しながわ未来からは、行財政改革・ＳＤＧｓ推進と災害・環境対策の２つの調査事項の委員会を挙げております。１つ目の行財政改革・ＳＤＧｓ推進については、１０項目を候補に挙げております。１つ目が、新庁舎・庁舎跡地等・公有地に関することです。最後、３つ目が清掃・リサイクルに関することで、具体的にはリサイクル製品、製品プラスチック回収、周知・啓発方法等になります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"品川改革連合の意見を申し上げます。現在、特別委員会は２つあり、１つは行財政改革特別委員会で、その調査事項は新庁舎等に関すること、および行政のデジタル化に関することの２件としています。したがって、次年度もわざわざ特別委員会を設置する必要がないと思われますので、品川改革連合としては、特別委員会を設置することに反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"提案していただいた皆様の案を見させていただいたのですが、共産党としては、例えば、自民党や公明党の公共交通や、公明党の若者政策、都市部の住まい、特にマンションの２つの老いという部分は重要だと思っています。共産党としては、これらのところに共感したということで、意見を述べさせていただきたいと思います。こちらも意見です。１つ質問したいのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-005"},{"speaker":"せお委員","kind":"意見","question":"今、議会改革の会議体が４つあって、もしこの特別委員会が設置されたら、その下にと言ったらおかしいですが、そこから派生して、大まかな方針などを特別委員会で検討して、実質的に運営のところは今の会議体でいいのかなという考えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かるような、分からないようなという感じなのですが、議会改革として、今、議長が主導してやっているということがあるのと、議会改革推進会議のリーダーはまつざわ委員長だと思っているのですけれども、その整理というか、そこら辺をどのように考えているのかということがもしあれば、聞かせていただきたいなと思うのです。","respondent":"渡辺議長","answer":"そうすると、１つの案としたら、特別委員会は定期的に時間が確保できるだろう。そのような点で挙げたと解釈しています。そのような議論があって今に至っている。ただ、今後は、やはり交通整理と優先順位だと思うのです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今回、これだけの項目を出されたのですが、最後にこれを決める人も大変だと思うのです。すごいボリュームで、淡々と皆様が意見を述べたのは分かるのですけれども、１年間でできるのですか。これだったら、毎週のごとく議論しないと、到底できないような項目を皆様は書かれているのですが、選ぶ人も大変だと思うのですけれども、大丈夫ですかという意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"こんの委員","kind":"意見","question":"それぞれこういう視点を持って事業を展開していくという、いわゆる指針というか、この１７項目のＳＤＧｓそのものが事業となるものもあれば、そういう視点を持って区の事業をしていきましょうという、１つの指標、目標、視点なので、そうした観点から見ると、先ほども申し上げたように、全ての事業をこういう視点で展開していくという考え方が大事でありますので、当然ながら、たくさん挙げましたけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"塚本委員","kind":"意見","question":"それに当たっては、各会派から出ている案の重なるところ、共通とするところ、例えば、うちのほうから言わせてもらえばＳＤＧｓはしながわ未来からも出ているし、あと、ＡＩオンデマンド、地域交通は自民党からも出ておりますので、そういったところは１つにまとめていけるのかな。１つの特別委員会というまとめをしていくと、３つ、４つになっていくのではないかと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-010"},{"speaker":"せお委員","kind":"意見","question":"私たちも、たくさん挙げていただいた中から絞っていけばいいのかなと考えています。公明党やしながわ未来が書いている、うちの視点にはなかったところですとＳＤＧｓ。公有地にも関わってくるのですけれども、公明党が書いていらっしゃいます、大井町駅周辺まちづくりといったところも、ぜひ特別委員会で検討できたらなということは考えておりますので、そういった形で皆様で集約できたらなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-011"},{"speaker":"こしば委員","kind":"提案","question":"せお委員から我が会派の説明をさせていただきまして、その他の会派の方のお話、説明を伺いました。大変共感、賛成するところがありました。八潮の地域は高齢化率が３割を超えると聞いております。大変子育て世代の多いエリアですので、そういった人口の年代の構成のパーセンテージが変わるところで、一体化した人的な交流も踏まえたまちづくりも、ぜひ調査・研究をしていきたいということでご提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"しばしば広町などの調査となると、自分たちの持ち物ですから、ある程度そうかもしれないのですけれども、あくまで大井町の周辺としてしまうと、公有地ではないところもたくさん含まれているわけで、まちづくりというのは、区長も言っていますけれども、そこに住む住民の方々がまちづくりの主役なのだということをおっしゃっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"意見","question":"私も大井町のまちづくりの部分では、再開発につながるような検討はすべきではないと思います。まちづくりとしては、今、安藤委員が言ったとおりですけれども、やはりその周辺には、もう既に計画があって、大変不安に思われている方もたくさんいますので、再開発につながるような議論はすべきではないと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ。先ほどこんの委員からＳＤＧｓについてお話を聞きましたけれども、ＳＤＧｓは足かせがあるではないですか。誰一人取り残さないという施策をやって、そうすると、実際、高齢者介護、医療、様々な子どもたちのひきこもりをはじめ、いじめもあります。やらなければいけないのでしょうという足かせが議会にかまされてしまうのではないかという気もするので、それだけ注意していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"こういった大型施設の中で、防災といった観点の話も併せてできるかと思いますので、そのようなところも合わせてグルーピングしていただくというのも１つあるのではないかです。それから、若者政策や地域共生社会のところも、公明党をはじめ、自民党からの要望もうまくまとめることができるとすれば、それもいいのではないかと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"せお委員","kind":"意見","question":"うちの会派からの案にも２から４と書きましたが、今の議論を踏まえて、本当に充実してきているということから、やはり２から増やして、あと、実務的なところも考えて、３程度かなというのが、設置数としては考えられるなと思っています。例えば、委員の数ですと、現在１３名ずつだと思うのですけれども、１３名だと少し多い。そういった考え方もありなのかなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-017"},{"speaker":"山本委員","kind":"意見","question":"当初、２つとご提示していますけれども、これだけ様々な調査事項等の候補が挙がっておりますので、増やしていくことに異論、違和感はございません。候補として挙げた中身をしっかり議論するような委員会数、また、適切な議論がしっかりとなされて調査が進むような人数であればいいなと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-018"},{"speaker":"こんの委員","kind":"意見","question":"私としても、全てやるというのは現実的ではないので、その中で私たちの視点も入れていただいているところもありますので、おおむね３ぐらいなのかな。委員数としては、せお委員からもお話がありましたので、今までの１３人という人数から、もう少し分散というか、３つぐらいにするのであれば、当然、委員の数もそれに合わせた考え方でというのは、公明党の意見としてあるかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"最初に言いました、３つなのですけれども、現在１３名で特に不都合はないと思います。一方で、再三指摘されているように、無所属議員もきちんと区民の審判を経て議会に入ってきているわけですから、隔たりなく参加していただくためには、私は減らすというのはないのではないか。全員が入れるような人数にしていくべきだなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"これはすごくいいことだと思っていて、そういう特別委員会になれば、それは本当に重みを増すと思うのです。議会としての活性化につながると思うので、そういう意味からすると、やはり常任委員会的な人数というのが１つの参考になるのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"すみません。最初、１３人という話がありましたけれども、１３人を３つつくるとなると３９人です。でも、無所属の人が入らないとなれば、おのずと人数は分けなければいけないということです。その辺も今まで前例がないのですけれども、どこかで委員長が採決を取らないと駄目になってしまうのですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"よくないと思います。それでしたら、５時のぎりぎりまでやっているのですかと言われると、やっていないのではないですかと思いますので、１３人が駄目だという議論は、私は承服しがたいというのと、そうなりますと、結局、無所属の議員の人が排除されたままになってしまうのではないかというところは危惧されるところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"それで、今、我々区議会としては議会改革をしていこうという、今日も案が出ましたけれども、以前は特別委員会が３つだったのが、委員長、副委員長を１つずつ減らして２つになって、議会改革をしてきました。それが、今回は３つになるということは、我々は、先人が議会改革をしたことを、逆にまた前へ戻して、委員長も副委員長も人数を増やすのです。は委員長が仕切ることになる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-024"}]},{"id":"topic-02","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"西村委員","kind":"提案","question":"私どもからは、国への要望に関しては、５本出させていただきました。そちらからご説明させていただきたいと思いますが、細かいところはぜひ調査票を１つずつご覧いただきたいと思うのですけれども、昨年に引き続き、ふるさと納税に関しては要望し続けなければならないだろうということで、特別区の財政負担を軽減することを要望しております。少子化対策および子ども・子育て施策に対する要望。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-025"},{"speaker":"こんの委員","kind":"質問・要望","question":"１つは、高額療養費制度に関する要望です。その間、いろいろながん患者のご意見など、私ども会派、公明党としてもいろいろなところでお聞きしておりますので、この方たちの意見をよく聞いて、一旦見送りになっておりますが、その先、またこの議論が再開したときに、この高額療養費制度についてはしっかり議論をしていただきたい、柔軟な対応をしていただきたいといった要望が１つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"山本委員","kind":"質問・要望","question":"しながわ未来からは、国への要望が１０件、都への要望が９件ということで、重複しておりまして、合計１１件の要望を挙げしています。こうした状況下において、国民の暮らしを守り、地域経済を下支えする観点から、個人や事業者に対して生活や経営の実態に即した直接的かつ効果的な財政支援および水道・光熱費等の負担軽減に資する支援の強化など、５項目について要望するものです。これは国への要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"クラスの人数を減らす少人数学級や、公立の義務教育諸学校等の教育職員の給与等に関する特別措置法の廃止など、抜本策を求めていくべきだという内容です。最後、８番目は羽田新ルートなのですが、第６回固定化回避検討会の結果に品川区が看過できないと申し入れたことを記しておりまして、２３区に広く影響を与える都心低空飛行ルートの撤回を議会として求めるものとなっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川改革連合は、まず１つ目が、国への要望として、歴史的な物価高により光熱費や物価が高騰し、国民生活に大きな負担を強いていますので、国民生活に直結する光熱費等に対して国に補助していただきたい。２つ目、同じく国への要望として、少子化対策。３つ目、これも国への要望です。４つ目、これは全国市議会議長会を通じて行う要望です。学校教員の人事権と教員給与を東京都から２３区へ移譲してほしい。","respondent":"まつざわ委員長","answer":"それぞれご説明ありがとうございました。意見等があれば、お願いいたします。","voiceIndex":67,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区議会として、これは決して要望していくべきではないと強く言いたいと思います。それと、公明党が訪問介護報酬の引下げ見直しというものを要望項目に挙げたのは、私は重要だと思っているのですが、そもそも、なぜそれを進めたのか、あるいは区議会で上がる住民の請願に対して、何で不採択にしてしまうのかという、少し不可解なところはあるのですが、これは議会としても要望を上げるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-030"}]},{"id":"topic-03","title":"傍聴規則の改正","agenda":"傍聴規則の改正","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"「静粛を旨とし」や「私語の禁止」も、現行で「騒ぎ立てないこと」とあるのですから、わざわざ書き込むということは、私は必要以上の規制を強めることを明文化することになるなと思っています。したがいまして、議会運営委員会に参加していますので、共産党として意見を求められれば、私たちとしては、この原案をこのまま決定することには反対。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"傍聴は、全ての議員や議会全体に関わることなので、私としては、全議員の方々にも意見を聴取することが必要なのではないかなと思っています。期限がいつまでと決まっている。今日決めるというよりも、進め方を丁寧にしていただきたいなと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"我々だったら、大概言われても、あまりびくともしないと思うのですけれども、そういう一般の区民のことを考えたら、やはりここまで書き込んでいて、あと、どうする云々は議長の采配だと思うので、そのような方法でよろしいのではないでしょうかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"ごめんなさい。戻して恐縮なのですけれども、今、少し思いついたのですけれども、我々、予算特別委員会で議会費を全員で賛否を取って議決したわけですけれども、今回、例えば、特別委員会が３つになると、委員長・副委員長の役職手当というものがつくわけです。そうすると、その費用が入っていないことになると思うのですけれども、そうしたら、再度議決するということになるのでしょうか。","respondent":"大澤区議会事務局長","answer":"３つ分の特別委員会の予算を取っていますので、改めての議決は必要ございません。","voiceIndex":91,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7017#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":28869,"voices":94}},{"id":"r07-20250415-6","meetingId":"r07-cm04","date":"2025年4月15日","dateIso":"2025-04-15","committee":"区民委員会","time":"午後 １時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年度 町会・自治会課題解決支援事業報告書","agenda":"令和６年度 町会・自治会課題解決支援事業報告書","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そもそも現在の町会・自治会の加入率は現状どうなっているかというのを分かる範囲で教えていただきたいのと、それと、「３.令和７年度の実施予定」というところで、昨年度は合計６町会だったのが、今度は計８に増えるということなのですけれども、これはやはりこういう支援に対する関心が高いということなのでしょうか。","respondent":"平原地域活動課長","answer":"続きまして、事業者の選定ですが、こちら、プロポーザルを実施いたしまして、その中で一番可能性の高いといいましょうか、効果の高いところを選定させていただいて、現行の会社になったところです。１つ目のところは、大変申し訳ございませんでした。","voiceIndex":16,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"加入率のところ、最新というのはいつの数字なのかというのを後で教えていただきたいのが１つと、今回、３と５で合計８ということなのですが、これはこのプログラムに手を挙げるところというか、希望するところはもっと多いけれども、今年は３町会とか５町会に絞ったということなのか、そこら辺、知りたいなと思って、それを２つ目に伺いたいと思います。","respondent":"平原地域活動課長","answer":"令和７年度、予算的にはこの数でやっていかなければならないもので、手の挙がり方によっては、今後のことはまた検討してまいりたいと考えています。","voiceIndex":18,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問の意図が分からなかったので、伺いたいなと思います。それが１点です。それと同時に、マンションの特に交流が難しいという、住まい方としてそもそも難しいのではないかという、タワーマンションの規制などですね、住宅施策とかまちづくりとの連携というのもどうしても必要になってくるのではないかと思うのですけれども、そこら辺、担当部署としてのお考えを伺いたいなと思います。","respondent":"平原地域活動課長","answer":"希望するところには支援をといったところですけれども、そこはしっかりと対応させていただければと思ってあります。","voiceIndex":20,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は不可分な感じがするので、もちろんどっちも大切だと言いたいので、広い視点を持って、横の連携をとっていただいて、よりそのコミュニティが活性化するまちづくりはどういうことかというのを考えていただきたいなと思います。実際に町会長からも声がいっぱい出ていますし、そしてこの報告書の中にも生の声で出てきているわけですから、そこら辺、お伺いしたいなと思います。","respondent":"平原地域活動課長","answer":"そういった点で、何が課題というよりは、それぞれの状況かなと私では考えているところがございまして、やはり町会でまとまって参加という形になりましたら、目の前にある区立の小学校の方々がまとまって参加とかということが一番分かりやすいのですけれども。","voiceIndex":22,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて、同じようなところで言うと、区内の景況調査について、あれも冊子になっているわけですから、ぜひこのように事業の報告書、事業についてしっかり報告があるわけですから、私は、同じ税金を使ってしっかり事業を行っているという点で、中小企業の景況もぜひ区民委員会で報告していただくようにしていただきたいと改めて思いましたので、意見として述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今お話とかを聞かせていただくと、やはりマンションの方にいかに入っていただくかという部分かなと思うのです。マンションの防災に関してなのですけれども、令和６年度に防災のところでエレベーターチェアを希望するマンションに配布していたと思うのですが、担当が違うかもしれないが、大丈夫ですかね。準備した分は全部、配布は完了したのでしょうか。","respondent":"平原地域活動課長","answer":"令和６年度に防災課で実施いたしましたエレベーター用防災チェアについてですが、３月時点での数字ではたしか３７０基ぐらいの配布だったかと思いますので、予定していた初年度の数量には達しなかったと考えています。","voiceIndex":26,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"やはりアンテナを張って、向こうから品川区の助成だったりとか地域の活動の情報を取りにきて、協力的なマンションもあれば、そうでないところもあるのかなといった感じで、エレベーターチェアの登場の詳細を掲示板に貼ったりして広くやっている管理組合のマンションもあれば、急にぽんと置いてあるだけで、何だろうとなっているようなマンションもありますし、うちのマンションはさらに。","respondent":"平原地域活動課長","answer":"そういったところもありますので、管理組合を中心に、マンションとして防災、例えば備えるためにはどうすればいいかという中で、町会との関わりみたいなものは必要なのですよという情報を、私ども。","voiceIndex":28,"id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"こちらの伴走型支援プログラム、令和４年度からされていますけれども、先ほど伴走型支援を受けたところのフォローアップについての質問がありましたが、今、どれぐらい持続できているといいますか、フォローアップの申請があったとか、継続が重要だなと思うので、過去の、この一、二年の状況みたいなものを簡単にご紹介いただければと思います。","respondent":"平原地域活動課長","answer":"そういったところもあって、継続性が非常に重要だと私どもも認識しておりまして、例えば簡単にアドバイスをすると済むような話から、なかなか課題としては、次の壁が見つかってきたみたいなところというのは、新たな課題として、また別の問題として。","voiceIndex":30,"id":"exchange-008"},{"speaker":"おぎの委員","kind":"意見","question":"ありがとうございました。やはりその回だけで、単回で終わってしまうと、せっかく問題があって取り組もうと思ったのにという部分もありますので、また新たな壁が見つかるとかという部分で、柔軟にご相談に乗っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。要は、区の情報を伝えるために回覧板をやったりとか、区の地域を盛り上げるためにイベントをやったりだとか、何となく地域と行政との関係性が少し、今後どうやっていったらいいのだろうというような不安を持っている方たちも多いと思うので、そういう不安を払拭していただくためにも、伴走型の支援をしていただきたいと思いますが、改めて区のご意見をお聞かせください。","respondent":"平原地域活動課長","answer":"一般のいわゆる地域活動についても全く同じことでございまして、その状況に応じた形で対応していくといったところで、この伴走型支援というのは、まさに委員ご指摘のとおり、始めたものです。個々の悩みに対して、それぞれの課題解決を一緒に考えていきましょうと。","voiceIndex":34,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"距離感があるので、ぜひそこは、特に若い職員の人たちにそういう経験をしていただくことによって、彼らの行政マンとしての成長に大きくつながっていくと思いますので、ぜひその辺をやっていただきたいと思いますし、行政だけではなく、例えば、なぜ今、人がこんなに足りないのか。今、２３区で一番問題になっているのはやはりそこだから。これは要望で終わらせていただきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-011"},{"speaker":"せお委員","kind":"質問","question":"先ほど答弁の中かな、今年度、手を挙げたところが多ければ、選定してみたいな話があったのですけれども、それは予算の関係でと多分おっしゃっていたと思うので、予算はどんなところにかかっているのかなと。専門コンサルタントの人件費なのか。どこが大きいのですか。そこだけ、すみません、最初にお願いします。","respondent":"平原地域活動課長","answer":"コンサルの実働のところですが、ほぼほぼ人件費です。","voiceIndex":38,"id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"だから、予算の関係というのも分かるのですけれども、手を挙げているところはやはり何か助けてほしいのだと思うので、はじかれてしまうところがあると、それは区としてはちょっとあれだなと思ったので、では、入れなかったときにですけれども、何かほかの支援とかはあったりするのか、教えてください。","respondent":"平原地域活動課長","answer":"例えば先ほどもお話が出ましたけれども、地域センターでありますとか、あるいは地域活動課、本課の地域の支援を行っている部署がありますので、そういったところがお話を伺いながら、では今だったらどういったところまでできるのかというのを一緒になって進めすると。","voiceIndex":40,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひそういった形で進めていっていただけたらなと。今もお話がありましたけれども、本当に課題がそれぞれ違うのだろうなというところが私も見えてきたので、このプログラムだけではなく、それぞれに寄り添った支援があればいいなと思っています。それは要望で終わるのですけれども、先ほどお話があった西五反田谷山会の学校選択制のところは、ごめんなさい、これは意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"町会の役割というか課題の中で上位を占めるのは、防犯、防災だと思うのですけれども、その辺、担当の課長にまず大きく伺いたいと思うのですが、地域活動課長は前職が防災課長というキャリアをお持ちですから、町会の中で上位に上がってくる課題の防災という意味を含めて、課が違うからということではなく、やはり防災を含めた地域活動というか。","respondent":"平原地域活動課長、澤邉生活安全担当課長","answer":"そういったところでは、私、防災にある程度携わらせていただいたところですけれども、防災を考える上では、やはり連携というものが非常に重要だと強く思ってきたところでございまして、そういう意味では、以前の。このたび補助金等でそういったところについても手当をしていきたいと考えていますし、そこは丁寧な説明を今後ともしていきたいと思っています。これについては、おおむね好意を持って受け止めていただいています。","voiceIndex":44,"id":"exchange-015"},{"speaker":"藤原委員","kind":"確認","question":"細かく聞いていきますが、さっき、町会の加入率は平均して５５％とおっしゃっていました。つまり、これが現実なのです。町会の魅力を発信するだの云々とあると思うのですけれども、でも、あまり増えていないというのも片やあると思うのですが、これから少なくとも１年間は地域活動課長として町会等の担当をしていくわけですから、その辺の思いというのはどういう思いがあるか、改めてお伺いします。","respondent":"平原地域活動課長","answer":"そういったところで、先ほどマンションの、１棟単位か個別なのかといったところで、お金を払っても自分は入っていた実感がないというところが一番問題だと思っているところもありますので、実際に入って活動していくような端緒をつくっていく、そういうようなきっかけとして。","voiceIndex":47,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"なので、課長が今、地域活動課の課長をやっていて、ありがたいなと思うのです。だからこそ、一番身近な品川区として、課長、入っていただいて、一致団結するような町会づくりをしていっていただきたいという思いで質問させていただいているので、その辺、最後、この１年間は間違いなくやられるわけですから、地域活動課の課長を。効果を出していっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"平原地域活動課長","answer":"そういう視点で、今後、１年かどうかというのはありますけれども、きちんとやっていきたいと思います。","voiceIndex":49,"id":"exchange-017"}]},{"id":"topic-02","title":"なぎさ会館の現状と課題","agenda":"なぎさ会館の現状と課題","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１の（３）のところですけれども、収支状況ということなのですが、令和２年度と令和５年度の歳出が特に多い理由を教えていただきたいというのが１つです。利用料なのですけれども、これは比較できるものなのかよく分からないのですが、臨海斎場や桐ヶ谷斎場と比べてどうなのか、伺いたいと思います。","respondent":"築山戸籍住民課長","answer":"令和３年度のほうが歳出はもっと多いのですけれども、こちらはエレベーター改修を行いましたので、そのため多くなっております。令和５年度ですが、こちらは、照明ＬＥＤ化や空調機の修繕を行ったため、その工事等にかかる経費で増えているというものです。","voiceIndex":55,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"すみません。間違えました。令和３年のところを聞きたかったので、ありがとうあります。そうですね。だから、結構設備投資もしているのではないかと改めて思いました。それと、利用料もやはり安いですよね。伺いたいのは、この廃止方針というのは、事務事業評価でＤだったという話もありますけれども、廃止方針を定めるに当たり、利用者の声というのは現時点で聞いていらっしゃるのか、伺いたいと思います。","respondent":"築山戸籍住民課長","answer":"先ほどご説明したように、減少傾向が続いているというのは、区民ニーズと一致していないところが原因なのではないかというような形で葬祭事業者からも意見はいただいているところですので、そういったところから、結果として、様々な点からＤ評価にしています。","voiceIndex":57,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"資料には、なぎさ会館から近い臨海斎場と書いてあるのですけれども、とは言え、こちらのなぎさ会館から距離は２キロぐらい離れておりまして、私、再三この場でも言っていますけれども、臨海斎場にはアクセス性の課題があって、先ほど紹介したような声の方とかは、地元の地域で、割と近くに行ける距離にあるのが助かっている、だから利用しているのだという声がある中で、臨海斎場がありますから。","respondent":"築山戸籍住民課長","answer":"アクセスの課題につきましては、臨海斎場のほうで令和１２年度に増築を控えておりますので、そこに向けて検討していくと聞いております。組織区としましては、引き続きアクセスについては意見等してまいりたいなと考えているところです。","voiceIndex":59,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"そちらの推進には賛成できないなと述べさせていただきたいと思います。現時点で跡地活用の検討というのはどの程度行っているのか。地域振興部や文化観光スポーツ振興部などで考えている活用ニーズとかだけでもいいので、現在、どういう検討を行っているのかというのを教えてください。","respondent":"築山戸籍住民課長","answer":"跡地の活用についてですが、これからなぎさ会館の廃止についての検討をするところですので、跡地についての検討はまだ行っていない段階です。","voiceIndex":61,"id":"exchange-021"},{"speaker":"石田（し）委員","kind":"提案","question":"私、実は平成２８年に、このなぎさ会館について見直しをするべきだと。私が廃止をするべきだと言ったのは１０年前。だけど、その時点で既に葬儀をされる方たちのニーズも変わってきたし、人口形態も変わってきていたので、臨海斎場もできていたし、なのでそういった提案をしたのです。跡地だったり、どうやって臨海斎場へのルートを確保したりしていくかというほうにぜひシフトしていっていただきたい。","respondent":"築山戸籍住民課長","answer":"そういう状況にもなりますので、廃止につきましてはなるべく早期に、廃止すべきという結論が出るのであれば、そのように進めていきたいと考えております。","voiceIndex":65,"id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私はぜひそっちに向けて検討を進めていっていただきたいし、逆に、先ほど安藤委員が言ったみたいに、今まで使っていた方たちに不便がかかるのだから、その人たちをどうやって支えていくかという部分で、やはりそこで一つ大きいのは、どう見ても交通アクセスなのです。前もこの委員会で臨海斎場の件があったときに、交通アクセスの件はいろいろな委員からお話があった。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-023"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"予算特別委員会のときに、我が会派から、今後丁寧な進め方をということで、議会に対しても、あと区民に対しても進めていくようにと要望させてもらったと思うのですけれども、その際に、検討会については４月以降のスタートと理事者から答弁があったと思います。","respondent":"築山戸籍住民課長","answer":"もし廃止となれば、なるべく早い段階でお伝えすべきだと考えておりますが、その前に、事前に地域の方ですとか葬祭業関係の方のご意見等も聞きながら、廃止というところでの最終的な決定が下りてからの周知となりますので、決まりましたら。","voiceIndex":69,"id":"exchange-024"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"重ねての要望ですけれども、区民への早い段階での周知と、今後の業者が分かるように、ぜひお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"だから、ちょっと似てはいるのですけれども。だから、廃止だけではなく、廃止と抱き合わせに、今後区民が得られる利益というか、利益と言ってしまうとあれですけれども、それを抱き合わせに、セットでお示ししないと、そうすると時間がかかってしまうかもしれないのですが、それぐらいもう検討しておいてほしかったのですけれども、そこら辺はどんな感じのスケジュールなのですか。","respondent":"築山戸籍住民課長","answer":"スケジュールのところで、次の検討につきましては、やはり所管だけでは難しいところがありまして、全庁的なところで、企画部門と共に進めていかなければならないというところですので、ここについてはもうしばらく時間がかかるだろうと考えております。","voiceIndex":73,"id":"exchange-026"},{"speaker":"おぎの委員","kind":"確認","question":"もう皆さん聞いていただいたので、私から１点だけ確認したいのですが、令和８年に臨海斎場のほうが増設されるということで、特にこのオープンを待っているとか、そういうわけではないのですよね。連動はしていないということでよろしいのでしょうか。","respondent":"築山戸籍住民課長","answer":"臨海斎場のオープンに合わせたというわけではなく、あくまで品川区の施設として事務事業評価しておりますので、その中で、区民ニーズですとか実績等を踏まえまして、判断しているものです。","voiceIndex":77,"id":"exchange-027"},{"speaker":"おぎの委員","kind":"質問・要望","question":"そうしますと、期限がこのオープンを待つというわけではないということで、今話に上がりましたアクセス含め、検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"アクセスのことについてお伺いしますが、これ、実はもう２０年ぐらい前から出ているのですよね。今日、答弁はいいですけれども、その話もずっと出ていたではないですか。そういうふうに行く方のやはり要望ですよね。そういうのを解決していくというのが行政なのに、質問も出ている、要望も出ている、でも、解決ってされないのですね。要望も出て、質問も出て、今日もみんなからアクセスをどうするのだと。","respondent":"築山戸籍住民課長","answer":"傾向としては今後もこの小規模葬という傾向になっていくのではないかと思います。そういった今後の葬儀の在り方ですとか形態が変わっているということも踏まえまして、アクセスについても併せて考えていけたらよいかと考えております。","voiceIndex":81,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"私がアクセスという理由は、前回か前々回の委員会で、実は八潮の駅をつくればいいではないですかと。やはり地域は地域なのだなと。２０年前ぐらいの質問・要望で臨海へのアクセスというのは出ているのです。だって、きちんとした選挙で私たちは選ばれているわけですから。きちんと公平・公正な選挙で選ばれているわけですから。課長、もうちょっと前向きな答弁をいただきたいのです。その辺、どうでしょうか。","respondent":"築山戸籍住民課長","answer":"先ほど委員から、ご要望があるということは受け止めております。品川区は臨海斎場の組織区でありまして、運営会議等を通じて意見等は述べていける立場ですので、品川区民からこのような要望が出ているということは臨海斎場には伝えてまいりたいと思います。","voiceIndex":83,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川区民からも出ていたし、所管している区民委員会からもこういう形でほとんどの議員から要望が出ましたという話はしていただきたいし、その辺はしっかり、ずっと、検討します、さっき石田しんご委員が言ったけれども、１０年前から検討しますという話もあったけれども、そんなにすぐできないことかもしれない、でも、あそこまでの距離は本当に大変ですから、ぜひその辺はしていっていただきたいと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-031"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ここの所管に限らず、一般的にどうも品川区、説明が遅いのです。でも、そうではなくて、今検討が進んでいるのは確かなので、検討の段階で、検討が始まっているのであれば、一刻も早く説明会を開くべきだと私は思います。先ほどゆきた委員からのご意見にもその部分があったかなと思うのですけれども、やはり早く、まずは説明していただきたいと思うのですが、いかがでしょうか。","respondent":"築山戸籍住民課長","answer":"地域の方のご意見等をお聞きしながら丁寧に進めていきたいという考え方は、先ほど説明したとおりです。","voiceIndex":87,"id":"exchange-032"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"今のご答弁でも、決定したらということなのですけれども、検討が進んでいるという段階では駄目なのでしょうか。多分紛糾します。でも、それでもやはり早い段階での説明というのは、区民の権利として求めてよいと思いますし、区の責任としては、紛糾したとしても、それはしっかり行って、それこそ誠意を持って説明していくべきだと思うのですけれども、いかがでしょうか。","respondent":"築山戸籍住民課長","answer":"現段階で廃止に向けて検討するというご報告をこの区民委員会でさせていただいているところです。まさに決定前の段階で、このたびご報告をさせていただいているところです。","voiceIndex":89,"id":"exchange-033"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"なので、やはりもう少し早く開いていれば、もう少し穏やかに進められたのではないかなと思いましたし、区民からしてみても、決定前に説明会が開かれたというのは、区の誠意というか姿勢として前向きに受け止めてくださる方もいらっしゃると思いますので、ぜひその辺は早い説明を要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"合理性は一定あると思います。ただ、さらに加えて、今日出たような、今使っているのはどうするのですかとか、あるいは、どうしてもこの施設を転用しなければいけない理由が何かほかにあるのだとか、そういった、区として今回こういうふうに進めていくということをより丁寧に、もっと合理的に、しかも多角的な説明を踏まえて、決定前に、私は紛糾してもいいではないですかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7025#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":31137,"voices":99}},{"id":"r07-20250415-7","meetingId":"r07-cm04","date":"2025年4月15日","dateIso":"2025-04-15","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年陳情第１６号、障害者グループホームの公平公正な入居選考を区に求める陳情","agenda":"令和７年陳情第１６号、障害者グループホームの公平公正な入居選考を区に求める陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"ここにも区立の障害者グループホームは４２名という状況ですし、金子山とか森前が１６人ということなのですけれども、そこも含めての空きが生じた場合に、その入居候補者選定会議にかかるのか、その点をまず教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"陳情のご説明では、新設の出石つばさの家の流れについてご説明いたしました。基本的には空きが生じた場合でも基本的な流れは変わりませんけれども、ただし、新設の場合かなり多数の応募が予想されたために、入居調整指数という指数を用いさせていただいたです。","voiceIndex":18,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"申し込むときに入居推薦願というのを出すことになると思うのですけれども、入居推薦願というのは、一度出すとそのまま待機者ということで、ずっと入れるまで待機者ということでカウントされてその入居候補者選定会議の中にかかっていくのか、高齢者の場合、特別養護老人ホームなどは半年ごとに全部さらにしてもう一回申し込み直しということになりますけれども、そういう仕組みとしては。","respondent":"松山障害者支援課長","answer":"それからあと、入居候補者選定会議の人数ですが、特に人数でこれというふうに決めているわけではないのですが、障害者支援課としては事務局ですので、計画相談事業所から上がってきたものを相談のほうで説明をするという形になっています。障害者支援課が複数名です。","voiceIndex":20,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、これからは区立グループホームを造らないということなので、その調整指数で公平公正に選んでいくという仕組みは、たまに空いた人しか対象にならないみたいなことで、すごく公平公正な選び方ができなくなってしまうのではないかと思うのですけれども、そういう点から言えば、区の土地を使って区も支援をしながら助成金も出しながら建てていくわけですから。","respondent":"佐藤障害者施策推進課長","answer":"その実現のために、入居者の選定については最終的に事業者が行いますけれども、選定方法については区と協議することとしておりまして、先ほど障害者支援課長からの説明の際にもありましたとおり、こちらの入居に係る選定方法については。","voiceIndex":22,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"中度の方と重度の方が同じ指数になっているので、ここのところは３段階にしかなっていないわけですけれども、まだそこの指数を作ってどうするかというところまで行っていないので、私はぜひそこをやっていただきたいけれどもどうかということを伺いたいのと、それからそれをやるとしたら、その障害支援区分というのはもっと細かく分けて。","respondent":"佐藤障害者施策推進課長","answer":"ただ、繰り返しになりますけれども、その入居者の選定につきましては、支援区分も含めまして、先ほどもございましたより困難な状況にある方の受入れ等も踏まえた上で、そういった方がきちんと入れるような形の入居者の選定の仕方につきましては。","voiceIndex":24,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"入居調整指数は設けるというところはまだ言えないということですか。設けるということも検討するということですか。けれども、障害者のこのグループホームの場合は、民設民営の場合は事業者を選ぶということであれば、それでその調整指数についても設けるということも言えないということになると、公平公正がどう担保されるのかというのはどう考えるのか、その点も伺いたいと思います。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"ただ、既存の事業所になりますこちらの陳情書にも上っております金子山ですとか森前の部分も含めまして、最終的には事業者のほうで選定しているところになりますので。同じになります。障害者の場合は、区内に区立１か所、それから民間が１か所、計２か所の入所施設がございまして、入所施設の場合はこの選定会議を活用しておりますので、高齢者と同等のものを行っているという認識です。","voiceIndex":26,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私はもう少し、これだけ切実な思いでグループホームが求められているときに、それで絶対数が足りないというのが一番の問題なのですけれども、そこのところで絶対数が足りない中で、ではこれだけの希望者がいる中で、それを公平公正にどう選んでいくのかというところが問われると思いますので、少なくとも新規受入れのところに対しては。","respondent":"佐藤障害者施策推進課長","answer":"今、委員がおっしゃっていただいた支援区分の高い方の入居も含めて、次期の障害福祉計画等も絡めまして、そういったところの整備の計画をしまして、今後、支援区分の高い方、重度の方等の受入れが進むようなところについては検討を進めてまいりたいと思います。","voiceIndex":30,"id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問・要望","question":"グループホームの公平公正な入居選考を求める陳情につきまして、この趣旨のところを見ていくと、区が整備または無償貸付など区が介入している事業者については、しっかりと区が責任を持って希望する方々が入れるように、さらに透明性のある入居選定をしてほしいというような趣旨だと理解しています。お聞かせください。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"グループホームの入居の利用者、もしくは利用希望者ですけれども、１つは障害福祉計画の中で利用見込み等を確認しまして、そういったところを含めて利用者の見込みは出しているところがあります。そのほか地域移行、地域生活の移行のために入所施設の全員に調査を行いましてご希望を伺ったところ、１９人の方が地域移行のご希望があったということです。その方を合わせると６９人ということになります。","voiceIndex":32,"id":"exchange-007"},{"speaker":"ひがし委員","kind":"意見","question":"しっかりと全体像の把握をして、これから整備をするということで、今、全員で８６名希望されている、まだ入れていない方がいると認識をしています。","respondent":"松山障害者支援課長","answer":"それからもう一点、今回だからということではなくて、通常、日頃からケースワーカーのほうでやはりどこに入所したい、あるいはどこに通所したいというご希望は、計画相談員を通じて行っておりまして、相談員とケースワーカーが連携してできる限りご希望に沿えるように。","voiceIndex":35,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"確認","question":"先ほどのお話だと、入居者の氏名が区に戻ってきて、区の名簿にあるかを確認して、名簿にあれば大丈夫だったという判断というお話があったと思うのですけれども、多分恐らくこの陳情を出されている方は、それではなくて、もっと何で入れなかったのか、自分よりも状態が軽い方が入っていたその理由とかが透明化されていなくて。","respondent":"松山障害者支援課長","answer":"ただ指定管理者へは、例えばお問合せがあった場合、なかなかご希望に沿えなかったということでお問合せがあった場合については、指定管理者から理由を説明しています。","voiceIndex":37,"id":"exchange-009"},{"speaker":"ひがし委員","kind":"確認","question":"区が細かい情報のところの共有は今のところされていなくて、どの方が決まったのかっていうところまでしか分からないという形だと思うのですけれども、それでいくと、この陳情に書かれている、実際に選定が適正に行われていることを確認しているというところが、どのように確認したのかなと、この陳情者が言っているのが私もすごく分かるなと思うのですけれども、正しく行われているかのその判断。","respondent":"松山障害者支援課長","answer":"やはり区が建てたものですので、そのような形の優先順位区分ということにしております。推薦名簿を確認しているので、特にその間で比較を区ができるかと申しますと、なかなか実際には難しいところがあります。","voiceIndex":39,"id":"exchange-010"},{"speaker":"ひがし委員","kind":"確認","question":"先ほど言った入居候補者選定会議の中でしっかりと把握をして、名簿化をしていて、そこの名簿にするときにランク付けをしているから、その下のほうの方々というか、区の中でこの方々を入れてほしいという人たちが優先的に入れているというのを確認できているということですか。","respondent":"松山障害者支援課長","answer":"あくまでも入居候補者選定会議の中では、書面での確認でしか、限界はそこまでしかないというところでございまして、実際にお会いして確認しているわけではないですので、それが全てではないですけれども、あくまでも多数の応募の中から、ではどの方から面接するかと言ったときに。","voiceIndex":41,"id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問・要望","question":"分かりました。そこで言うと、区が言っているその名簿を作って、今度その優先順位が高い方から面談してくださいというふうな意向があって、事業者側もそれにのっとって面談をしてくださっている。これは要望にとどめます。何かあればご回答もお願いできればと思います。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"ご納得いただけるような理由というのがなかなか難しいところですけれども、個別のお問合せにつきましては、事業所が丁寧に対応していると聞いております。今後の整備につきましては、先ほどのお話のとおり、需要量の精査等も踏まえて進めていくところですし、また、直近で予定されているこの整備案件につきましても、入居の選考にあたりましては。","voiceIndex":43,"id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問・要望","question":"しっかりと現場の声を聞いて、例えば入れたいのだけれども、入れられない理由がきっとお金の面だったりとかあるのかなというか、職員が足りなかったりとか、そういうところは区がしっかりとサポートを引き続き連携して行っていただきたいなというのは、最後に要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"その４か所のうちの３か所分が日中サービス支援型というふうなことを区が誘導して造り、そしてその日中サービス支援型ということであれば事業所の経営がすごく大変になるので、職員配置とか経営の支援も含めた支援をしていくというのを要綱で決めて支援をしていくという方向が出されているのですけれども。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"事業者が整備等を進めるにあたっては現在補助金等も設けているところですが、そういった部分についても類型の区別でそういったところ、金額等に差をつけているものもございませんので。私から、中・重度の入居者の支援区分に応じた運営費助成を今年度開始いたしましたので、できる限りＰＲをさせていただきまして、中・重度の受入れを既存の事業者で進めていただくとともに、他区からも。","voiceIndex":47,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのように誘致するときに用地の確保というのはすごくやはり一つの大きな課題になってくると思うのですけれども、世田谷区のホームページを見ましたら、世田谷区ばかり紹介してあれなのですけれども、土地を提供してくださる方はご協力くださいみたいな、そういうチラシも作って、かなりいろいろな施設に対してやっていますけれども、障害者グループホームについても、こういう土地を区としては求めています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"これは、この陳情者にとってそれは良いことではないというところで、品川区の入居選考の公平性がなかったり、公正性がなかったりという指摘なのだというふうに読んで、ですので、品川区が考える公平公正な入居選考というのは、ずっと今までの質疑で何となく理解はできるかなと思うのですけれども、改めて品川区が考えるこの障害者グループホームの公平公正な入居選考の考え方を。","respondent":"松山障害者支援課長","answer":"幾つもの複数の目で確認をしておりますし、また入居後も契約に基づいてサービス提供がなされる、その中で契約の説明も行われているというところで、お互い双方合意の下にサービスが提供されているところを区としては確認をしているという流れについて。","voiceIndex":51,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、また公平公正な選考と言うからには、制度ご利用者が関わっているものですし、増えていけばまた選考の方法ももしかしたら見直しが必要な時期もあるかなと思いますので、そこら辺も含めて、さらに公平性・公正性を高めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-017"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"それで、中・重度がどうしてもこれまでも少ないという話もあって、中・重度は今回その金額も、運営に対して支援をしてくださるということもやっていただいている。１３９m2でできるわけだから、それを探してと言う話をさんざんしてきている話なので、そこはやはりそういうのを、それは今回の陳情とは違う話だけれども、それもぜひ加味していただいて今後やっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。ただし、ずっと申し込みをしているのに入れず不安を抱えている方がいるということは現状を受け止めて、透明性のある入居選考の仕組みの強化と、重度の方々が狭き門になっているとしたら、入れるような仕組みというのを区でこれからも強化していただくように要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すということで、趣旨採択でお願いしたいと思います。それから、そもそも絶対数が足りないということがこういう大きな問題になっているということなので、所要量をしっかり出していただいて、それの具体化、そして運営が成り立つ助成も含めて、グループホームの拡充に取組を進めていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。けれども、ただし公平公正な選考ではないと疑われないように、引き続き客観性・透明性の確保には努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問","question":"様々区から答弁いただきまして、入居候補者選定会議で様々な方と公平な選考をされているというようなお話もあって、さらに指定管理者等も含めて面談があったり、いろいろなことで逆に確かに機械的にやり過ぎないことによって利点も出ているというのは非常に理解できまして、公平な取組をされてらっしゃるのかなということは非常に分かった上なのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-022"}]},{"id":"topic-02","title":"の順番を入れ替えて、(2)東品川三丁目における都有地（品川消防署東品川出張所跡地）を活用した認知症高齢者グループホームの整備","agenda":"の順番を入れ替えて、(2)東品川三丁目における都有地（品川消防署東品川出張所跡地）を活用した認知症高齢者グループホームの整備","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"ここで東京都から品川区が定期借地で借り受けるということなのですけれども、その借地料というのは幾らぐらいかというのが分かれば教えていただきたいのと、その借地料というのはどのように決められるのかも伺いたいと思います。","respondent":"東野福祉計画課長","answer":"借地料ですが、都の要綱に基づきまして減額率が適用される、通常ですと通常価格から５０％減額というような制度となっております。まだ具体的な金額等については示されておりませんので、今後東京都と協議をするという形になります。","voiceIndex":68,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"民設民営、なぜ区立のグループホームで指定管理者というふうにはしないのか、その理由と、それからあと民設民営にする場合、その土地代というのは無償でその事業者に提供するのか、その点も伺いたいと思います。それから、施設整備費の補助というのが都の補助制度と区の上乗せ補助というのがありますけれども、これは具体的にどのようなものなのかも伺いたいと思います。","respondent":"東野福祉計画課長","answer":"それから区の補助につきましては、最大で３ユニットになりますので、２,２５０万円ということで、合計で２億２,６２０万円ほど補助が出るという見込みです。これは最大でという形になります。","voiceIndex":70,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"意見","question":"そうすると、その土地代というのは、東京都から借り受けたその土地代は丸々区の負担・持出しはなくて、事業者で払ってもらうみたいな形での事業者負担になるのかということと、この東京都の補助制度と品川区の補助制度で、合わせて建設費用の何％ぐらいが賄えることになるのか、おおよそ分かったら、その点もお聞かせください。","respondent":"東野福祉計画課長","answer":"施設につきましては、こちらの土地でいきますと大体４階建てぐらいが想定されておりまして、こちら２億２,０００万円ほどの補助になりますと、かなり大きなウエイトでの補助ということになろうかと考えています。","voiceIndex":72,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"そもそも論になるかと思うのですけれども、いろいろな福祉施設があると思うのですけれども、この場所を認知症高齢者グループホームにしようと思ったその理由を教えてください。地域バランス的なこともあったのかなと思うのですけれども、その辺り、今回認知症高齢者グループホームを整備する理由を教えてください。","respondent":"東野福祉計画課長","answer":"他の地区を見ますと、多いところでは３施設であったり、１施設、２施設ということで、区内では全部で１４施設あるのですけれども、こちらの地区には全くないというような状況を踏まえまして、認知症高齢者グループホームとして、区として手を挙げたものです。","voiceIndex":74,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。では、そうしたこの品川地域になかったので、用地が空いたら、大体区としては認知症高齢者グループホームを造ろうと、もう前々から結構お考えがあったということでよろしいですか。","respondent":"東野福祉計画課長","answer":"今回、大きさ的に約５００m2弱ぐらいというところになるのですけれども、認知症高齢者グループホームを造るにあたりましては、それなりの大きさ・広さが必要となりますので、大体このぐらいの土地を区内全域でくまなくアンテナを張って。","voiceIndex":76,"id":"exchange-027"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"１点だけ。本当に品一、品二地区には初めてできるので、大変ありがたいと思っています。そうすると残りが５５８m2なのですね。それだったら極端なことを言えば一部５階建てでも、それでもしそれを上に持っていくのなら４階、５階で一部そういうのをやれば、かえって４階、５階のほうがうまくやれるなどという感じがあるのだけれども、そういうことも含めて提案してくれということで理解しておけばいいのか。","respondent":"東野福祉計画課長","answer":"今、石田秀男副委員長のほうからもお話ありましたとおり、１ユニット定員９名ということになりますと、それなりのフロアの広さが必要となりますので、現在想定で考えているのが４階建て、１フロアやはり約２８０m2ということで考えているものです。","voiceIndex":78,"id":"exchange-028"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"増えた平米数の費用ぐらいで、それが一気に６階建て以上だとまた違ってくるけれども、それであるならば、さっき言った５５８m2を２つで割っても２８０m2の２つぐらいはあるわけだから、一部５階というのは非常にできる可能性はあると思っていて、そういう有効活用が非常にいいと思うので、検討していただければなと、提案でそういうのが出てくれば、そういうのも検討していただきたいと思うのが１点と。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、今この建設予定の用地のところというのは、駐車場と更地になっているところでよろしいですか。","respondent":"東野福祉計画課長","answer":"つい最近までは駐車場として使用していたようですけれども、現在は更地になってあります。","voiceIndex":81,"id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"となると、恐らく用地の奥に雨宮産業という会社があって、大きい道路からちょうど車１台より少し余裕があるぐらいの細い道があって、雨宮産業というような感じになっているので、そこの細い道に関してはもちろん雨宮産業で、これから借り上げる土地ではないということでよろしいですか。","respondent":"東野福祉計画課長","answer":"そこに通じる通路がありますので、そちらの部分についてはあくまでも東京都から借りるものではなく、その通路部分につきましては、現在そちらの雨宮産業のほうで使っておりますので、当然空けてというような形になります。","voiceIndex":83,"id":"exchange-031"}]},{"id":"topic-03","title":"「品川区生活困窮者住居確保給付金の支給に関する規則の一部を改正する規則」の概要","agenda":"「品川区生活困窮者住居確保給付金の支給に関する規則の一部を改正する規則」の概要","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"住居確保給付金の拡充ということですけれども、基本的に住居確保給付金が受けられる人が、この拡充した制度も受けられるということで考えていいのでしょうか。それと、住居確保給付金を受けている方は今何人くらいいるのか、伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"拡充された、国がそうした内容ですが、いわゆる住居確保給付金というか、家賃が高い人で家賃が払えなくなってという人が、家賃がそうなってしまったときにはもう転居する費用すらもうないというところから。","voiceIndex":90,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問","question":"そういうことで言うと、暮らし・しごと応援センターに相談に来た人に相談員が案内するというのが使われる制度になっていくのかなと思うのですけれども、そういうことなのか、その点についても伺います。","respondent":"豊嶋生活福祉課長","answer":"と言いますのは、この家庭改善支援、現在生活困窮者というか暮らし・しごと応援センターにお金がちょっと困っていますという相談に来る方に、家計改善プログラムというのがありましてということでご説明するのですが、やはりお財布の中身を一つ一つ確認をしていって。","voiceIndex":92,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"意見","question":"周知というところでは、暮らし・しごと応援センターが、生活保護の対象にならないという方は、私は暮らし・しごと応援センターでかなりいろいろな方が相談に乗っていただいて、支援をしていただいているのですけれども、そこのところで暮らし・しごと応援センターがちょっと入ったところで、私は看板をもっと大きくしてほしいということでずっと言ってきたのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-034"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回拡充ということなのですけれども、それ以前はどのような支給要件だったのですか。","respondent":"豊嶋生活福祉課長","answer":"これが最大３か月まで支給できますよというのがもともとの制度だったのですが、いろいろなコロナ等々を経て、３か月が延長、再延長ということで期間は増減があったりはしたのですけれども、基本３か月だけもらえる。","voiceIndex":95,"id":"exchange-035"}]},{"id":"topic-04","title":"「しながわ健康プラン２１（第二次）」素案に係るパブリックコメントの実施結果および同計画の策定","agenda":"「しながわ健康プラン２１（第二次）」素案に係るパブリックコメントの実施結果および同計画の策定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことからすると、せっかくつくったこの計画を、説明会を開いてパブリックコメントをもっと増やしていくというようなところにつなげていただきたいなと、そしてまた説明会を行うことが意識の啓発にもなるし、またこれを生かすということにもつながっていくのではないかという思いがするのですけれども、その点についても伺えたらと思います。","respondent":"勝亦健康課長","answer":"パブリックコメントをやるにあたって、計画の説明会を実施すべきではなかったかということで、パブリックコメントのほうは終了してしまいましたので、今後より多くの方にこの計画を知っていただきご理解いただき、周知啓発していくために、様々な機会を捉えて。","voiceIndex":102,"id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうですね。ぜひパブリックコメントというのが私はすごく良い機会だと思うのですけれども、さらにそれを踏まえた形で、それでも結構ご意見がいただけてよかったとは思っているのですけれども、それを踏まえた形で、こういう形でさらに作られましたので、この作られたしながわ健康プラン２１というところでは、区民に知らせていくという場面をぜひともつくっていただきたいということで、要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"今回しながわ健康プラン２１、改定をされようとしていますけれども、私が委員会とかで要望させていただいた飲酒の件とか、座りっ放しによる健康リスクということも記載されているのですけれども、改めてこの飲酒のリスクと座りっ放しの健康リスクを記載した理由はどうでしょうか。","respondent":"勝亦健康課長","answer":"そういった部分でも、また座りっ放しにつきましても、近年、座りっぱなしの健康への悪影響といったものが話題に出てありますので、そういったものはできるだけ新しいものを取り入れた形で、区民の方にも分かりやすく伝えられるようにということで取り上げさせていただきました。","voiceIndex":105,"id":"exchange-038"}]},{"id":"topic-05","title":"「品川区がん対策推進計画（第二次）」素案に係るパブリックコメントの実施結果および同計画の策定","agenda":"「品川区がん対策推進計画（第二次）」素案に係るパブリックコメントの実施結果および同計画の策定","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"先ほどと同じなのですけれども、本当にこれだけせっかくつくられた計画が４件というのは、私はすごく少ないのではないかと思うのですけれども、区としてこれはどう捉えられているでしょうかということと、このがん対策推進計画というのは、今後どのように活用されていくのか、その点も伺いたいと思います。","respondent":"勝亦健康課長","answer":"ただ、そういった中で貴重なご意見、かなり丁寧なご意見をいただいておりますので、４件ではありますけれども、区民の方の貴重なご意見はいただけたのかなと考えています。","voiceIndex":112,"id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう本当にがんは周りの人の多くががんになってつらい思いをしているというところを実感しない人はいないというぐらい、がんがやはり２人に１人と言われるような状況なので、これはもっと本当に、せっかくこれだけの計画をつくったので、それが生かされるような形で、これもぜひ計画のときには説明会をそういう形でもやっていただきたいということは、改めてこれは要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-040"}]},{"id":"topic-06","title":"「品川区自殺対策計画中間改定」素案に係るパブリックコメントの実施結果および同計画の策定","agenda":"「品川区自殺対策計画中間改定」素案に係るパブリックコメントの実施結果および同計画の策定","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"先ほどとも同じなのですけれども、この２件というのはいかんせんちょっと少ないのではないかと思うのですけれども、このパブリックコメントを受け付けるための区の取組というのは、どのようなことをされたのかを伺いたいのと、それからそれを踏まえた形で、きちんとしたこういう計画が策定されたわけですけれども、これをどのように今後活用していくのか、その点も伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"ただ、やはりなかなかその辺が難しいところかなとは思っておりますが、様々な機会を通じてやはり普及啓発に努めていって、もう少しいろいろな意識を持っていただくことが大切かなと考えていますので、普及啓発に努めてまいりたいと思っているところです。","voiceIndex":121,"id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点では、こういう取組を区としてもやっていきますよというところでの計画をぜひとも知らせていくような、そういう取組というのも、私は説明会をまたこの点でも希望しておきますけれども、ぜひ活用して取組を進めていただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"パブリックコメントに関連してなのですけれども、品川区自殺対策計画以外でも、今日出たしながわ健康プラン２１とか、品川区がん対策推進計画についてもありますけれども、パブリックコメントは原則３０日以上だったと思いますけれども、今回品川区自殺対策計画については、年末ということもあったと思うのですけれども、３０日取っていないということと。","respondent":"五十嵐保健予防課長","answer":"私も品川区のやり方を完全に分かっているわけではないのですけれども、今回健康プラン等の計画のほうと大体同じ時期に重なりまして、うちの計画のほうもお正月を含んだ期間で、パブリックコメントは一緒なのかなと思っていましたら。","voiceIndex":124,"id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"保健予防課だけの問題ではないと思うので、パブリックコメントの期間というのはもう少し丁寧に、区としても期間を延ばすなり丁寧に区民の声を拾っていただきたいという思いでおりますので、ぜひよろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-044"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"今の話なのですが、せっかく副区長もいらっしゃるので、戦略広報という名前もつけてやっていらっしゃるので、ちょっと横串を刺していただいて、２件、４件は少ないと思います。やはりそこはもう少しどのようにしたらいいのだということは、パブリックコメントは必ずこれからもあるのでしょうから、これはこれで終わりにして、ぜひそこら辺は検討していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほど鈴木委員との質疑の中で、パブリックコメントが少なかったことに対して、自殺対策が自分に関わることだという回答が２５％で低かったというお話だったのですけれども、２５％でも低いという実感で区としてはお考えなのでしょうか。","respondent":"五十嵐保健予防課長","answer":"２５％という数字だけ聞けば、それなりの数かなというところもあるのですけれども、やはりどこまで関心を持たれている方がいるのかなというところもありますし、やはりなかなか自殺という話は身近な方にもできなかったりとかいう部分もありますので。","voiceIndex":128,"id":"exchange-046"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"このアンケートの中で、実は「分からない」と「無回答」が合わせて大体２０％ぐらいあるのですね。それを除いた中でパーセンテージを取ると、「そう思う」、「どちらかと言えばそう思う」というのが３２％ぐらいになるのです。だからつまり２５％よりも、さらに実は７％ぐらい多分実態的には多いのだなと思うし、この数字というのはやはり私は明らかに多いと思う。何かあればお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-047"}]},{"id":"topic-07","title":"品川区立八潮南特別養護老人ホーム等の増改築工事の進捗","agenda":"品川区立八潮南特別養護老人ホーム等の増改築工事の進捗","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"そうすると、以前、特別養護老人ホームを建てるときにはそういうのは全然問題にならなくて、特別養護老人ホームのところの地面は大丈夫だったけれども、校庭のところに汚染土が出てきたということなのでしょうかというところを伺いたいと思います。","respondent":"長尾施設整備課長","answer":"既存の建物で、今特別養護老人ホーム等で使っているところにつきましては、もともと建物が建っていた校舎の用途を変更して使っておりますので、そのときは今回の増築工事のように土を掘ってというようなところは基本的には発生しておりません。","voiceIndex":136,"id":"exchange-048"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"これはちょっと教えてほしいのだけれども、これは結構大変なことだと思っているのです。これは、例えば昭和５０年代の埋立てというのはこのようなものだったのかというのが一つ。そのときに、このように校庭全部から出てくるということがあったらほかのところも出てくるわけだから、６９棟もしっかり建てられたのかと思うではないですか。それをどうお考えですかというのだけ聞きたいです。","respondent":"長尾施設整備課長","answer":"今回の件があった上で、今後どう建替え等をするときに捉えるかというところですが、今回の工事につきましても、事前の調査、地盤調査であったり土壌汚染の調査というところは、基準にのっとって一定しておりますが、今回のようなことが発生しておりますので。","voiceIndex":139,"id":"exchange-049"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"ガラというよりも、土壌汚染のほうが大変だと思うのです。杭は深くまで行っているから、ではそれをうまく生かそうとか、いろいろな考え方ができるではないですか。全部そのようなものが出てきたら大変なことだと思うのですけれども、それはどうお考えですか。軽く簡単に調査しますと言いましたけれども。","respondent":"長尾施設整備課長","answer":"今回汚染が見つかった土についても、その敷地の範囲の一定の深さまでの土を全て入れ替えるというわけではなくて、今回で言いますと建物の基礎が深さ二、三ｍぐらいまで入りますので、そこまでの土と、あとはその杭を刺しますので。","voiceIndex":141,"id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"汚染土がフッ素ということなのですけれども、教えていただきたいのですが、フッ素が地中に埋まっていたりとか、こういったことで健康に与える影響というのはどういったことが考えられるのですか。","respondent":"長尾施設整備課長","answer":"この基準値というのも相当厳しい基準値が出ていまして、人が一生涯、７０年と設定されているようなのですけれども、一生涯に摂取し続けるようなところで、その人体への悪影響があるというところで基準が設定されておりますので、短期間のうちに多少接触したからといって。","voiceIndex":144,"id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問","question":"そうなると、現在も希望の日数が通えないという状況があると思うのですけれども、医療的ケアの方がもっと受け入れられるような、心身障害者福祉会館ですとかぐるっぽとかで受け入れられるような、そういう状況も検討が必要ではないかと思うのですけれども、いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"直ちに他施設のほうでの対応というのはなかなか難しい状況ではありますが、現在の利用者であるとか、またはその利用を希望されている方等につきましては、現状のニーズを確認等させていただいて。","voiceIndex":146,"id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこは送迎がなかったりするところもあって、家族が送迎をしなければならない、またそこは経済的にも負担がかかるという状況もありますので、今年はもう高校を卒業した方がそういう形で他区のほうに行っているという状況はあると思うのですけれども、来年も再来年もそういう卒業してくる方がどれぐらいいらして、その方々が通える受皿というところは。","respondent":"松山障害者支援課長","answer":"４月から、もう来年度卒業される方の情報を特別支援学校の進路担当の先生方と情報共有を今図っておりまして、実際に個別対応になりますので、その方々がどの施設をご希望されているのか、これまで実習されたところもありますので、実習先、あるいは今年度また実習もありますので。","voiceIndex":148,"id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思います。区内に通える場所がないために、近隣区に通わざるを得ないという状況が実際に起こっているということですので、区内での受け皿というところでの拡充を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7023#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":44604,"voices":154}}]);
